# ===== END TRADE SOURCE =====

def _extract_trade_source(trade_name):
    """현재 PY 파일의 해당 공종 평문 소스 블록을 읽습니다."""
    marker = f"# ===== TRADE SOURCE: {trade_name} ====="
    end_marker = "# ===== END TRADE SOURCE ====="
    collecting = False
    result = []
    with open(os.path.abspath(__file__), "r", encoding="utf-8") as f:
        for raw in f:
            line = raw.rstrip("\n")
            if line == marker:
                collecting = True
                continue
            if collecting and (
                line == end_marker or line.startswith("# ===== TRADE SOURCE:")
            ):
                break
            if collecting and line.startswith("#|"):
                result.append(line[2:])
    return "\n".join(result) + "\n"


def _load_fonts():
    font_dir = os.path.join(os.getcwd(), "프로그램 내장 폰트")
    if not os.path.isdir(font_dir):
        return
    for filename in os.listdir(font_dir):
        if filename.lower().endswith((".ttf", ".otf")):
            try:
                ctypes.windll.gdi32.AddFontResourceExW(
                    os.path.join(font_dir, filename), 0x10, 0
                )
            except Exception:
                pass


_load_fonts()

