master_root = tk.Tk()
master_root.title("서울대학교 감리 자동산출 프로그램_최종본107")
master_root.geometry("1100x900")
master_root.configure(bg="white")

current_login_mode = None
active_trade = None
trade_instances = {}

login_frame = tk.Frame(master_root, bg="white")
selection_frame = tk.Frame(master_root, bg="white")

def _center_window(win):
    win.update_idletasks()
    w = win.winfo_width()
    h = win.winfo_height()
    sw = win.winfo_screenwidth()
    sh = win.winfo_screenheight()
    x = max(0, (sw - w) // 2)
    y = max(0, (sh - h) // 2)
    win.geometry(f"{w}x{h}+{x}+{y}")

def _show_selection():
    login_frame.pack_forget()
    selection_frame.pack(fill="both", expand=True)
    master_root.title("서울대학교 감리 자동산출 프로그램_최종본107")
    master_root.deiconify()
    master_root.lift()
    _center_window(master_root)


def _return_to_selection():
    global active_trade
    if active_trade in trade_instances:
        ns = trade_instances[active_trade]
        try:
            ns["root"].withdraw()
        except Exception:
            pass
    active_trade = None
    electric_var.set(False)
    communication_var.set(False)
    fire_var.set(False)
    _show_selection()



# ===== 최종본107 화면동일형 엑셀 내보내기 패치 =====

def _v71_walk_widgets(parent):
    """parent 아래의 모든 위젯을 재귀적으로 반환합니다."""
    result = []

    try:
        children = parent.winfo_children()
    except Exception:
        return result

    for child in children:
        result.append(child)
        result.extend(_v71_walk_widgets(child))

    return result


def _v71_widget_option(widget, option, default=None):
    try:
        return widget.cget(option)
    except Exception:
        return default


def _v71_to_excel_color(widget, color_value, default="FFFFFF"):
    """Tkinter 색상명을 Excel용 RRGGBB 값으로 변환합니다."""
    if color_value in (None, ""):
        return default

    value = str(color_value).strip()

    try:
        if value.startswith("#"):
            value = value[1:]

            if len(value) == 3:
                return "".join(ch * 2 for ch in value).upper()

            if len(value) == 6:
                return value.upper()

            if len(value) == 12:
                return (
                    value[0:2] +
                    value[4:6] +
                    value[8:10]
                ).upper()

        red, green, blue = widget.winfo_rgb(value)

        return "{:02X}{:02X}{:02X}".format(
            red // 256,
            green // 256,
            blue // 256
        )

    except Exception:
        return default


def _v71_is_descendant(widget, parent):
    current = widget

    while current is not None:
        if current == parent:
            return True

        try:
            current = current.master
        except Exception:
            return False

    return False


def _v71_is_excluded(widget, excluded_roots):
    for excluded in excluded_roots:
        try:
            if widget == excluded or _v71_is_descendant(widget, excluded):
                return True
        except Exception:
            pass

    return False


def _v71_is_managed(widget):
    """
    실제 화면 레이아웃에 포함된 위젯인지 확인합니다.

    스크롤 캔버스 밖에 있어 현재 보이지 않는 위젯도 manager가 존재하면
    전체 화면 구조에 포함된 것으로 처리합니다.
    """
    try:
        if not widget.winfo_exists():
            return False
    except Exception:
        return False

    try:
        manager = str(widget.winfo_manager()).strip()
        return manager != ""
    except Exception:
        return False


def _v71_relative_position(widget, root_widget):
    """
    widget의 좌표를 root_widget 기준 좌표로 변환합니다.
    """
    x = 0
    y = 0
    current = widget
    safety = 0

    while current is not None and current != root_widget and safety < 200:
        safety += 1

        try:
            x += int(current.winfo_x())
            y += int(current.winfo_y())
            current = current.master
        except Exception:
            break

    return x, y


def _v71_reset_canvases(parent):
    """스크롤 위치 때문에 좌표가 어긋나지 않도록 캔버스를 맨 위로 이동합니다."""
    try:
        widgets = [parent] + _v71_walk_widgets(parent)
    except Exception:
        widgets = [parent]

    for widget in widgets:
        try:
            if widget.winfo_class() == "Canvas":
                try:
                    widget.xview_moveto(0)
                except Exception:
                    pass

                try:
                    widget.yview_moveto(0)
                except Exception:
                    pass
        except Exception:
            pass


def _v71_widget_text(widget):
    """화면 위젯의 실제 표시값을 읽습니다."""
    try:
        widget_class = widget.winfo_class()
    except Exception:
        return ""

    # Entry 및 ttk.Entry
    if widget_class in ("Entry", "TEntry", "TCombobox", "Spinbox"):
        try:
            return widget.get()
        except Exception:
            return ""

    # Text 위젯
    if widget_class == "Text":
        try:
            return widget.get("1.0", "end-1c")
        except Exception:
            return ""

    # 체크박스
    if widget_class in ("Checkbutton", "TCheckbutton"):
        text = str(_v71_widget_option(widget, "text", "") or "")
        variable_name = _v71_widget_option(widget, "variable", "")

        selected = False

        if variable_name:
            try:
                value = widget.getvar(variable_name)
                selected = str(value).lower() in (
                    "1", "true", "yes", "on", "o"
                )
            except Exception:
                selected = False

        return ("☑ " if selected else "☐ ") + text

    # 라디오버튼
    if widget_class in ("Radiobutton", "TRadiobutton"):
        text = str(_v71_widget_option(widget, "text", "") or "")
        variable_name = _v71_widget_option(widget, "variable", "")
        radio_value = str(_v71_widget_option(widget, "value", ""))

        selected = False

        if variable_name:
            try:
                current_value = str(widget.getvar(variable_name))
                selected = current_value == radio_value
            except Exception:
                selected = False

        return ("● " if selected else "○ ") + text

    # Label, Message, Button, Menubutton 등
    try:
        return str(widget.cget("text"))
    except Exception:
        return ""


def _v71_widget_background(widget):
    """
    readonly Entry의 readonlybackground를 우선 적용하고,
    그 외에는 bg/background를 적용합니다.
    """
    try:
        state = str(_v71_widget_option(widget, "state", "")).lower()

        if state == "readonly":
            readonly_bg = _v71_widget_option(
                widget,
                "readonlybackground",
                None
            )

            if readonly_bg:
                return readonly_bg
    except Exception:
        pass

    background = _v71_widget_option(widget, "background", None)

    if not background:
        background = _v71_widget_option(widget, "bg", "white")

    return background or "white"


def _v71_widget_foreground(widget):
    foreground = _v71_widget_option(widget, "foreground", None)

    if not foreground:
        foreground = _v71_widget_option(widget, "fg", "black")

    return foreground or "black"


def _v71_font_info(widget):
    """
    Tkinter 글꼴을 Excel 글꼴 정보로 변환합니다.
    """
    info = {
        "name": "맑은 고딕",
        "size": 9,
        "bold": False,
        "italic": False,
        "underline": None,
    }

    try:
        import tkinter.font as tkfont

        font_value = widget.cget("font")
        actual = tkfont.Font(font=font_value).actual()

        family = str(actual.get("family", "")).strip()

        if family:
            info["name"] = family

        size = actual.get("size", 9)

        try:
            size = abs(float(size))
        except Exception:
            size = 9

        if size <= 0:
            size = 9

        info["size"] = size
        info["bold"] = str(actual.get("weight", "")).lower() == "bold"
        info["italic"] = str(actual.get("slant", "")).lower() == "italic"

        if bool(actual.get("underline", False)):
            info["underline"] = "single"

    except Exception:
        pass

    return info


def _v71_widget_alignment(widget):
    """
    Tkinter anchor/justify를 Excel 정렬로 변환합니다.
    """
    anchor = str(_v71_widget_option(widget, "anchor", "center")).lower()
    justify = str(_v71_widget_option(widget, "justify", "center")).lower()

    if "w" in anchor or justify == "left":
        horizontal = "left"
    elif "e" in anchor or justify == "right":
        horizontal = "right"
    else:
        horizontal = "center"

    if anchor.startswith("n") or anchor in ("nw", "ne"):
        vertical = "top"
    elif anchor.startswith("s") or anchor in ("sw", "se"):
        vertical = "bottom"
    else:
        vertical = "center"

    return horizontal, vertical


def _v71_widget_has_border(widget):
    """
    Entry 또는 solid/groove/ridge/sunken/raised 형태 위젯은
    Excel에서도 테두리를 적용합니다.
    """
    try:
        widget_class = widget.winfo_class()
    except Exception:
        widget_class = ""

    if widget_class in (
        "Entry",
        "TEntry",
        "TCombobox",
        "Spinbox",
        "Listbox",
        "Text",
    ):
        return True

    relief = str(_v71_widget_option(widget, "relief", "")).lower()

    if relief in ("solid", "groove", "ridge", "sunken", "raised"):
        return True

    # 표 안쪽 Label은 부모 Frame의 relief를 확인합니다.
    try:
        parent_relief = str(
            _v71_widget_option(widget.master, "relief", "")
        ).lower()

        if parent_relief in (
            "solid",
            "groove",
            "ridge",
            "sunken",
            "raised",
        ):
            return True
    except Exception:
        pass

    return False


def _v71_is_export_leaf(widget):
    """
    Excel 셀로 출력할 위젯인지 판별합니다.
    """
    try:
        widget_class = widget.winfo_class()
    except Exception:
        return False

    # 내보내기에서 제외할 조작용 위젯
    if widget_class in (
        "Button",
        "TButton",
        "Scrollbar",
        "TScrollbar",
        "Scale",
        "TScale",
        "Separator",
        "Sizegrip",
    ):
        return False

    supported = (
        "Label",
        "TLabel",
        "Message",
        "Entry",
        "TEntry",
        "TCombobox",
        "Spinbox",
        "Text",
        "Checkbutton",
        "TCheckbutton",
        "Radiobutton",
        "TRadiobutton",
        "Menubutton",
        "TMenubutton",
        "Listbox",
    )

    if widget_class not in supported:
        return False

    text = _v71_widget_text(widget)

    # 빈 Entry도 입력셀 구조를 유지하기 위해 포함합니다.
    if widget_class in (
        "Entry",
        "TEntry",
        "TCombobox",
        "Spinbox",
        "Text",
    ):
        return True

    return str(text).strip() != ""



# ===== 최종본74 Excel 화면배치 정렬 수정 =====
# 1. 숨겨진 부모 프레임 내부 위젯 제외
# 2. Excel 좌측·상단 불필요한 공백 제거
# 3. 화면 8픽셀 기준 열 너비 교정
# 4. Excel 보기 배율 및 시작 위치 교정
# 5. MergedCell 오류 방지 유지
# ============================================================

# ===== 최종본76 Excel 세부 화면 구조 보정 =====
# 1. 실제 표시되지 않는 위젯 제외
# 2. LabelFrame 전체 배경·외곽선 출력
# 3. 짧은 문구 세로 줄바꿈 방지
# 4. 상단 잔여 위젯 출력 방지
# ============================================================

# ===== 최종본77 기본입력사항 빈 시트 수정 =====
# 1. winfo_ismapped 강제 검사 제거
# 2. 실제 크기와 요청 크기를 함께 검사
# 3. 시트 전환 후 화면 배치 계산 완료
# 4. 빈 시트 발생 시 위젯 수집 재시도
# ============================================================

def _v74_is_effectively_managed(
    widget,
    root_widget
):
    """
    위젯과 부모 프레임이 pack/grid/place 구조에 포함되어 있는지
    검사합니다.

    주의:
    Excel 변환 과정에서 화면 시트를 전환하거나 Toplevel 상태가
    변경되면 정상적인 위젯도 일시적으로 winfo_ismapped()가 False가
    될 수 있습니다.

    따라서 최종본77에서는 winfo_ismapped()를 사용하지 않고
    위젯 관리자(pack/grid/place)의 존재 여부만 검사합니다.
    """
    current = widget
    safety = 0

    while (
        current is not None
        and current != root_widget
        and safety < 200
    ):
        safety += 1

        try:
            if not current.winfo_exists():
                return False

            manager = str(
                current.winfo_manager()
            ).strip()

            if not manager:
                return False

            current = current.master

        except Exception:
            return False

    return current == root_widget


def _v71_collect_export_items(root_widget, excluded_roots=None):
    """
    화면 위젯의 좌표, 크기, 값, 색상, 글꼴 정보를 수집합니다.
    """
    excluded_roots = set(excluded_roots or [])
    items = []

    try:
        root_widget.update_idletasks()
    except Exception:
        pass

    _v71_reset_canvases(root_widget)

    try:
        root_widget.update_idletasks()
    except Exception:
        pass

    all_widgets = [root_widget] + _v71_walk_widgets(root_widget)

    for widget in all_widgets:
        if widget == root_widget:
            continue

        if _v71_is_excluded(widget, excluded_roots):
            continue

        if not _v71_is_managed(widget):
            continue

        # 최종본74: 숨겨진 부모 프레임 내부 위젯 제외
        if not _v74_is_effectively_managed(
            widget,
            root_widget
        ):
            continue

        # 최종본77: 실제 크기와 요청 크기를 함께 검사
        # 화면 전환 직후 actual 크기가 1이어도 requested 크기가
        # 정상이면 유효한 위젯으로 처리합니다.
        try:
            actual_width = int(widget.winfo_width())
            actual_height = int(widget.winfo_height())

            requested_width = int(
                widget.winfo_reqwidth()
            )

            requested_height = int(
                widget.winfo_reqheight()
            )

            effective_width = max(
                actual_width,
                requested_width
            )

            effective_height = max(
                actual_height,
                requested_height
            )

            if (
                effective_width <= 1
                or effective_height <= 1
            ):
                continue

        except Exception:
            continue

        try:
            widget_class = widget.winfo_class()
        except Exception:
            continue

        # LabelFrame 제목을 별도 항목으로 저장
        if widget_class in ("Labelframe", "TLabelframe"):
            title = str(_v71_widget_option(widget, "text", "") or "").strip()

            if title:
                x, y = _v71_relative_position(widget, root_widget)

                try:
                    width = max(
                        int(widget.winfo_width()),
                        int(widget.winfo_reqwidth()),
                        80
                    )
                except Exception:
                    width = 120

                items.append({
                    "kind": "labelframe_title",
                    "widget": widget,
                    "text": title,
                    "x": x + 7,
                    "y": max(0, y),
                    "width": min(width - 14, max(80, len(title) * 16)),
                    "height": 20,
                    "bg": _v71_widget_background(widget),
                    "fg": _v71_widget_foreground(widget),
                    "font": _v71_font_info(widget),
                    "align": ("left", "center"),
                    "border": False,
                })

            continue

        if not _v71_is_export_leaf(widget):
            continue

        x, y = _v71_relative_position(widget, root_widget)

        try:
            width = max(
                int(widget.winfo_width()),
                int(widget.winfo_reqwidth()),
                8
            )
        except Exception:
            width = 80

        try:
            height = max(
                int(widget.winfo_height()),
                int(widget.winfo_reqheight()),
                8
            )
        except Exception:
            height = 22

        items.append({
            "kind": "widget",
            "widget": widget,
            "text": _v71_widget_text(widget),
            "x": max(0, x),
            "y": max(0, y),
            "width": width,
            "height": height,
            "bg": _v71_widget_background(widget),
            "fg": _v71_widget_foreground(widget),
            "font": _v71_font_info(widget),
            "align": _v71_widget_alignment(widget),
            "border": _v71_widget_has_border(widget),
        })

    # 큰 배경 위젯보다 실제 입력/라벨 위젯을 우선 처리합니다.
    items.sort(
        key=lambda item: (
            item["y"],
            item["x"],
            item["width"] * item["height"]
        )
    )

    return items


def _v71_excel_value(value):
    """
    화면 문자열 중 순수 숫자는 Excel 숫자형으로 변환합니다.
    날짜·수식·복합문구는 화면 문자열을 그대로 유지합니다.
    """
    if value is None:
        return ""

    text = str(value)

    if "\n" in text:
        return text

    stripped = text.strip()

    if not stripped:
        return ""

    # 체크/라디오 표시값은 문자열 유지
    if stripped.startswith(("☑", "☐", "●", "○")):
        return text

    # 날짜 형식은 문자열 유지
    if "." in stripped and len(stripped.replace(".", "")) == 8:
        if stripped.replace(".", "").isdigit():
            return text

    normalized = stripped.replace(",", "")

    try:
        if normalized.startswith("-"):
            signless = normalized[1:]
        else:
            signless = normalized

        if signless.isdigit():
            return int(normalized)

        if signless.count(".") == 1:
            left, right = signless.split(".", 1)

            if left.isdigit() and right.isdigit():
                return float(normalized)

    except Exception:
        pass

    return text


def _v71_safe_sheet_name(name, used_names):
    """
    Excel 시트명 금지문자를 제거하고 중복되지 않는 이름을 생성합니다.
    """
    invalid_chars = set(r'[]:*?/\\')

    cleaned = "".join(
        "_" if char in invalid_chars else char
        for char in str(name)
    ).strip()

    if not cleaned:
        cleaned = "Sheet"

    cleaned = cleaned[:31]
    candidate = cleaned
    sequence = 2

    while candidate in used_names:
        suffix = f"_{sequence}"
        candidate = cleaned[:31 - len(suffix)] + suffix
        sequence += 1

    used_names.add(candidate)
    return candidate


def _v71_put_border_on_range(
    ws,
    min_row,
    min_col,
    max_row,
    max_col,
    border
):
    for row in range(min_row, max_row + 1):
        for col in range(min_col, max_col + 1):
            ws.cell(row=row, column=col).border = border


# ===== 최종본75 실제 위젯 경계 기반 Excel 변환 =====
# 고정 8픽셀 세부 열 방식을 제거하고 실제 위젯의
# 시작·종료 좌표를 Excel 셀 경계로 사용합니다.
# ============================================================

def _v71_write_widget_sheet(
    workbook,
    sheet_name,
    root_widget,
    excluded_roots=None
):
    """
    하나의 Tkinter 화면을 하나의 Excel 시트로 변환합니다.

    최종본75 변경 사항
    -----------------
    기존처럼 화면을 8픽셀 단위의 수많은 고정 열로 나누지 않고,
    실제 위젯들의 시작·종료 좌표를 Excel 셀 경계로 사용합니다.

    이 방식은 다음 문제를 방지합니다.

    1. GF, HD 열까지 초미세 열이 생성되는 문제
    2. 문구가 세로로 한 글자씩 표시되는 문제
    3. 반올림된 셀 좌표 때문에 서로 다른 위젯이 겹치는 문제
    4. 병합 셀 내부에 다시 값을 넣어 발생하는 MergedCell 오류
    """
    from openpyxl.styles import (
        Alignment,
        Border,
        Font,
        PatternFill,
        Side,
    )
    from openpyxl.utils import get_column_letter

    used_names = set(workbook.sheetnames)

    safe_name = _v71_safe_sheet_name(
        sheet_name,
        used_names
    )

    ws = workbook.create_sheet(
        title=safe_name
    )

    items = _v71_collect_export_items(
        root_widget,
        excluded_roots=excluded_roots
    )

    # 최종본77: 빈 시트 방지를 위한 위젯 수집 재시도
    if not items:
        try:
            root_widget.update_idletasks()

            try:
                root_widget.update()
            except Exception:
                pass

            root_widget.update_idletasks()

            items = _v71_collect_export_items(
                root_widget,
                excluded_roots=excluded_roots
            )

        except Exception:
            pass

    # --------------------------------------------------------
    # 재시도 후에도 출력할 항목이 없는 경우 빈 시트 반환
    # --------------------------------------------------------
    if not items:
        ws.sheet_view.showGridLines = False
        return ws

    # --------------------------------------------------------
    # 좌표값 안전 변환
    # --------------------------------------------------------
    normalized_items = []

    for item in items:
        try:
            x = max(
                0,
                int(float(item.get("x", 0)))
            )

            y = max(
                0,
                int(float(item.get("y", 0)))
            )

            width = max(
                8,
                int(float(item.get("width", 8)))
            )

            height = max(
                8,
                int(float(item.get("height", 8)))
            )

        except Exception:
            continue

        copied_item = dict(item)

        copied_item["x"] = x
        copied_item["y"] = y
        copied_item["width"] = width
        copied_item["height"] = height

        normalized_items.append(
            copied_item
        )

    if not normalized_items:
        ws.sheet_view.showGridLines = False
        return ws

    items = normalized_items

    # --------------------------------------------------------
    # 화면 왼쪽·위쪽 불필요한 빈 공간 제거
    # --------------------------------------------------------
    minimum_x = min(
        item["x"]
        for item in items
    )

    minimum_y = min(
        item["y"]
        for item in items
    )

    for item in items:
        item["x"] = max(
            0,
            item["x"] - minimum_x
        )

        item["y"] = max(
            0,
            item["y"] - minimum_y
        )

    # --------------------------------------------------------
    # 너무 가까운 좌표를 같은 경계로 정리
    #
    # Tkinter 위젯은 padding 또는 테두리 때문에 실제로는 같은
    # 위치여도 1~3픽셀 차이가 날 수 있습니다.
    # --------------------------------------------------------
    def snap_coordinate(value, unit=4):
        try:
            return int(
                round(float(value) / unit) * unit
            )
        except Exception:
            return 0

    for item in items:
        original_x = item["x"]
        original_y = item["y"]
        original_right = (
            item["x"] + item["width"]
        )
        original_bottom = (
            item["y"] + item["height"]
        )

        snapped_x = snap_coordinate(
            original_x
        )

        snapped_y = snap_coordinate(
            original_y
        )

        snapped_right = snap_coordinate(
            original_right
        )

        snapped_bottom = snap_coordinate(
            original_bottom
        )

        if snapped_right <= snapped_x:
            snapped_right = snapped_x + 8

        if snapped_bottom <= snapped_y:
            snapped_bottom = snapped_y + 8

        item["x"] = snapped_x
        item["y"] = snapped_y
        item["right"] = snapped_right
        item["bottom"] = snapped_bottom

    # --------------------------------------------------------
    # 실제 위젯 경계 좌표 목록 생성
    #
    # 고정 8픽셀 열 대신 화면에 존재하는 실제 위젯의
    # 시작점과 끝점만 Excel 열·행 경계로 사용합니다.
    # --------------------------------------------------------
    x_boundaries = {0}
    y_boundaries = {0}

    for item in items:
        x_boundaries.add(
            item["x"]
        )

        x_boundaries.add(
            item["right"]
        )

        y_boundaries.add(
            item["y"]
        )

        y_boundaries.add(
            item["bottom"]
        )

        # 최종본76: LabelFrame 전체 범위를 Excel 경계에 포함
        if item.get("kind") == "labelframe_title":
            frame_widget = item.get("widget")

            try:
                frame_x, frame_y = _v71_relative_position(
                    frame_widget,
                    root_widget
                )

                frame_x = snap_coordinate(
                    max(0, int(frame_x) - minimum_x)
                )

                frame_y = snap_coordinate(
                    max(0, int(frame_y) - minimum_y)
                )

                frame_width = max(
                    20,
                    int(frame_widget.winfo_width())
                )

                frame_height = max(
                    20,
                    int(frame_widget.winfo_height())
                )

                frame_right = snap_coordinate(
                    frame_x + frame_width
                )

                frame_bottom = snap_coordinate(
                    frame_y + frame_height
                )

                if frame_right <= frame_x:
                    frame_right = frame_x + 20

                if frame_bottom <= frame_y:
                    frame_bottom = frame_y + 20

                item["frame_bounds"] = (
                    frame_x,
                    frame_y,
                    frame_right,
                    frame_bottom
                )

                x_boundaries.add(frame_x)
                x_boundaries.add(frame_right)
                y_boundaries.add(frame_y)
                y_boundaries.add(frame_bottom)

            except Exception:
                pass

    maximum_right = max(
        item["right"]
        for item in items
    )

    maximum_bottom = max(
        item["bottom"]
        for item in items
    )

    x_boundaries.add(
        maximum_right
    )

    y_boundaries.add(
        maximum_bottom
    )

    x_boundaries = sorted(
        x_boundaries
    )

    y_boundaries = sorted(
        y_boundaries
    )

    # 경계가 하나뿐인 비정상 상황 방지
    if len(x_boundaries) < 2:
        x_boundaries.append(
            x_boundaries[0] + 80
        )

    if len(y_boundaries) < 2:
        y_boundaries.append(
            y_boundaries[0] + 22
        )

    # 좌표에서 Excel 열·행 번호로 변환하기 위한 표
    x_index = {
        coordinate: index
        for index, coordinate
        in enumerate(x_boundaries)
    }

    y_index = {
        coordinate: index
        for index, coordinate
        in enumerate(y_boundaries)
    }

    # --------------------------------------------------------
    # 각 열 너비를 실제 픽셀 간격으로 설정
    # --------------------------------------------------------
    def pixels_to_excel_width(pixel_width):
        """
        화면 픽셀을 Excel 열 너비로 변환합니다.

        Excel 열 너비는 글꼴 기준 단위이므로
        픽셀값을 그대로 사용할 수 없습니다.
        """
        pixel_width = max(
            1,
            float(pixel_width)
        )

        if pixel_width <= 12:
            return max(
                0.35,
                pixel_width / 12.0
            )

        return max(
            0.35,
            (pixel_width - 5.0) / 7.0
        )

    for index in range(
        len(x_boundaries) - 1
    ):
        pixel_width = (
            x_boundaries[index + 1]
            - x_boundaries[index]
        )

        column_number = index + 1

        column_letter = get_column_letter(
            column_number
        )

        ws.column_dimensions[
            column_letter
        ].width = round(
            pixels_to_excel_width(
                pixel_width
            ),
            2
        )

    # --------------------------------------------------------
    # 각 행 높이를 실제 픽셀 간격으로 설정
    # 1픽셀은 약 0.75포인트입니다.
    # --------------------------------------------------------
    for index in range(
        len(y_boundaries) - 1
    ):
        pixel_height = (
            y_boundaries[index + 1]
            - y_boundaries[index]
        )

        row_number = index + 1

        ws.row_dimensions[
            row_number
        ].height = max(
            3.0,
            round(
                pixel_height * 0.75,
                2
            )
        )

    # --------------------------------------------------------
    # 스타일 설정
    # --------------------------------------------------------
    thin_side = Side(
        style="thin",
        color="808080"
    )

    thin_border = Border(
        left=thin_side,
        right=thin_side,
        top=thin_side,
        bottom=thin_side
    )

    occupied_ranges = []

    def ranges_intersect(
        row1,
        column1,
        row2,
        column2
    ):
        for (
            existing_row1,
            existing_column1,
            existing_row2,
            existing_column2
        ) in occupied_ranges:

            separated = (
                row2 < existing_row1
                or row1 > existing_row2
                or column2 < existing_column1
                or column1 > existing_column2
            )

            if not separated:
                return True

        return False

    def cell_is_occupied(
        row_number,
        column_number
    ):
        for (
            existing_row1,
            existing_column1,
            existing_row2,
            existing_column2
        ) in occupied_ranges:

            if (
                existing_row1
                <= row_number
                <= existing_row2
                and existing_column1
                <= column_number
                <= existing_column2
            ):
                return True

        return False

    # 최종본76: LabelFrame 배경과 외곽 테두리 선출력
    # 실제 프로그램의 감리사항·기본입력사항 박스를
    # Excel에서도 하나의 큰 영역으로 표시합니다.
    for frame_item in items:
        frame_bounds = frame_item.get("frame_bounds")

        if not frame_bounds:
            continue

        try:
            frame_x1, frame_y1, frame_x2, frame_y2 = (
                frame_bounds
            )

            frame_start_col = x_index[frame_x1] + 1
            frame_end_col = max(
                frame_start_col,
                x_index[frame_x2]
            )

            frame_start_row = y_index[frame_y1] + 1
            frame_end_row = max(
                frame_start_row,
                y_index[frame_y2]
            )

            frame_widget = frame_item.get("widget")

            frame_bg = _v71_to_excel_color(
                frame_widget,
                frame_item.get("bg", "F2F2F2"),
                "F2F2F2"
            )

            frame_fill = PatternFill(
                fill_type="solid",
                start_color=frame_bg,
                end_color=frame_bg
            )

            for frame_row in range(
                frame_start_row,
                frame_end_row + 1
            ):
                for frame_col in range(
                    frame_start_col,
                    frame_end_col + 1
                ):
                    background_cell = ws.cell(
                        row=frame_row,
                        column=frame_col
                    )

                    background_cell.fill = frame_fill

                    current_border = background_cell.border

                    left_side = (
                        thin_side
                        if frame_col == frame_start_col
                        else current_border.left
                    )

                    right_side = (
                        thin_side
                        if frame_col == frame_end_col
                        else current_border.right
                    )

                    top_side = (
                        thin_side
                        if frame_row == frame_start_row
                        else current_border.top
                    )

                    bottom_side = (
                        thin_side
                        if frame_row == frame_end_row
                        else current_border.bottom
                    )

                    background_cell.border = Border(
                        left=left_side,
                        right=right_side,
                        top=top_side,
                        bottom=bottom_side
                    )

        except Exception:
            pass

    # 위쪽·왼쪽부터 차례대로 처리
    items.sort(
        key=lambda item: (
            item["y"],
            item["x"],
            item["width"] * item["height"]
        )
    )

    max_column = 1
    max_row = 1

    for item in items:
        start_col = (
            x_index[item["x"]] + 1
        )

        # 경계 index는 셀 개수와 같으므로
        # 종료 열에는 +1을 하지 않습니다.
        end_col = x_index[
            item["right"]
        ]

        start_row = (
            y_index[item["y"]] + 1
        )

        end_row = y_index[
            item["bottom"]
        ]

        end_col = max(
            start_col,
            end_col
        )

        end_row = max(
            start_row,
            end_row
        )

        max_column = max(
            max_column,
            end_col
        )

        max_row = max(
            max_row,
            end_row
        )

        # 실제 화면 좌표가 겹치는 항목인지 확인
        has_overlap = ranges_intersect(
            start_row,
            start_col,
            end_row,
            end_col
        )

        if has_overlap:
            # 시작 셀이 이미 사용 중이면 범위 안에서
            # 사용 가능한 첫 번째 셀을 찾습니다.
            available_position = None

            for candidate_row in range(
                start_row,
                end_row + 1
            ):
                for candidate_column in range(
                    start_col,
                    end_col + 1
                ):
                    if not cell_is_occupied(
                        candidate_row,
                        candidate_column
                    ):
                        available_position = (
                            candidate_row,
                            candidate_column
                        )
                        break

                if available_position is not None:
                    break

            # 범위 전체가 다른 항목으로 사용 중이면 중복 출력 제외
            if available_position is None:
                continue

            start_row, start_col = (
                available_position
            )

            end_row = start_row
            end_col = start_col

            can_merge = False

        else:
            can_merge = True

        cell = ws.cell(
            row=start_row,
            column=start_col
        )

        # 최종본75: MergedCell read-only 오류 방지
        if (
            cell.__class__.__name__
            == "MergedCell"
        ):
            continue

        try:
            cell.value = _v71_excel_value(
                item.get("text", "")
            )
        except AttributeError:
            continue

        widget = item["widget"]

        bg_color = _v71_to_excel_color(
            widget,
            item.get("bg", "FFFFFF"),
            "FFFFFF"
        )

        fg_color = _v71_to_excel_color(
            widget,
            item.get("fg", "000000"),
            "000000"
        )

        font_info = item.get(
            "font",
            {}
        )

        font_name = font_info.get(
            "name",
            "맑은 고딕"
        )

        font_size = font_info.get(
            "size",
            9
        )

        try:
            font_size = float(
                font_size
            )
        except Exception:
            font_size = 9

        # 지나치게 큰 글꼴이 Excel 배치를 무너뜨리지 않도록 제한
        font_size = min(
            16,
            max(7, font_size)
        )

        cell.font = Font(
            name=font_name,
            size=font_size,
            bold=bool(
                font_info.get(
                    "bold",
                    False
                )
            ),
            italic=bool(
                font_info.get(
                    "italic",
                    False
                )
            ),
            underline=font_info.get(
                "underline"
            ),
            color=fg_color
        )

        horizontal, vertical = item.get(
            "align",
            ("center", "center")
        )

        # 최종본76: 짧은 문구의 세로 줄바꿈 방지
        try:
            widget_class = widget.winfo_class()
        except Exception:
            widget_class = ""

        input_classes = (
            "Entry",
            "TEntry",
            "TCombobox",
            "Spinbox",
            "Text",
            "Listbox",
        )

        is_input_widget = (
            widget_class in input_classes
        )

        cell.alignment = Alignment(
            horizontal=horizontal,
            vertical=vertical,
            wrap_text=is_input_widget,
            shrink_to_fit=not is_input_widget
        )

        cell.fill = PatternFill(
            fill_type="solid",
            start_color=bg_color,
            end_color=bg_color
        )

        if isinstance(
            cell.value,
            (int, float)
        ):
            if isinstance(
                cell.value,
                float
            ):
                cell.number_format = "#,##0.00"
            else:
                cell.number_format = "#,##0"

        if item.get("border", False):
            try:
                _v71_put_border_on_range(
                    ws,
                    start_row,
                    start_col,
                    end_row,
                    end_col,
                    thin_border
                )
            except Exception:
                pass

        occupied_ranges.append(
            (
                start_row,
                start_col,
                end_row,
                end_col
            )
        )

        if (
            can_merge
            and (
                end_row > start_row
                or end_col > start_col
            )
        ):
            try:
                ws.merge_cells(
                    start_row=start_row,
                    start_column=start_col,
                    end_row=end_row,
                    end_column=end_col
                )
            except ValueError:
                # 다른 병합영역과 충돌하면 병합하지 않고
                # 시작 셀의 값은 그대로 유지합니다.
                pass
            except Exception:
                pass

    # --------------------------------------------------------
    # Excel 기본 보기 설정
    # --------------------------------------------------------
    ws.sheet_view.showGridLines = False

    try:
        ws.sheet_view.zoomScale = 85
        ws.sheet_view.zoomScaleNormal = 85
        ws.sheet_view.topLeftCell = "A1"

        if ws.sheet_view.selection:
            ws.sheet_view.selection[
                0
            ].activeCell = "A1"

            ws.sheet_view.selection[
                0
            ].sqref = "A1"

    except Exception:
        pass

    try:
        ws.freeze_panes = None
    except Exception:
        pass

    # --------------------------------------------------------
    # 인쇄 설정
    # --------------------------------------------------------
    try:
        ws.sheet_properties.pageSetUpPr.fitToPage = True

        ws.page_setup.fitToWidth = 1
        ws.page_setup.fitToHeight = 0

        # 실제 화면 폭이 넓으면 가로 방향 사용
        if maximum_right >= 900:
            ws.page_setup.orientation = "landscape"
        else:
            ws.page_setup.orientation = "portrait"

        ws.page_margins.left = 0.15
        ws.page_margins.right = 0.15
        ws.page_margins.top = 0.25
        ws.page_margins.bottom = 0.25

        ws.print_area = (
            f"A1:"
            f"{get_column_letter(max_column)}"
            f"{max_row}"
        )

    except Exception:
        pass

    return ws


def _v71_find_active_sheet_name(namespace):
    sheet_frames = namespace.get("sheet_frames", {})

    if not isinstance(sheet_frames, dict):
        return None

    for name, frame in sheet_frames.items():
        try:
            if frame.winfo_ismapped():
                return name
        except Exception:
            pass

    return None


def _v71_find_show_sheet_function(namespace):
    for function_name in (
        "electric_show_sheet",
        "communication_show_sheet",
        "fire_show_sheet",
        "show_sheet",
    ):
        function = namespace.get(function_name)

        if callable(function):
            return function

    return None


def _v71_current_trade_name(namespace, fallback):
    for function_name in (
        "electric_current_trade_name",
        "communication_current_trade_name",
        "fire_current_trade_name",
        "current_trade_name",
    ):
        function = namespace.get(function_name)

        if callable(function):
            try:
                value = str(function()).strip()

                if value:
                    return value
            except Exception:
                pass

    return fallback



# ===== 최종본79 Excel 개요 시트 추가 =====

def _v79_add_overview_sheet(
    workbook,
    namespace,
    trade_name
):
    """
    Excel 통합문서의 가장 첫 번째 위치에
    A4 세로 형태의 '개요' 시트를 생성합니다.

    출력 내용
    --------
    사업명1, 사업명2, 사업명3 전기/통신/소방감리 산출내역서

    오늘 날짜
    시설기획과 ㅇㅇㅇ
    """
    from datetime import datetime as _v79_datetime

    from openpyxl.styles import (
        Alignment,
        Border,
        Font,
        PatternFill,
        Side,
    )

    # --------------------------------------------------------
    # 기존 개요 시트 중복 방지
    # --------------------------------------------------------
    if "개요" in workbook.sheetnames:
        try:
            workbook.remove(
                workbook["개요"]
            )
        except Exception:
            pass

    # index=0으로 생성하여 항상 첫 번째 시트로 배치
    worksheet = workbook.create_sheet(
        title="개요",
        index=0
    )

    # --------------------------------------------------------
    # 사업 1~3의 입력된 사업명 수집
    # --------------------------------------------------------
    project_names = []

    entry_names = namespace.get(
        "entry_names",
        []
    )

    for entry in entry_names[:3]:
        try:
            project_name = str(
                entry.get()
            ).strip()

            if project_name:
                project_names.append(
                    project_name
                )

        except Exception:
            pass

    if project_names:
        project_name_text = ", ".join(
            project_names
        )
    else:
        project_name_text = "사업명 미입력"

    # --------------------------------------------------------
    # 공종명 정리
    # --------------------------------------------------------
    normalized_trade_name = str(
        trade_name or ""
    ).strip()

    if normalized_trade_name not in (
        "전기",
        "통신",
        "소방"
    ):
        normalized_trade_name = "감리"

    if normalized_trade_name == "감리":
        document_title = (
            f"{project_name_text} 감리 산출내역서"
        )
    else:
        document_title = (
            f"{project_name_text} "
            f"{normalized_trade_name}감리 산출내역서"
        )

    today_text = _v79_datetime.now().strftime(
        "%Y년 %m월 %d일"
    )

    # --------------------------------------------------------
    # A4 화면 영역 및 열 너비 설정
    # --------------------------------------------------------
    column_widths = {
        "A": 4,
        "B": 13,
        "C": 13,
        "D": 13,
        "E": 13,
        "F": 13,
        "G": 13,
        "H": 4,
    }

    for column_letter, width in column_widths.items():
        worksheet.column_dimensions[
            column_letter
        ].width = width

    # A4 문서 형태를 위한 행 높이
    for row_number in range(1, 30):
        worksheet.row_dimensions[
            row_number
        ].height = 22

    worksheet.row_dimensions[1].height = 15
    worksheet.row_dimensions[2].height = 25
    worksheet.row_dimensions[3].height = 25

    for row_number in range(5, 11):
        worksheet.row_dimensions[
            row_number
        ].height = 30

    worksheet.row_dimensions[17].height = 28
    worksheet.row_dimensions[19].height = 28

    # --------------------------------------------------------
    # 바깥 A4 문서 테두리
    # --------------------------------------------------------
    thin_gray_side = Side(
        style="thin",
        color="D9D9D9"
    )

    outer_side = Side(
        style="medium",
        color="7F7F7F"
    )

    white_fill = PatternFill(
        fill_type="solid",
        start_color="FFFFFF",
        end_color="FFFFFF"
    )

    for row_number in range(2, 29):
        for column_number in range(2, 8):
            cell = worksheet.cell(
                row=row_number,
                column=column_number
            )

            cell.fill = white_fill

            left_border = (
                outer_side
                if column_number == 2
                else thin_gray_side
                if column_number == 1
                else Side(style=None)
            )

            right_border = (
                outer_side
                if column_number == 7
                else Side(style=None)
            )

            top_border = (
                outer_side
                if row_number == 2
                else Side(style=None)
            )

            bottom_border = (
                outer_side
                if row_number == 28
                else Side(style=None)
            )

            cell.border = Border(
                left=left_border,
                right=right_border,
                top=top_border,
                bottom=bottom_border
            )

    # --------------------------------------------------------
    # 문서 제목
    # --------------------------------------------------------
    worksheet.merge_cells(
        "B5:G10"
    )

    title_cell = worksheet["B5"]

    title_cell.value = document_title

    title_cell.font = Font(
        name="맑은 고딕",
        size=22,
        bold=True,
        color="000000"
    )

    title_cell.alignment = Alignment(
        horizontal="center",
        vertical="center",
        wrap_text=True,
        shrink_to_fit=True
    )

    # --------------------------------------------------------
    # 구분선
    # --------------------------------------------------------
    worksheet.merge_cells(
        "C13:F13"
    )

    separator_cell = worksheet["C13"]

    separator_cell.value = ""

    separator_cell.border = Border(
        bottom=Side(
            style="thin",
            color="BFBFBF"
        )
    )

    # --------------------------------------------------------
    # 오늘 날짜
    # --------------------------------------------------------
    worksheet.merge_cells(
        "B17:G17"
    )

    date_cell = worksheet["B17"]

    date_cell.value = today_text

    date_cell.font = Font(
        name="맑은 고딕",
        size=14,
        bold=False,
        color="000000"
    )

    date_cell.alignment = Alignment(
        horizontal="center",
        vertical="center"
    )

    # --------------------------------------------------------
    # 부서 및 작성자
    #
    # ㅇㅇㅇ 부분은 Excel에서 직접 수정할 수 있습니다.
    # --------------------------------------------------------
    worksheet.merge_cells(
        "B19:G19"
    )

    department_cell = worksheet["B19"]

    department_cell.value = "시설기획과 ㅇㅇㅇ"

    department_cell.font = Font(
        name="맑은 고딕",
        size=15,
        bold=True,
        color="000000"
    )

    department_cell.alignment = Alignment(
        horizontal="center",
        vertical="center"
    )

    # --------------------------------------------------------
    # 하단 문구
    # --------------------------------------------------------
    worksheet.merge_cells(
        "B25:G25"
    )

    footer_cell = worksheet["B25"]

    footer_cell.value = (
        "서울대학교 시설기획과"
    )

    footer_cell.font = Font(
        name="맑은 고딕",
        size=9,
        italic=False,
        color="808080"
    )

    footer_cell.alignment = Alignment(
        horizontal="center",
        vertical="center"
    )

    # --------------------------------------------------------
    # Excel 화면 설정
    # --------------------------------------------------------
    worksheet.sheet_view.showGridLines = False

    try:
        worksheet.sheet_view.zoomScale = 85
        worksheet.sheet_view.zoomScaleNormal = 85
        worksheet.sheet_view.topLeftCell = "A1"

        if worksheet.sheet_view.selection:
            worksheet.sheet_view.selection[
                0
            ].activeCell = "B2"

            worksheet.sheet_view.selection[
                0
            ].sqref = "B2"

    except Exception:
        pass

    # --------------------------------------------------------
    # A4 인쇄 설정
    # --------------------------------------------------------
    try:
        worksheet.sheet_properties.pageSetUpPr.fitToPage = True

        worksheet.page_setup.paperSize = (
            worksheet.PAPERSIZE_A4
        )

        worksheet.page_setup.orientation = (
            "portrait"
        )

        worksheet.page_setup.fitToWidth = 1
        worksheet.page_setup.fitToHeight = 1

        worksheet.page_margins.left = 0.3
        worksheet.page_margins.right = 0.3
        worksheet.page_margins.top = 0.4
        worksheet.page_margins.bottom = 0.4
        worksheet.page_margins.header = 0
        worksheet.page_margins.footer = 0

        worksheet.print_options.horizontalCentered = True
        worksheet.print_options.verticalCentered = True

        worksheet.print_area = "B2:G28"

    except Exception:
        pass

    # 개요 시트를 활성 시트로 설정
    try:
        workbook.active = 0
    except Exception:
        pass

    return worksheet


# ===== 최종본79 Excel 개요 시트 추가 끝 =====


def _v71_export_screen_excel(namespace, trade_name):
    """
    기본입력사항 및 모든 산출 시트를 화면 구조 기준으로 Excel에 저장합니다.
    """
    try:
        import openpyxl
        from tkinter import filedialog, messagebox
    except ImportError:
        try:
            namespace["messagebox"].showerror(
                "모듈 누락",
                "openpyxl 라이브러리가 필요합니다.\n\n"
                "명령 프롬프트에서 다음 명령을 실행하세요.\n"
                "py -3 -m pip install openpyxl"
            )
        except Exception:
            pass

        return

    root = namespace.get("root")

    if root is None:
        return

    try:
        # 저장 직전 모든 계산 갱신
        for function_name in (
            "electric_actual_ui_update",
            "communication_actual_ui_update",
            "fire_actual_ui_update",
            "electric_update_all_communication_info",
            "communication_update_all_communication_info",
            "fire_update_all_communication_info",
            "electric_update_comparison_table",
            "communication_update_comparison_table",
            "fire_update_comparison_table",
        ):
            function = namespace.get(function_name)

            if callable(function):
                try:
                    function()
                except Exception:
                    pass

        root.update_idletasks()

        current_trade = _v71_current_trade_name(
            namespace,
            trade_name
        )

        entry_names = namespace.get("entry_names", [])
        project_names = []

        for entry in entry_names[:3]:
            try:
                name = entry.get().strip()

                if name:
                    project_names.append(name)
            except Exception:
                pass

        project_title = ", ".join(project_names)

        if not project_title:
            project_title = "미지정사업"

        # 최종본71 오류수정: 공종별 namespace와 관계없이 datetime을 함수 내부에서 직접 import
        from datetime import datetime as _v71_datetime
        today_string = _v71_datetime.now().strftime("%y%m%d")
        default_filename = (
            f"서울대학교 {project_title} "
            f"{current_trade}공사 감리용역 산출조서_"
            f"{today_string}.xlsx"
        )

        file_path = filedialog.asksaveasfilename(
            defaultextension=".xlsx",
            initialfile=default_filename,
            filetypes=[("Excel 통합문서", "*.xlsx")],
            title=f"{current_trade}공종 전체 화면 엑셀 내려받기"
        )

        if not file_path:
            return

        workbook = openpyxl.Workbook()
        default_sheet = workbook.active
        workbook.remove(default_sheet)

        # 최종본79: 첫 번째 위치에 개요 시트 생성
        _v79_add_overview_sheet(
            workbook,
            namespace,
            current_trade
        )

        sheet_frames = namespace.get("sheet_frames", {})

        if not isinstance(sheet_frames, dict):
            sheet_frames = {}

        active_sheet_name = _v71_find_active_sheet_name(namespace)
        show_sheet = _v71_find_show_sheet_function(namespace)

        # ---------------------------------------------------------
        # 1. 기본입력사항
        # ---------------------------------------------------------
        basic_root = None

        # 프로그램에 기본입력사항 시트가 등록되어 있으면 해당 시트 우선
        for name, frame in sheet_frames.items():
            normalized = str(name).replace(" ", "")

            if (
                "기본입력" in normalized or
                "입력사항" in normalized or
                "사업정보" in normalized
            ):
                basic_root = frame
                break

        if basic_root is not None:
            if show_sheet is not None:
                try:
                    show_sheet(name)

                    # 최종본77: 시트 전환 후 화면 배치 계산 완료
                    root.update_idletasks()

                    try:
                        root.update()
                    except Exception:
                        pass

                    root.update_idletasks()
                except Exception:
                    pass

            _v71_write_widget_sheet(
                workbook,
                "기본입력사항",
                basic_root
            )

        else:
            # 별도 기본입력 시트가 없는 구조에서는 main_content를 사용
            main_content = namespace.get("main_content")

            if main_content is not None:
                output_frames = set(sheet_frames.values())

                _v71_write_widget_sheet(
                    workbook,
                    "기본입력사항",
                    main_content,
                    excluded_roots=output_frames
                )

        # ---------------------------------------------------------
        # 2. 프로그램에 등록된 모든 산출 시트
        # ---------------------------------------------------------
        for name, frame in sheet_frames.items():
            normalized = str(name).replace(" ", "")

            if (
                "기본입력" in normalized or
                "입력사항" in normalized or
                "사업정보" in normalized
            ):
                # 위에서 이미 출력
                continue

            if show_sheet is not None:
                try:
                    show_sheet(name)

                    # 최종본77: 시트 전환 후 화면 배치 계산 완료
                    root.update_idletasks()

                    try:
                        root.update()
                    except Exception:
                        pass

                    root.update_idletasks()
                except Exception:
                    pass

            _v71_write_widget_sheet(
                workbook,
                name,
                frame
            )

        # sheet_frames 외에 화면에 별도 등록된 비교표가 있으면 추가
        comparison_candidates = (
            ("감리비 비교표", "comparison_frame"),
            ("비교표", "comparison_table_frame"),
            ("투입계획표", "gantt_frame"),
            ("배치계획표", "deployment_plan_frame"),
        )

        already_exported_frames = set(sheet_frames.values())

        for extra_name, variable_name in comparison_candidates:
            extra_frame = namespace.get(variable_name)

            if (
                extra_frame is not None and
                extra_frame not in already_exported_frames
            ):
                try:
                    if extra_frame.winfo_exists():
                        _v71_write_widget_sheet(
                            workbook,
                            extra_name,
                            extra_frame
                        )
                        already_exported_frames.add(extra_frame)
                except Exception:
                    pass

        if not workbook.sheetnames:
            raise RuntimeError(
                "엑셀로 내보낼 화면 또는 시트를 찾지 못했습니다."
            )

        # 원래 보고 있던 시트 복구
        if active_sheet_name and show_sheet is not None:
            try:
                show_sheet(active_sheet_name)
                root.update_idletasks()
            except Exception:
                pass

        workbook.save(file_path)

        messagebox.showinfo(
            "엑셀 저장 완료",
            "화면 구조 기준 엑셀 파일을 저장했습니다.\n\n"
            f"{file_path}\n\n"
            f"생성 시트 수: {len(workbook.sheetnames)}개"
        )

    except PermissionError:
        try:
            messagebox.showerror(
                "저장 실패",
                "저장하려는 Excel 파일이 열려 있거나 "
                "파일을 쓸 권한이 없습니다.\n\n"
                "Excel 파일을 닫고 다시 시도하세요."
            )
        except Exception:
            pass

    except Exception as error:
        import traceback

        detail = traceback.format_exc()

        try:
            messagebox.showerror(
                "엑셀 저장 오류",
                "화면 구조를 Excel로 변환하는 중 오류가 발생했습니다.\n\n"
                f"{error}\n\n"
                f"{detail}"
            )
        except Exception:
            print(detail)


def _v71_remove_bold_from_widget(widget):
    """기존 글꼴을 유지하면서 bold 속성만 제거합니다."""
    try:
        import tkinter.font as tkfont

        actual = tkfont.Font(font=widget.cget("font")).actual()

        widget.configure(
            font=(
                actual.get("family", "Arial"),
                abs(int(actual.get("size", 9))) or 9,
                "normal"
            )
        )
    except Exception:
        try:
            widget.configure(font=("Arial", 9, "normal"))
        except Exception:
            pass


def _v71_find_monitor_frame(widget):
    current = widget

    while current is not None:
        try:
            if (
                current.winfo_class() in (
                    "Labelframe",
                    "TLabelframe"
                ) and
                str(current.cget("text")).strip() == "감리사항"
            ):
                return current

            current = current.master
        except Exception:
            break

    return None


def _v71_patch_electric_supervision(namespace, trade_name):
    # 전기공종 감리사항 UI 수정
    #
    # 1. '필요 감리원' 문구의 시작 위치를
    #    '배치 형태' 문구와 정확히 일치시킵니다.
    #
    # 2. 파란색 감리원 안내문은
    #    상주 체크버튼 시작 열 위에 배치합니다.
    #
    # 3. '배치 형태'와 '필요 감리원'은
    #    굵지 않은 일반 글꼴로 표시합니다.

    if trade_name != "전기":
        return

    label_list = namespace.get(
        "label_required_supervisor_display",
        []
    )

    if not isinstance(label_list, (list, tuple)):
        label_list = [label_list]

    for required_label in label_list:
        if required_label is None:
            continue

        monitor_frame = _v71_find_monitor_frame(required_label)

        if monitor_frame is None:
            continue

        try:
            required_info = required_label.grid_info()

            if not required_info:
                continue
        except Exception:
            continue

        try:
            required_row = int(
                required_info.get("row", 0)
            )
        except Exception:
            required_row = 0

        resident_column = None
        max_column = 0
        placement_label = None
        existing_need_label = None

        # 감리사항 프레임 내부의 배치 형태/상주/필요 감리원 위치 확인
        for child in monitor_frame.winfo_children():
            try:
                info = child.grid_info()

                if not info:
                    continue

                column = int(info.get("column", 0))
                columnspan = int(info.get("columnspan", 1))

                max_column = max(
                    max_column,
                    column + columnspan - 1
                )

                text = str(
                    _v71_widget_option(
                        child,
                        "text",
                        ""
                    ) or ""
                ).strip()

                child_class = child.winfo_class()

                if (
                    child_class in (
                        "Checkbutton",
                        "TCheckbutton"
                    )
                    and text == "상주"
                ):
                    resident_column = column

                if text == "배치 형태":
                    placement_label = child

                if text == "필요 감리원":
                    existing_need_label = child

            except Exception:
                pass

        # 배치 형태의 정확한 그리드 위치와 여백을 읽습니다.
        placement_column = 0
        placement_columnspan = 1
        placement_sticky = "w"
        placement_padx = (10, 5)
        placement_pady = (0, 2)
        placement_background = None

        if placement_label is not None:
            try:
                placement_info = placement_label.grid_info()

                placement_column = int(
                    placement_info.get("column", 0)
                )

                placement_columnspan = int(
                    placement_info.get("columnspan", 1)
                )

                placement_sticky = (
                    placement_info.get("sticky", "w")
                    or "w"
                )

                placement_padx = placement_info.get(
                    "padx",
                    0
                )

                placement_pady = placement_info.get(
                    "pady",
                    0
                )

            except Exception:
                pass

            try:
                placement_background = (
                    _v71_widget_option(
                        placement_label,
                        "background",
                        None
                    )
                    or
                    _v71_widget_option(
                        placement_label,
                        "bg",
                        None
                    )
                )
            except Exception:
                placement_background = None

            # 배치 형태 문구 볼드 해제
            _v71_remove_bold_from_widget(
                placement_label
            )

        if resident_column is None:
            try:
                original_column = int(
                    required_info.get("column", 0)
                )
            except Exception:
                original_column = 0

            resident_column = max(
                placement_column + placement_columnspan,
                original_column + 1
            )

        required_columnspan = max(
            1,
            max_column - resident_column + 1
        )

        # 파란색 필요 감리원 상세 안내문을
        # 상주 체크버튼의 시작 열 위로 이동합니다.
        try:
            required_label.grid_configure(
                row=required_row,
                column=resident_column,
                columnspan=required_columnspan,
                sticky="w",
                padx=0,
                pady=(0, 2)
            )
        except Exception:
            pass

        # '필요 감리원' 제목이 차지할 범위:
        # 배치 형태 시작 열부터 상주 체크버튼 직전까지
        need_columnspan = max(
            1,
            resident_column - placement_column
        )

        if placement_background is None:
            try:
                placement_background = (
                    _v71_widget_option(
                        monitor_frame,
                        "background",
                        None
                    )
                    or
                    _v71_widget_option(
                        monitor_frame,
                        "bg",
                        "#f0f0f0"
                    )
                )
            except Exception:
                placement_background = "#f0f0f0"

        # 이미 필요 감리원 문구가 있으면 새로 만들지 않고
        # 위치와 스타일만 수정합니다.
        if existing_need_label is not None:
            try:
                existing_need_label.configure(
                    text="필요 감리원",
                    anchor="w",
                    justify="left",
                    bg=placement_background
                )
            except Exception:
                pass

            try:
                existing_need_label.grid_configure(
                    row=required_row,
                    column=placement_column,
                    columnspan=need_columnspan,
                    sticky=placement_sticky,
                    padx=placement_padx,
                    pady=placement_pady
                )
            except Exception:
                pass

            _v71_remove_bold_from_widget(
                existing_need_label
            )

        else:
            try:
                # 배치 형태의 글꼴을 기준으로 일반체 글꼴을 만듭니다.
                font_family = "Arial"
                font_size = 9

                if placement_label is not None:
                    try:
                        import tkinter.font as tkfont

                        actual_font = tkfont.Font(
                            font=placement_label.cget("font")
                        ).actual()

                        font_family = actual_font.get(
                            "family",
                            "Arial"
                        )

                        font_size = abs(
                            int(actual_font.get("size", 9))
                        ) or 9

                    except Exception:
                        pass

                need_label = tk.Label(
                    monitor_frame,
                    text="필요 감리원",
                    font=(
                        font_family,
                        font_size,
                        "normal"
                    ),
                    bg=placement_background,
                    anchor="w",
                    justify="left"
                )

                need_label.grid(
                    row=required_row,
                    column=placement_column,
                    columnspan=need_columnspan,
                    sticky=placement_sticky,
                    padx=placement_padx,
                    pady=placement_pady
                )

            except Exception:
                pass

    try:
        namespace["root"].update_idletasks()
    except Exception:
        pass


def _v71_patch_excel_buttons(namespace, trade_name):
    """
    현재 공종에 존재하는 엑셀 내려받기 버튼을
    최종본107 화면동일형 내보내기 함수에 연결합니다.
    """
    root = namespace.get("root")

    if root is None:
        return

    patched_count = 0

    def export_command():
        return _v71_export_screen_excel(
            namespace,
            trade_name
        )

    for widget in _v71_walk_widgets(root):
        try:
            widget_class = widget.winfo_class()

            if widget_class not in ("Button", "TButton"):
                continue

            text = str(
                _v71_widget_option(widget, "text", "") or ""
            ).replace(" ", "")

            if "엑셀" not in text:
                continue

            if not any(
                keyword in text
                for keyword in (
                    "내려받기",
                    "다운로드",
                    "저장",
                    "출력",
                    "내보내기",
                )
            ):
                continue

            widget.configure(command=export_command)
            patched_count += 1

        except Exception:
            pass

    # 버튼명이 단순히 '엑셀'인 경우까지 추가 처리
    if patched_count == 0:
        for widget in _v71_walk_widgets(root):
            try:
                widget_class = widget.winfo_class()

                if widget_class not in ("Button", "TButton"):
                    continue

                text = str(
                    _v71_widget_option(widget, "text", "") or ""
                ).replace(" ", "")

                if text == "엑셀":
                    widget.configure(command=export_command)
                    patched_count += 1

            except Exception:
                pass

    # 기존 저장 함수 이름으로 직접 호출되는 경우도 교체
    for function_name in (
        "electric_export_to_excel",
        "communication_export_to_excel",
        "fire_export_to_excel",
        "export_to_excel",
    ):
        if function_name in namespace:
            namespace[function_name] = export_command

    return patched_count



# ===== 최종본73 입력 활성화 및 MergedCell 오류 수정 =====
# 1. 상주 보조1~3 날짜 입력란 직접 입력 허용
# 2. 날짜 입력란 연보라색 유지
# 3. Excel MergedCell read-only 오류 방지
# ============================================================

# ===== 최종본72 전기공종 동적 연동 패치 시작 =====

def _v71_electric_get_item(collection, project_index, role_index=None):
    """
    공종 namespace의 1차원 또는 2차원 배열에서
    위젯이나 변수를 안전하게 가져옵니다.
    """
    try:
        project_item = collection[project_index]

        if role_index is None:
            return project_item

        return project_item[role_index]

    except (
        IndexError,
        KeyError,
        TypeError,
        AttributeError
    ):
        return None


def _v71_electric_get_text(widget):
    """Entry 등의 현재 값을 안전하게 가져옵니다."""
    if widget is None:
        return ""

    try:
        return str(widget.get())
    except Exception:
        return ""



def _v71_electric_set_entry(
    widget,
    value,
    target_state=None
):
    """
    최종본107 최적화:
    현재 값과 새 값이 같으면 Entry의 delete/insert를 생략합니다.

    기존 코드는 값이 동일해도 매번 delete/insert를 실행하여
    Tkinter 변수 추적과 계산 이벤트가 연속 발생할 수 있었습니다.
    """
    if widget is None:
        return

    new_value = (
        ""
        if value is None
        else str(value)
    )

    try:
        current_value = str(
            widget.get()
        )
    except Exception:
        current_value = None

    try:
        current_state = str(
            widget.cget("state")
        )
    except Exception:
        current_state = None

    final_state = (
        target_state
        if target_state is not None
        else current_state
    )

    # 값이 같으면 delete/insert를 하지 않습니다.
    if current_value == new_value:
        if (
            final_state
            in (
                "normal",
                "disabled",
                "readonly",
            )
            and final_state != current_state
        ):
            try:
                widget.configure(
                    state=final_state
                )
            except Exception:
                pass

        if target_state == "normal":
            try:
                current_background = str(
                    widget.cget("bg")
                )
            except Exception:
                current_background = ""

            if current_background.lower() != "#ebd4f5":
                try:
                    widget.configure(
                        bg="#ebd4f5"
                    )
                except Exception:
                    pass

        return

    try:
        widget.configure(
            state="normal"
        )
    except Exception:
        pass

    try:
        widget.delete(
            0,
            "end"
        )

        if new_value:
            widget.insert(
                0,
                new_value
            )
    except Exception:
        pass

    if final_state in (
        "normal",
        "disabled",
        "readonly",
    ):
        try:
            widget.configure(
                state=final_state
            )
        except Exception:
            pass

    if target_state == "normal":
        try:
            widget.configure(
                state="normal",
                bg="#ebd4f5",
            )
        except Exception:
            try:
                widget.configure(
                    state="normal"
                )
            except Exception:
                pass



def _v71_electric_set_variable(variable, value):
    """Tkinter 변수를 안전하게 변경합니다."""
    if variable is None:
        return

    try:
        if str(variable.get()) != str(value):
            variable.set(value)
    except Exception:
        pass


def _v71_electric_clear_duration_label(
    labels,
    project_index,
    role_index
):
    """날짜 초기화 시 배치기간 표시도 함께 지웁니다."""
    label = _v71_electric_get_item(
        labels,
        project_index,
        role_index
    )

    if label is None:
        return

    try:
        label.configure(text="")
    except Exception:
        pass


def _v71_electric_active_sub_count(area_value):
    """
    연면적별 활성화할 상주 보조감리원 수를 반환합니다.

    30,000㎡ 미만: 0명
    30,000㎡ 이상: 보조1
    50,000㎡ 이상: 보조1~2
    70,000㎡ 이상: 보조1~3
    """
    try:
        area = float(
            str(area_value)
            .replace(",", "")
            .strip()
            or 0
        )
    except (TypeError, ValueError):
        area = 0.0

    if area >= 70000:
        return 3

    if area >= 50000:
        return 2

    if area >= 30000:
        return 1

    return 0


def _v71_electric_walk_widgets(widget):
    """하위 위젯을 재귀적으로 순회합니다."""
    try:
        children = widget.winfo_children()
    except Exception:
        children = []

    for child in children:
        yield child
        yield from _v71_electric_walk_widgets(child)



def _v71_electric_set_grade_widget_state(
    namespace,
    grade_variable,
    enabled
):
    """
    최종본107 최적화:
    등급 변수와 연결된 위젯을 매번 전체 탐색하지 않고 캐시합니다.
    """
    root = namespace.get(
        "root"
    )

    if root is None or grade_variable is None:
        return

    try:
        variable_name = str(
            grade_variable
        )
    except Exception:
        return

    cache = namespace.get(
        "_v88_electric_grade_widget_cache"
    )

    if not isinstance(
        cache,
        dict,
    ):
        cache = {}
        namespace[
            "_v88_electric_grade_widget_cache"
        ] = cache

    target_widgets = cache.get(
        variable_name
    )

    cache_is_valid = (
        isinstance(target_widgets, list)
    )

    if cache_is_valid:
        for widget in target_widgets:
            try:
                if not widget.winfo_exists():
                    cache_is_valid = False
                    break
            except Exception:
                cache_is_valid = False
                break

    if not cache_is_valid:
        variable_map = {}

        try:
            all_widgets = list(
                _v71_electric_walk_widgets(
                    root
                )
            )
        except Exception:
            all_widgets = []

        for widget in all_widgets:
            for option_name in (
                "textvariable",
                "variable",
            ):
                try:
                    option_value = str(
                        widget.cget(
                            option_name
                        )
                    )
                except Exception:
                    continue

                if not option_value:
                    continue

                variable_map.setdefault(
                    option_value,
                    []
                ).append(
                    widget
                )

        cache.clear()
        cache.update(
            variable_map
        )

        target_widgets = cache.get(
            variable_name,
            [],
        )

    desired_state = (
        "normal"
        if enabled
        else "disabled"
    )

    for widget in target_widgets:
        try:
            current_state = str(
                widget.cget("state")
            )
        except Exception:
            current_state = ""

        if current_state == desired_state:
            continue

        try:
            widget.configure(
                state=desired_state
            )
        except Exception:
            pass


def _v71_electric_refresh_calculation(
    namespace,
    project_index
):
    """날짜 및 등급 변경 후 관련 계산표를 갱신합니다."""
    function_names = (
        "electric_update_actual_cost_table",
        "electric_toggle_cost_table",
        "electric_update_individual_sheet_only",
    )

    for function_name in function_names:
        function = namespace.get(function_name)

        if not callable(function):
            continue

        try:
            if function_name == (
                "electric_update_individual_sheet_only"
            ):
                function()
            else:
                function(project_index)

        except Exception:
            pass


def _v71_electric_sync_nonresident(
    namespace,
    project_index
):
    """
    비상주 체크 상태에 따라 비상주1~3 날짜를 처리합니다.

    체크:
        전기공사 착공일·준공일 연동

    체크 해제:
        비상주1~3 투입일·종료일 공란 처리
    """
    nonresident_variables = namespace.get(
        "var_nonresident",
        []
    )

    nonresident_variable = _v71_electric_get_item(
        nonresident_variables,
        project_index
    )

    if nonresident_variable is None:
        return

    try:
        is_enabled = bool(
            nonresident_variable.get()
        )
    except Exception:
        is_enabled = False

    electric_start_entries = namespace.get(
        "entry_elec_start_date",
        []
    )

    electric_end_entries = namespace.get(
        "entry_elec_end_date",
        []
    )

    construction_start = _v71_electric_get_text(
        _v71_electric_get_item(
            electric_start_entries,
            project_index
        )
    )

    construction_end = _v71_electric_get_text(
        _v71_electric_get_item(
            electric_end_entries,
            project_index
        )
    )

    nonresident_start_entries = namespace.get(
        "entry_nonres_start",
        []
    )

    nonresident_end_entries = namespace.get(
        "entry_nonres_end",
        []
    )

    nonresident_duration_labels = namespace.get(
        "label_nonres_duration_display",
        []
    )

    for role_index in range(3):
        start_widget = _v71_electric_get_item(
            nonresident_start_entries,
            project_index,
            role_index
        )

        end_widget = _v71_electric_get_item(
            nonresident_end_entries,
            project_index,
            role_index
        )

        if is_enabled:
            _v71_electric_set_entry(
                start_widget,
                construction_start,
                "normal"
            )

            _v71_electric_set_entry(
                end_widget,
                construction_end,
                "normal"
            )

        else:
            _v71_electric_set_entry(
                start_widget,
                "",
                "normal"
            )

            _v71_electric_set_entry(
                end_widget,
                "",
                "normal"
            )

            _v71_electric_clear_duration_label(
                nonresident_duration_labels,
                project_index,
                role_index
            )


def _v71_electric_sync_sub_resident(
    namespace,
    project_index
):
    """
    연면적에 따라 상주 보조감리원 1~3을 연동합니다.

    활성 대상:
        날짜를 전기공사 기간과 연동
        등급이 none/공란이면 초급으로 지정
        날짜 및 등급 선택 위젯 활성화

    비활성 대상:
        투입일·종료일 공란
        등급을 none으로 초기화
        날짜 및 등급 선택 위젯 비활성화
    """
    area_entries = namespace.get(
        "entry_area",
        []
    )

    area_widget = _v71_electric_get_item(
        area_entries,
        project_index
    )

    area_value = _v71_electric_get_text(
        area_widget
    )

    active_count = (
        _v71_electric_active_sub_count(
            area_value
        )
    )

    electric_start_entries = namespace.get(
        "entry_elec_start_date",
        []
    )

    electric_end_entries = namespace.get(
        "entry_elec_end_date",
        []
    )

    construction_start = _v71_electric_get_text(
        _v71_electric_get_item(
            electric_start_entries,
            project_index
        )
    )

    construction_end = _v71_electric_get_text(
        _v71_electric_get_item(
            electric_end_entries,
            project_index
        )
    )

    sub_start_entries = namespace.get(
        "entry_sub_res_start",
        []
    )

    sub_end_entries = namespace.get(
        "entry_sub_res_end",
        []
    )

    sub_duration_labels = namespace.get(
        "label_sub_res_duration_display",
        []
    )

    grade_variables = namespace.get(
        "var_grades",
        []
    )

    for role_index in range(3):
        enabled = role_index < active_count

        start_widget = _v71_electric_get_item(
            sub_start_entries,
            project_index,
            role_index
        )

        end_widget = _v71_electric_get_item(
            sub_end_entries,
            project_index,
            role_index
        )

        # var_grades:
        # 0=상주 책임, 1=보조1, 2=보조2, 3=보조3
        grade_variable = _v71_electric_get_item(
            grade_variables,
            project_index,
            role_index + 1
        )

        if enabled:
            _v71_electric_set_entry(
                start_widget,
                construction_start,
                "normal"
            )

            _v71_electric_set_entry(
                end_widget,
                construction_end,
                "normal"
            )

            try:
                current_grade = str(
                    grade_variable.get()
                ).strip()
            except Exception:
                current_grade = ""

            if current_grade in (
                "",
                "none",
                "None"
            ):
                _v71_electric_set_variable(
                    grade_variable,
                    "초급"
                )

            _v71_electric_set_grade_widget_state(
                namespace,
                grade_variable,
                True
            )

        else:
            _v71_electric_set_entry(
                start_widget,
                "",
                "normal"
            )

            _v71_electric_set_entry(
                end_widget,
                "",
                "normal"
            )

            _v71_electric_set_variable(
                grade_variable,
                "none"
            )

            _v71_electric_set_grade_widget_state(
                namespace,
                grade_variable,
                False
            )

            _v71_electric_clear_duration_label(
                sub_duration_labels,
                project_index,
                role_index
            )



def _v88_electric_sync_project_immediate(
    namespace,
    project_index
):
    """
    기존 전기공종 사업별 연동 계산의 실제 실행 함수입니다.

    외부 이벤트에서는 직접 호출하지 않고
    _v71_electric_sync_project 디바운스 함수를 거칩니다.
    """
    busy_projects = namespace.setdefault(
        "_v72_electric_busy_projects",
        set()
    )

    if project_index in busy_projects:
        return

    busy_projects.add(
        project_index
    )

    try:
        _v71_electric_sync_nonresident(
            namespace,
            project_index
        )

        _v71_electric_sync_sub_resident(
            namespace,
            project_index
        )

        _v71_electric_refresh_calculation(
            namespace,
            project_index
        )

    finally:
        busy_projects.discard(
            project_index
        )


def _v71_electric_sync_project(
    namespace,
    project_index
):
    """
    최종본107 전기공종 랙 방지 디바운스 함수.

    연면적·날짜 입력 중 들어오는 계산 요청을 즉시 모두 실행하지 않고,
    마지막 요청 이후 약 150ms 뒤 한 번만 실행합니다.

    사업별로 타이머를 따로 관리하기 때문에
    다른 사업의 입력 계산과 충돌하지 않습니다.
    """
    try:
        project_index = int(
            project_index
        )
    except Exception:
        return

    busy_projects = namespace.setdefault(
        "_v72_electric_busy_projects",
        set()
    )

    # 실제 계산 중 발생한 변수 trace는 다시 예약하지 않습니다.
    if project_index in busy_projects:
        return

    root = namespace.get(
        "root"
    )

    if root is None:
        _v88_electric_sync_project_immediate(
            namespace,
            project_index
        )
        return

    pending_jobs = namespace.setdefault(
        "_v88_electric_pending_sync_jobs",
        {}
    )

    old_job = pending_jobs.pop(
        project_index,
        None,
    )

    if old_job is not None:
        try:
            root.after_cancel(
                old_job
            )
        except Exception:
            pass

    def run_scheduled_sync():
        pending_jobs.pop(
            project_index,
            None,
        )

        try:
            if not root.winfo_exists():
                return
        except Exception:
            return

        _v88_electric_sync_project_immediate(
            namespace,
            project_index
        )

    # 사업별 실행 시점을 조금씩 분산하여
    # 최초 화면 진입 시 네 사업 계산이 한 번에 몰리지 않게 합니다.
    delay_ms = 150 + (
        max(0, project_index) * 35
    )

    try:
        job_id = root.after(
            delay_ms,
            run_scheduled_sync,
        )

        pending_jobs[
            project_index
        ] = job_id

    except Exception:
        _v88_electric_sync_project_immediate(
            namespace,
            project_index
        )


def _v71_electric_sync_all(namespace):
    """등록된 모든 사업에 전기공종 연동 규칙을 적용합니다."""
    area_entries = namespace.get(
        "entry_area",
        []
    )

    for project_index in range(
        len(area_entries)
    ):
        _v71_electric_sync_project(
            namespace,
            project_index
        )


def _v71_install_electric_dynamic_rules(
    namespace,
    trade_name
):
    """
    전기공종 인스턴스에만 최종본72 동적 연동 규칙을 설치합니다.
    """
    if trade_name != "전기":
        return

    if namespace.get(
        "_v72_electric_dynamic_rules_installed"
    ):
        _v71_electric_sync_all(namespace)
        return

    namespace[
        "_v72_electric_dynamic_rules_installed"
    ] = True

    root = namespace.get("root")

    # --------------------------------------------------------
    # 1. 비상주 체크 변수 추적
    # --------------------------------------------------------
    for project_index, variable in enumerate(
        namespace.get("var_nonresident", [])
    ):
        try:
            variable.trace_add(
                "write",
                lambda *args, idx=project_index: (
                    _v71_electric_sync_project(
                        namespace,
                        idx
                    )
                )
            )
        except Exception:
            pass

    # --------------------------------------------------------
    # 2. 연면적 입력 시 즉시 반영
    # --------------------------------------------------------
    for project_index, area_widget in enumerate(
        namespace.get("entry_area", [])
    ):
        try:
            area_widget.bind(
                "<KeyRelease>",
                lambda event, idx=project_index: (
                    _v71_electric_sync_project(
                        namespace,
                        idx
                    )
                ),
                add="+"
            )
        except Exception:
            pass

        try:
            area_widget.bind(
                "<<Paste>>",
                lambda event, idx=project_index: (
                    root.after(
                        10,
                        lambda i=idx: (
                            _v71_electric_sync_project(
                                namespace,
                                i
                            )
                        )
                    )
                    if root is not None
                    else None
                ),
                add="+"
            )
        except Exception:
            pass

        try:
            area_widget.bind(
                "<FocusOut>",
                lambda event, idx=project_index: (
                    _v71_electric_sync_project(
                        namespace,
                        idx
                    )
                ),
                add="+"
            )
        except Exception:
            pass

    # --------------------------------------------------------
    # 3. 전기공사 시작일·종료일 변경 시 날짜 재연동
    # --------------------------------------------------------
    date_collections = (
        namespace.get(
            "entry_elec_start_date",
            []
        ),
        namespace.get(
            "entry_elec_end_date",
            []
        ),
    )

    for collection in date_collections:
        for project_index, date_widget in enumerate(
            collection
        ):
            try:
                date_widget.bind(
                    "<KeyRelease>",
                    lambda event, idx=project_index: (
                        _v71_electric_sync_project(
                            namespace,
                            idx
                        )
                    ),
                    add="+"
                )
            except Exception:
                pass

            try:
                date_widget.bind(
                    "<FocusOut>",
                    lambda event, idx=project_index: (
                        _v71_electric_sync_project(
                            namespace,
                            idx
                        )
                    ),
                    add="+"
                )
            except Exception:
                pass

    # --------------------------------------------------------
    # 4. 프로그램 내부에서 연면적을 자동 변경하는 경우도 처리
    # --------------------------------------------------------
    original_area_handler = namespace.get(
        "electric_handle_area_input"
    )

    if callable(original_area_handler):
        def _v72_area_handler(
            event,
            index,
            *args,
            **kwargs
        ):
            result = original_area_handler(
                event,
                index,
                *args,
                **kwargs
            )

            _v71_electric_sync_project(
                namespace,
                index
            )

            return result

        namespace[
            "electric_handle_area_input"
        ] = _v72_area_handler

    # --------------------------------------------------------
    # 5. 프로그램 내부 날짜 연동 함수 실행 후 재검사
    # --------------------------------------------------------
    original_live_update = namespace.get(
        "electric_update_live_data"
    )

    if callable(original_live_update):
        def _v72_live_update(
            index,
            *args,
            **kwargs
        ):
            result = original_live_update(
                index,
                *args,
                **kwargs
            )

            _v71_electric_sync_project(
                namespace,
                index
            )

            return result

        namespace[
            "electric_update_live_data"
        ] = _v72_live_update

    # 최종본107:
    # 전기 화면 진입 시 동일한 전체 계산을 즉시, 100ms, 500ms에
    # 총 3회 반복하던 구조를 제거하고 화면 생성 완료 후 1회만
    # 실행합니다.
    if root is not None:
        try:
            root.after_idle(
                lambda: _v71_electric_sync_all(
                    namespace
                )
            )
        except Exception:
            _v71_electric_sync_all(
                namespace
            )
    else:
        _v71_electric_sync_all(
            namespace
        )


# ===== 최종본72 전기공종 동적 연동 패치 끝 =====



# ===== 최종본78 통합배치 입력값 수동 수정 패치 =====

def _v78_get_integrated_entry_map(namespace):
    """
    통합배치 사업인 사업4(index 3)의 수정 대상 입력란을 반환합니다.
    """
    entry_map = {}

    collection_map = (
        ("사업명", "entry_names"),
        ("도급액", "entry_contract_cost"),
        (
            "도급자 관급자재비",
            "entry_contractor_material_cost"
        ),
        ("연면적", "entry_area"),
        ("건축공사 착공일", "entry_start_date"),
        ("건축공사 준공일", "entry_end_date"),
    )

    for field_name, collection_name in collection_map:
        collection = namespace.get(
            collection_name,
            []
        )

        try:
            if len(collection) > 3:
                widget = collection[3]

                if widget is not None:
                    entry_map[field_name] = widget

        except Exception:
            pass

    return entry_map


def _v78_get_entry_value(widget):
    """Entry 값을 안전하게 가져옵니다."""
    try:
        return str(widget.get())
    except Exception:
        return ""


def _v78_set_editable_lavender(widget):
    """
    통합배치 입력란을 직접 입력 가능한 상태로 만들고
    연보라색으로 표시합니다.
    """
    if widget is None:
        return

    try:
        widget.configure(
            state="normal",
            bg="#ebd4f5",
            readonlybackground="#ebd4f5",
            disabledbackground="#ebd4f5"
        )
    except Exception:
        try:
            widget.configure(
                state="normal",
                bg="#ebd4f5"
            )
        except Exception:
            pass


def _v78_set_entry_value(widget, value):
    """
    Entry의 현재 입력 상태를 유지하면서 값을 안전하게 변경합니다.
    """
    if widget is None:
        return

    try:
        current_value = str(widget.get())
    except Exception:
        current_value = ""

    value = "" if value is None else str(value)

    if current_value == value:
        _v78_set_editable_lavender(
            widget
        )
        return

    try:
        cursor_position = widget.index(
            "insert"
        )
    except Exception:
        cursor_position = None

    try:
        widget.configure(
            state="normal"
        )
    except Exception:
        pass

    try:
        widget.delete(
            0,
            "end"
        )

        if value:
            widget.insert(
                0,
                value
            )

    except Exception:
        return

    _v78_set_editable_lavender(
        widget
    )

    if cursor_position is not None:
        try:
            widget.icursor(
                min(
                    cursor_position,
                    len(value)
                )
            )
        except Exception:
            pass


def _v78_format_number_text(value):
    """
    숫자 입력값에 천 단위 콤마를 적용합니다.
    숫자가 아니면 원문을 유지합니다.
    """
    text = str(value).strip()

    if not text:
        return ""

    normalized = text.replace(
        ",",
        ""
    )

    if normalized.isdigit():
        try:
            return f"{int(normalized):,}"
        except Exception:
            return text

    # 소수점이 있는 연면적 처리
    try:
        if normalized.count(".") == 1:
            left, right = normalized.split(
                ".",
                1
            )

            if left.isdigit() and right.isdigit():
                return (
                    f"{int(left):,}.{right}"
                )
    except Exception:
        pass

    return text


def _v78_format_date_text(value):
    """
    YYYYMMDD 입력값을 YYYY.MM.DD 형태로 변환합니다.
    """
    text = str(value).strip()

    digits = "".join(
        character
        for character in text
        if character.isdigit()
    )

    if len(digits) == 8:
        return (
            f"{digits[:4]}."
            f"{digits[4:6]}."
            f"{digits[6:8]}"
        )

    return text


def _v78_capture_manual_value(
    namespace,
    field_name,
    widget
):
    """
    사용자가 직접 입력한 통합배치 값을 저장합니다.

    프로그램 내부의 delete/insert는 KeyRelease 이벤트를 만들지
    않으므로 사용자의 실제 키 입력만 수동 수정값으로 등록됩니다.
    """
    if namespace.get(
        "_v78_restoring_integrated_values",
        False
    ):
        return

    overrides = namespace.setdefault(
        "_v78_integrated_manual_overrides",
        {}
    )

    overrides[field_name] = (
        _v78_get_entry_value(widget)
    )

    _v78_set_editable_lavender(
        widget
    )


def _v78_capture_after_paste(
    namespace,
    field_name,
    widget
):
    """붙여넣기가 완료된 뒤 값을 저장합니다."""
    root = namespace.get("root")

    if root is None:
        _v78_capture_manual_value(
            namespace,
            field_name,
            widget
        )
        return

    try:
        root.after(
            10,
            lambda: _v78_capture_manual_value(
                namespace,
                field_name,
                widget
            )
        )
    except Exception:
        _v78_capture_manual_value(
            namespace,
            field_name,
            widget
        )


def _v78_format_manual_field(
    namespace,
    field_name,
    widget,
    trade_prefix
):
    """
    포커스를 벗어날 때 숫자·날짜 형식을 정리하고
    관련 계산을 갱신합니다.
    """
    current_value = _v78_get_entry_value(
        widget
    )

    if field_name in (
        "도급액",
        "도급자 관급자재비",
        "연면적"
    ):
        formatted_value = _v78_format_number_text(
            current_value
        )

    elif field_name in (
        "건축공사 착공일",
        "건축공사 준공일"
    ):
        formatted_value = _v78_format_date_text(
            current_value
        )

    else:
        formatted_value = current_value

    _v78_set_entry_value(
        widget,
        formatted_value
    )

    overrides = namespace.setdefault(
        "_v78_integrated_manual_overrides",
        {}
    )

    overrides[field_name] = formatted_value

    # 도급액·관급자재비 변경 시 추정금액을 다시 계산합니다.
    if field_name in (
        "도급액",
        "도급자 관급자재비"
    ):
        update_estimated_cost = namespace.get(
            f"{trade_prefix}_update_estimated_cost"
        )

        if callable(update_estimated_cost):
            try:
                update_estimated_cost(3)
            except Exception:
                pass

    # 연면적 변경 시 적용 방식과 관련 표를 갱신합니다.
    elif field_name == "연면적":
        area_handler = namespace.get(
            f"{trade_prefix}_handle_area_input"
        )

        if callable(area_handler):
            try:
                area_handler(
                    None,
                    3
                )
            except Exception:
                pass

    # 건축공사 날짜 변경 시 하단 공종 날짜도 연동합니다.
    elif field_name == "건축공사 착공일":
        start_sync = namespace.get(
            f"{trade_prefix}_sync_start_date"
        )

        if callable(start_sync):
            try:
                start_sync(
                    None,
                    3
                )
            except Exception:
                pass

    elif field_name == "건축공사 준공일":
        end_sync = namespace.get(
            f"{trade_prefix}_sync_end_date"
        )

        if callable(end_sync):
            try:
                end_sync(
                    None,
                    3
                )
            except Exception:
                pass

    root = namespace.get("root")

    if root is not None:
        try:
            root.after(
                20,
                lambda: _v78_restore_integrated_values(
                    namespace
                )
            )
        except Exception:
            pass


def _v78_restore_integrated_values(namespace):
    """
    자동 연동 함수가 사업4 값을 다시 입력하더라도
    사용자가 수정한 항목만 수동 입력값으로 복원합니다.
    """
    if namespace.get(
        "_v78_restoring_integrated_values",
        False
    ):
        return

    overrides = namespace.get(
        "_v78_integrated_manual_overrides",
        {}
    )

    entry_map = _v78_get_integrated_entry_map(
        namespace
    )

    namespace[
        "_v78_restoring_integrated_values"
    ] = True

    try:
        for field_name, widget in entry_map.items():
            _v78_set_editable_lavender(
                widget
            )

            if field_name in overrides:
                _v78_set_entry_value(
                    widget,
                    overrides[field_name]
                )

    finally:
        namespace[
            "_v78_restoring_integrated_values"
        ] = False


def _v78_periodic_integrated_restore(namespace):
    """
    최종본107:
    기존 200ms 반복 복원 타이머를 제거합니다.

    사업4 수동 수정값은 통합배치 계산 직후와 입력 포커스 이동 시
    복원되므로 상시 반복 타이머가 필요하지 않습니다.
    """
    try:
        _v78_restore_integrated_values(namespace)
    except Exception:
        pass



def _v78_install_integrated_editable(
    namespace,
    trade_name
):
    """
    전기·통신·소방의 통합배치 사업4 입력란에
    자동 연동과 수동 수정 보호 기능을 설치합니다.
    """
    if trade_name not in (
        "전기",
        "통신",
        "소방"
    ):
        return

    if namespace.get(
        "_v78_integrated_editable_installed",
        False
    ):
        _v78_restore_integrated_values(
            namespace
        )
        return

    prefix_map = {
        "전기": "electric",
        "통신": "communication",
        "소방": "fire",
    }

    trade_prefix = prefix_map[
        trade_name
    ]

    entry_map = _v78_get_integrated_entry_map(
        namespace
    )

    # 필요한 사업4 입력란이 아직 생성되지 않았다면
    # 화면 생성 후 다시 설치합니다.
    if not entry_map:
        root = namespace.get("root")

        if root is not None:
            try:
                root.after(
                    200,
                    lambda: _v78_install_integrated_editable(
                        namespace,
                        trade_name
                    )
                )
            except Exception:
                pass

        return

    namespace[
        "_v78_integrated_editable_installed"
    ] = True

    namespace.setdefault(
        "_v78_integrated_manual_overrides",
        {}
    )

    for field_name, widget in entry_map.items():
        _v78_set_editable_lavender(
            widget
        )

        # 기존 KeyRelease 동작이 자동 연동값으로 다시 덮어쓰는
        # 문제가 있으므로 사업4 입력란에 한해서 직접 입력 보호
        # 이벤트로 교체합니다.
        try:
            widget.bind(
                "<KeyRelease>",
                lambda event,
                name=field_name,
                target=widget: (
                    _v78_capture_manual_value(
                        namespace,
                        name,
                        target
                    )
                )
            )
        except Exception:
            pass

        try:
            widget.bind(
                "<<Paste>>",
                lambda event,
                name=field_name,
                target=widget: (
                    _v78_capture_after_paste(
                        namespace,
                        name,
                        target
                    )
                ),
                add="+"
            )
        except Exception:
            pass

        try:
            widget.bind(
                "<FocusOut>",
                lambda event,
                name=field_name,
                target=widget: (
                    _v78_format_manual_field(
                        namespace,
                        name,
                        target,
                        trade_prefix
                    )
                ),
                add="+"
            )
        except Exception:
            pass

    # 통합배치 여부가 바뀌면 먼저 자동 연동을 허용하고
    # 수동 수정된 항목만 다시 복원합니다.
    for variable in namespace.get(
        "var_integrated",
        []
    ):
        try:
            variable.trace_add(
                "write",
                lambda *args: (
                    namespace.get("root").after(
                        20,
                        lambda: _v78_restore_integrated_values(
                            namespace
                        )
                    )
                    if namespace.get("root") is not None
                    else None
                )
            )
        except Exception:
            pass

    # 사업1~3 원본 입력값 변경 후에도 수동 수정값 보호
    source_collections = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
    )

    for collection_name in source_collections:
        collection = namespace.get(
            collection_name,
            []
        )

        for source_widget in collection[:3]:
            try:
                source_widget.bind(
                    "<KeyRelease>",
                    lambda event: (
                        namespace.get("root").after(
                            20,
                            lambda: _v78_restore_integrated_values(
                                namespace
                            )
                        )
                        if namespace.get("root") is not None
                        else None
                    ),
                    add="+"
                )
            except Exception:
                pass

    _v78_restore_integrated_values(
        namespace
    )

    root = namespace.get("root")

    if root is not None:
        try:
            root.after(
                200,
                lambda: _v78_periodic_integrated_restore(
                    namespace
                )
            )
        except Exception:
            pass


# ===== 최종본78 통합배치 입력값 수동 수정 패치 끝 =====



# ===== 최종본107 통합배치 지속 연동 패치 =====

def _v80_get_source_signature(namespace):
    """
    사업1~3의 통합배치 관련 입력값과 통합배치 선택 상태를
    항목별로 반환합니다.
    """
    signature = {}

    collection_map = (
        ("사업명", "entry_names"),
        ("도급액", "entry_contract_cost"),
        (
            "도급자 관급자재비",
            "entry_contractor_material_cost"
        ),
        ("연면적", "entry_area"),
        ("건축공사 착공일", "entry_start_date"),
        ("건축공사 준공일", "entry_end_date"),
    )

    for field_name, collection_name in collection_map:
        collection = namespace.get(
            collection_name,
            []
        )

        values = []

        for widget in collection[:3]:
            try:
                values.append(
                    str(widget.get())
                )
            except Exception:
                values.append("")

        # 사업1~3 길이를 항상 동일하게 유지
        while len(values) < 3:
            values.append("")

        signature[field_name] = tuple(
            values
        )

    integrated_values = []

    for variable in namespace.get(
        "var_integrated",
        []
    )[:3]:
        try:
            integrated_values.append(
                str(variable.get())
            )
        except Exception:
            integrated_values.append("")

    while len(integrated_values) < 3:
        integrated_values.append("")

    signature[
        "통합배치 선택"
    ] = tuple(integrated_values)

    return signature


def _v80_changed_fields(
    previous_signature,
    current_signature
):
    """
    이전 값과 현재 값을 비교하여 변경된 항목을 반환합니다.
    """
    if not previous_signature:
        return set(
            current_signature.keys()
        )

    changed = set()

    all_fields = set(
        previous_signature.keys()
    ) | set(
        current_signature.keys()
    )

    for field_name in all_fields:
        if (
            previous_signature.get(field_name)
            != current_signature.get(field_name)
        ):
            changed.add(
                field_name
            )

    return changed


def _v80_clear_changed_manual_overrides(
    namespace,
    changed_fields
):
    """
    사업1~3에서 변경된 항목만 통합배치 사업4의 수동 보호를
    해제합니다.

    예:
    사업1 연면적 변경
        → 사업4 연면적은 다시 자동 연동
        → 사업4 사업명을 사용자가 직접 수정했다면 그 값은 유지
    """
    overrides = namespace.get(
        "_v78_integrated_manual_overrides"
    )

    if not isinstance(overrides, dict):
        return

    if "통합배치 선택" in changed_fields:
        # 통합배치 대상 사업 자체가 바뀌면 모든 합산값이
        # 달라질 수 있으므로 전체 수동 보호를 초기화합니다.
        overrides.clear()
        return

    for field_name in changed_fields:
        overrides.pop(
            field_name,
            None
        )


def _v80_call_optional(
    namespace,
    function_name,
    *args
):
    """namespace에 함수가 있을 경우 안전하게 실행합니다."""
    function = namespace.get(
        function_name
    )

    if not callable(function):
        return None

    try:
        return function(
            *args
        )
    except TypeError:
        try:
            return function()
        except Exception:
            return None
    except Exception:
        return None


def _v80_run_integration_judgment(
    namespace,
    trade_prefix
):
    """
    공종별 통합배치 가능 여부 관련 함수를 다시 실행합니다.
    존재하는 함수만 선택적으로 호출합니다.
    """
    # 사업별 판단 함수
    check_function_names = (
        f"{trade_prefix}_check_integration_rules",
        f"{trade_prefix}_check_integration_rule",
    )

    for project_index in range(3):
        for function_name in check_function_names:
            function = namespace.get(
                function_name
            )

            if callable(function):
                try:
                    function(
                        project_index
                    )
                except Exception:
                    pass

    # 공종별 전체 판단 함수
    total_check_names = (
        f"{trade_prefix}_update_integration_rules",
        (
            f"{trade_prefix}_update_"
            f"communication_integration_rules"
        ),
        (
            f"{trade_prefix}_update_"
            f"fire_integration_rules"
        ),
        f"{trade_prefix}_check_all_integration_rules",
    )

    for function_name in total_check_names:
        _v80_call_optional(
            namespace,
            function_name
        )


def _v80_sync_integrated_project(
    namespace,
    trade_name,
    changed_fields=None
):
    """
    통합배치 가능 판단을 다시 수행한 후 사업4 값을 갱신합니다.
    """
    if namespace.get(
        "_v80_integrated_sync_busy",
        False
    ):
        return

    prefix_map = {
        "전기": "electric",
        "통신": "communication",
        "소방": "fire",
    }

    trade_prefix = prefix_map.get(
        trade_name
    )

    if not trade_prefix:
        return

    namespace[
        "_v80_integrated_sync_busy"
    ] = True

    try:
        changed_fields = set(
            changed_fields or []
        )

        _v80_clear_changed_manual_overrides(
            namespace,
            changed_fields
        )

        # 최신 입력값으로 통합배치 가능 여부 재판단
        _v80_run_integration_judgment(
            namespace,
            trade_prefix
        )

        # 사업4 사업명·금액·면적·날짜를 다시 계산
        update_project4 = namespace.get(
            f"{trade_prefix}_update_project4_title"
        )

        if callable(update_project4):
            try:
                update_project4()
            except TypeError:
                try:
                    update_project4(None)
                except Exception:
                    pass
            except Exception:
                pass

        # 직접 수정된 다른 항목은 다시 복원
        restore_function = globals().get(
            "_v78_restore_integrated_values"
        )

        if callable(restore_function):
            root = namespace.get("root")

            if root is not None:
                try:
                    root.after(
                        30,
                        lambda: restore_function(
                            namespace
                        )
                    )
                except Exception:
                    pass

        # 통합배치 입력란 연보라색 유지
        editable_function = globals().get(
            "_v78_set_editable_lavender"
        )

        entry_map_function = globals().get(
            "_v78_get_integrated_entry_map"
        )

        if (
            callable(editable_function)
            and callable(entry_map_function)
        ):
            try:
                for widget in entry_map_function(
                    namespace
                ).values():
                    editable_function(
                        widget
                    )
            except Exception:
                pass

        try:
            namespace["root"].update_idletasks()
        except Exception:
            pass

    finally:
        namespace[
            "_v80_integrated_sync_busy"
        ] = False


def _v80_schedule_integrated_sync(
    namespace,
    trade_name,
    field_name,
    delay=500
):
    """
    최종본107:
    공종별 통합배치 연동 요청을 하나의 작업으로 병합합니다.

    여러 글자를 연속 입력하거나 여러 필드를 빠르게 변경하더라도
    마지막 입력 후 500ms가 지난 시점에 한 번만 계산합니다.
    """
    root = namespace.get("root")

    pending_fields = namespace.setdefault(
        "_v81_pending_changed_fields",
        set()
    )
    pending_fields.add(field_name)

    if root is None:
        fields = set(pending_fields)
        pending_fields.clear()

        _v80_sync_integrated_project(
            namespace,
            trade_name,
            fields
        )
        return

    old_job = namespace.get(
        "_v81_integrated_sync_job"
    )

    if old_job is not None:
        try:
            root.after_cancel(old_job)
        except Exception:
            pass

    def execute_sync():
        namespace["_v81_integrated_sync_job"] = None

        fields = set(
            namespace.get(
                "_v81_pending_changed_fields",
                set()
            )
        )

        namespace[
            "_v81_pending_changed_fields"
        ] = set()

        _v80_sync_integrated_project(
            namespace,
            trade_name,
            fields
        )

        try:
            namespace[
                "_v80_source_signature"
            ] = _v80_get_source_signature(
                namespace
            )
        except Exception:
            pass

    try:
        namespace["_v81_integrated_sync_job"] = root.after(
            max(250, int(delay)),
            execute_sync
        )
    except Exception:
        execute_sync()



def _v80_poll_source_changes(
    namespace,
    trade_name
):
    """
    최종본107:
    KeyRelease가 발생하지 않는 프로그램 내부 변경만 보조적으로 감지합니다.

    기존 250ms마다 즉시 전체 계산하던 구조를 제거하고,
    1200ms 간격으로 값만 비교한 뒤 변경된 경우 지연 연동합니다.
    """
    root = namespace.get("root")

    if root is None:
        return

    try:
        if not root.winfo_exists():
            return
    except Exception:
        return

    try:
        current_signature = _v80_get_source_signature(
            namespace
        )

        previous_signature = namespace.get(
            "_v80_source_signature",
            {}
        )

        changed_fields = _v80_changed_fields(
            previous_signature,
            current_signature
        )

        if changed_fields:
            # 동일 변경을 다음 감시 주기에 다시 발견하지 않도록
            # 계산 예약 전에 최신 서명을 먼저 기록합니다.
            namespace[
                "_v80_source_signature"
            ] = current_signature

            pending_fields = namespace.setdefault(
                "_v81_pending_changed_fields",
                set()
            )
            pending_fields.update(changed_fields)

            _v80_schedule_integrated_sync(
                namespace,
                trade_name,
                "__poll__",
                delay=500
            )

    except Exception:
        pass

    try:
        namespace["_v81_poll_job"] = root.after(
            1200,
            lambda: _v80_poll_source_changes(
                namespace,
                trade_name
            )
        )
    except Exception:
        pass



def _v81_set_entry_if_changed(widget, value):
    """값이 다를 때만 Entry를 수정합니다."""
    if widget is None:
        return

    value = "" if value is None else str(value)

    try:
        if str(widget.get()) == value:
            return
    except Exception:
        return

    try:
        old_state = str(widget.cget("state"))
    except Exception:
        old_state = "normal"

    try:
        if old_state != "normal":
            widget.configure(state="normal")

        widget.delete(0, "end")

        if value:
            widget.insert(0, value)

    except Exception:
        pass

    finally:
        if old_state in ("readonly", "disabled"):
            try:
                widget.configure(state=old_state)
            except Exception:
                pass


def _v81_format_date_widget(widget):
    """날짜가 8자리 완성된 경우에만 YYYY.MM.DD 형식으로 변경합니다."""
    if widget is None:
        return

    try:
        original = str(widget.get())
    except Exception:
        return

    digits = "".join(
        character
        for character in original
        if character.isdigit()
    )

    if len(digits) != 8:
        return

    formatted = (
        f"{digits[:4]}."
        f"{digits[4:6]}."
        f"{digits[6:8]}"
    )

    _v81_set_entry_if_changed(
        widget,
        formatted
    )


def _v81_call_namespace_function(
    namespace,
    function_name,
    *args
):
    """공종 namespace에 함수가 존재하는 경우에만 실행합니다."""
    function = namespace.get(function_name)

    if not callable(function):
        return None

    try:
        return function(*args)
    except TypeError:
        try:
            return function()
        except Exception:
            return None
    except Exception:
        return None


def _v81_execute_source_actions(
    namespace,
    trade_name
):
    """
    지연 병합된 사업1~3 입력 작업을 실제로 실행합니다.
    """
    if namespace.get(
        "_v81_source_action_running",
        False
    ):
        return

    prefix_map = {
        "전기": "electric",
        "통신": "communication",
        "소방": "fire",
    }

    trade_prefix = prefix_map.get(trade_name)

    if not trade_prefix:
        return

    actions = set(
        namespace.get(
            "_v81_pending_source_actions",
            set()
        )
    )

    changed_fields = set(
        namespace.get(
            "_v81_pending_changed_fields",
            set()
        )
    )

    namespace["_v81_pending_source_actions"] = set()
    namespace["_v81_pending_changed_fields"] = set()
    namespace["_v81_source_action_job"] = None
    namespace["_v81_source_action_running"] = True

    try:
        # 사업별로 처리하여 동일 사업의 도급액과 관급자재비가
        # 함께 변경된 경우 추정금액 계산을 한 번만 실행합니다.
        for project_index in range(3):
            project_actions = {
                field_name
                for field_name, index in actions
                if index == project_index
            }

            if not project_actions:
                continue

            # 사업명
            if "사업명" in project_actions:
                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_sync_site_name",
                    None,
                    project_index
                )

            # 도급액 또는 도급자 관급자재비
            if project_actions.intersection({
                "도급액",
                "도급자 관급자재비"
            }):
                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_update_estimated_cost",
                    project_index
                )

            # 연면적
            if "연면적" in project_actions:
                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_handle_area_input",
                    None,
                    project_index
                )

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_check_required_supervisor",
                    project_index
                )

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_apply_role_autofill",
                    project_index
                )

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_update_communication_info_for_project",
                    project_index
                )

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_update_fire_supervision_table",
                    project_index
                )

            # 건축공사 착공일
            if "건축공사 착공일" in project_actions:
                try:
                    widget = namespace.get(
                        "entry_start_date",
                        []
                    )[project_index]
                except Exception:
                    widget = None

                _v81_format_date_widget(widget)

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_sync_start_date",
                    None,
                    project_index
                )

            # 건축공사 준공일
            if "건축공사 준공일" in project_actions:
                try:
                    widget = namespace.get(
                        "entry_end_date",
                        []
                    )[project_index]
                except Exception:
                    widget = None

                _v81_format_date_widget(widget)

                _v81_call_namespace_function(
                    namespace,
                    f"{trade_prefix}_sync_end_date",
                    None,
                    project_index
                )

        # 모든 사업별 계산이 끝난 후 통합배치 사업4는 한 번만 갱신합니다.
        _v80_sync_integrated_project(
            namespace,
            trade_name,
            changed_fields
        )

        try:
            namespace[
                "_v80_source_signature"
            ] = _v80_get_source_signature(
                namespace
            )
        except Exception:
            pass

    finally:
        namespace["_v81_source_action_running"] = False


def _v81_queue_source_action(
    namespace,
    trade_name,
    field_name,
    project_index,
    delay=500
):
    """
    키 입력을 즉시 계산하지 않고 마지막 입력 후 한 번만 처리합니다.
    """
    root = namespace.get("root")

    actions = namespace.setdefault(
        "_v81_pending_source_actions",
        set()
    )
    actions.add((field_name, project_index))

    changed_fields = namespace.setdefault(
        "_v81_pending_changed_fields",
        set()
    )
    changed_fields.add(field_name)

    old_job = namespace.get(
        "_v81_source_action_job"
    )

    if root is None:
        _v81_execute_source_actions(
            namespace,
            trade_name
        )
        return

    if old_job is not None:
        try:
            root.after_cancel(old_job)
        except Exception:
            pass

    try:
        namespace["_v81_source_action_job"] = root.after(
            max(250, int(delay)),
            lambda: _v81_execute_source_actions(
                namespace,
                trade_name
            )
        )
    except Exception:
        _v81_execute_source_actions(
            namespace,
            trade_name
        )


def _v81_bind_source_widget(
    namespace,
    trade_name,
    widget,
    field_name,
    project_index
):
    """
    기존 중복 KeyRelease 바인딩을 제거하고
    지연 실행 바인딩 하나만 설치합니다.
    """
    if widget is None:
        return

    def schedule(event=None, delay=500):
        _v81_queue_source_action(
            namespace,
            trade_name,
            field_name,
            project_index,
            delay
        )

    try:
        # add="+"를 사용하지 않아 기존 중복 KeyRelease 콜백을 제거합니다.
        widget.bind(
            "<KeyRelease>",
            lambda event: schedule(event, 500)
        )
    except Exception:
        pass

    try:
        # 붙여넣기 완료 후 값을 읽도록 약간 지연합니다.
        widget.bind(
            "<<Paste>>",
            lambda event: (
                namespace.get("root").after(
                    20,
                    lambda: schedule(None, 500)
                )
                if namespace.get("root") is not None
                else schedule(None, 500)
            ),
            add="+"
        )
    except Exception:
        pass

    try:
        # 입력란을 벗어날 때 대기 중인 내용을 빠르게 반영합니다.
        widget.bind(
            "<FocusOut>",
            lambda event: schedule(event, 80),
            add="+"
        )
    except Exception:
        pass


def _v80_install_continuous_integration(
    namespace,
    trade_name
):
    """
    최종본107 최적화 설치 함수.

    사업1~3 입력은 지연 병합하고 사업4 수동 입력란은 건드리지 않습니다.
    """
    if trade_name not in (
        "전기",
        "통신",
        "소방"
    ):
        return

    if namespace.get(
        "_v80_continuous_integration_installed",
        False
    ):
        return

    namespace[
        "_v80_continuous_integration_installed"
    ] = True

    collection_map = (
        ("사업명", "entry_names"),
        ("도급액", "entry_contract_cost"),
        (
            "도급자 관급자재비",
            "entry_contractor_material_cost"
        ),
        ("연면적", "entry_area"),
        ("건축공사 착공일", "entry_start_date"),
        ("건축공사 준공일", "entry_end_date"),
    )

    # 사업1~3만 최적화 바인딩을 설치합니다.
    # 사업4는 최종본78의 수동 수정 보호 바인딩을 그대로 유지합니다.
    for field_name, collection_name in collection_map:
        collection = namespace.get(
            collection_name,
            []
        )

        for project_index, widget in enumerate(
            collection[:3]
        ):
            _v81_bind_source_widget(
                namespace,
                trade_name,
                widget,
                field_name,
                project_index
            )

    # 통합배치 O/X 변경은 입력 빈도가 낮으므로 trace를 유지하되
    # 전체 계산은 debounce 처리합니다.
    for variable in namespace.get(
        "var_integrated",
        []
    )[:3]:
        try:
            variable.trace_add(
                "write",
                lambda *args: _v80_schedule_integrated_sync(
                    namespace,
                    trade_name,
                    "통합배치 선택",
                    delay=250
                )
            )
        except Exception:
            pass

    try:
        namespace[
            "_v80_source_signature"
        ] = _v80_get_source_signature(
            namespace
        )
    except Exception:
        namespace[
            "_v80_source_signature"
        ] = {}

    root = namespace.get("root")

    if root is not None:
        try:
            # 화면 생성이 끝난 뒤 최초 연동을 한 번만 수행합니다.
            root.after(
                600,
                lambda: _v80_schedule_integrated_sync(
                    namespace,
                    trade_name,
                    "초기화",
                    delay=250
                )
            )
        except Exception:
            pass

        try:
            # KeyRelease가 없는 프로그램 내부 변경 감시
            root.after(
                1200,
                lambda: _v80_poll_source_changes(
                    namespace,
                    trade_name
                )
            )
        except Exception:
            pass



# ===== 최종본107 통합배치 지속 연동 패치 끝 =====



# ===== 최종본107 전기공종 입력 랙 개선 패치 =====

def _v85_install_electric_input_lag_fix(
    namespace,
    trade_name
):
    """
    전기공종의 입력 이벤트만 최종본107 지연 병합 방식으로
    다시 정리합니다.

    최종본107에서는 V80 지연 바인딩을 설치한 뒤 V72 전기 규칙이
    연면적과 전기공사 날짜 입력란에 즉시 계산 바인딩을 다시
    추가하여 한 번의 키 입력에 무거운 계산이 중복 실행될 수
    있었습니다.

    최종본107에서는:
    1. 사업1~3 기본 입력란의 KeyRelease를 V80 지연 병합으로 통일
    2. 전기공사 착공일/준공일은 날짜 표시는 즉시 정리
    3. 무거운 하단 계산은 마지막 입력 후 350ms에 한 번만 실행
    """

    if trade_name != "전기":
        return

    if namespace.get(
        "_v85_electric_input_lag_fix_installed",
        False
    ):
        return

    namespace[
        "_v85_electric_input_lag_fix_installed"
    ] = True

    root = namespace.get("root")

    if root is None:
        return

    # --------------------------------------------------------
    # 1. 사업1~3 기본 입력란
    # --------------------------------------------------------
    # 최종본107의 V80 처리 방식과 같은 필드명만 사용합니다.
    # add="+"를 사용하지 않으므로 이전의 중복 KeyRelease 계산을
    # 제거하고 마지막 입력 후 한 번만 처리합니다.
    source_collections = (
        ("사업명", "entry_names"),
        ("도급액", "entry_contract_cost"),
        (
            "도급자 관급자재비",
            "entry_contractor_material_cost"
        ),
        ("연면적", "entry_area"),
        ("건축공사 착공일", "entry_start_date"),
        ("건축공사 준공일", "entry_end_date"),
    )

    for field_name, collection_name in source_collections:
        collection = namespace.get(
            collection_name,
            []
        )

        for project_index, widget in enumerate(
            collection[:3]
        ):
            if widget is None:
                continue

            try:
                widget.bind(
                    "<KeyRelease>",
                    lambda event,
                    name=field_name,
                    idx=project_index: (
                        _v81_queue_source_action(
                            namespace,
                            trade_name,
                            name,
                            idx,
                            delay=500
                        )
                    )
                )
            except Exception:
                pass

    # --------------------------------------------------------
    # 2. 전기공사 착공일/준공일 입력란
    # --------------------------------------------------------
    # 날짜 입력 자체는 즉시 표시하되, 기간/대가/산출표 계산은
    # 마지막 입력 후 350ms에 한 번만 실행합니다.
    date_jobs = namespace.setdefault(
        "_v85_electric_date_jobs",
        {}
    )

    def schedule_electric_date_update(
        event,
        project_index,
        field_key,
    ):
        formatter = namespace.get(
            "electric_format_only_date"
        )

        if event is not None and callable(formatter):
            try:
                formatter(event)
            except Exception:
                pass

        old_job = date_jobs.get(
            (project_index, field_key)
        )

        if old_job is not None:
            try:
                root.after_cancel(
                    old_job
                )
            except Exception:
                pass

        def execute_update():
            date_jobs.pop(
                (project_index, field_key),
                None,
            )

            live_update = namespace.get(
                "electric_update_live_data"
            )

            if callable(live_update):
                try:
                    live_update(
                        project_index
                    )
                except Exception:
                    pass

            required_check = namespace.get(
                "electric_check_required_supervisor"
            )

            if callable(required_check):
                try:
                    required_check(
                        project_index
                    )
                except Exception:
                    pass

        try:
            date_jobs[
                (project_index, field_key)
            ] = root.after(
                350,
                execute_update,
            )

        except Exception:
            execute_update()

    date_collections = (
        (
            "전기공사 착공일",
            namespace.get(
                "entry_elec_start_date",
                []
            ),
        ),
        (
            "전기공사 준공일",
            namespace.get(
                "entry_elec_end_date",
                []
            ),
        ),
    )

    for field_key, collection in date_collections:
        for project_index, widget in enumerate(
            collection
        ):
            if widget is None:
                continue

            try:
                widget.bind(
                    "<KeyRelease>",
                    lambda event,
                    idx=project_index,
                    key=field_key: (
                        schedule_electric_date_update(
                            event,
                            idx,
                            key,
                        )
                    )
                )
            except Exception:
                pass


# ===== 최종본107 전기공종 입력 랙 개선 패치 끝 =====

def _v85_apply_runtime_patch(namespace, trade_name):
    """
    공종 인스턴스가 생성된 직후 UI와 엑셀 버튼을 최종본71 방식으로 수정합니다.
    """
    try:
        # 최종본107: 통합배치 지속 연동 설치
        _v80_install_continuous_integration(
            namespace,
            trade_name
        )

        # 최종본78: 통합배치 사업4 수동 수정 기능 설치
        _v78_install_integrated_editable(
            namespace,
            trade_name
        )

        # 최종본72: 전기공종 날짜·등급 동적 연동
        _v71_install_electric_dynamic_rules(
            namespace,
            trade_name
        )

        # 최종본107: V72가 추가한 즉시 계산 바인딩을
        # 지연 병합 방식으로 다시 정리합니다.
        _v85_install_electric_input_lag_fix(
            namespace,
            trade_name
        )

        if trade_name == "전기":
            _v71_patch_electric_supervision(
                namespace,
                trade_name
            )

        _v71_patch_excel_buttons(
            namespace,
            trade_name
        )

        # 화면 전환·사업 추가 후에도 버튼/UI가 유지되도록 재적용
        root = namespace.get("root")

        if root is not None:
            root.after(
                200,
                lambda: (
                    _v71_patch_electric_supervision(
                        namespace,
                        trade_name
                    ),
                    _v71_patch_excel_buttons(
                        namespace,
                        trade_name
                    )
                )
            )

            root.after(
                800,
                lambda: (
                    _v71_patch_electric_supervision(
                        namespace,
                        trade_name
                    ),
                    _v71_patch_excel_buttons(
                        namespace,
                        trade_name
                    )
                )
            )

    except Exception:
        import traceback
        print("[최종본71 패치 오류]")
        print(traceback.format_exc())


# =================================================================
# 최종본107 공통·전기·통신·소방 보완 패치
# =================================================================

_V87_RUNTIME_PATCH = True

_v87_original_electric_sync_sub_resident = None


def _v87_safe_get(
    collection,
    index,
    sub_index=None,
):
    try:
        value = collection[index]

        if sub_index is not None:
            value = value[sub_index]

        return value

    except Exception:
        return None


def _v87_entry_text(widget):
    try:
        return str(widget.get()).strip()

    except Exception:
        return ""


def _v87_clear_entry(widget):
    """
    Entry의 기존 상태를 유지하면서
    표시값만 제거합니다.
    """
    if widget is None:
        return

    try:
        previous_state = str(
            widget.cget("state")
        )

    except Exception:
        previous_state = "normal"

    try:
        if previous_state != "normal":
            widget.configure(
                state="normal"
            )

        widget.delete(
            0,
            "end"
        )

    except Exception:
        pass

    finally:
        if previous_state in (
            "readonly",
            "disabled",
        ):
            try:
                widget.configure(
                    state=previous_state
                )

            except Exception:
                pass


def _v87_clear_entry_collection(
    collection,
):
    if collection is None:
        return

    try:
        items = list(collection)

    except Exception:
        return

    for widget in items:
        _v87_clear_entry(widget)


# =================================================================
# Excel 산출조서 A4 세로 한 페이지 및 표 정리
# =================================================================

def _v87_is_calculation_sheet(
    sheet_name,
):
    normalized = str(
        sheet_name or ""
    ).replace(
        " ",
        ""
    )

    target_names = (
        "개별(정상요율)산출조서",
        "통합(정상요율)산출조서",
        "통합(조정요율)산출조서",
    )

    return any(
        target in normalized
        for target in target_names
    )


def _v87_apply_a4_report_format(
    worksheet,
    sheet_name,
):
    if worksheet is None:
        return

    if not _v87_is_calculation_sheet(
        sheet_name
    ):
        return

    try:
        from openpyxl.styles import (
            Alignment,
            Border,
            Side,
        )

        from openpyxl.utils import (
            get_column_letter,
        )

    except Exception:
        return

    try:
        max_row = max(
            1,
            int(worksheet.max_row),
        )

        max_column = max(
            1,
            int(worksheet.max_column),
        )

    except Exception:
        return

    # A4 세로 설정
    try:
        worksheet.page_setup.orientation = (
            worksheet.ORIENTATION_PORTRAIT
        )

    except Exception:
        worksheet.page_setup.orientation = (
            "portrait"
        )

    try:
        worksheet.page_setup.paperSize = (
            worksheet.PAPERSIZE_A4
        )

    except Exception:
        worksheet.page_setup.paperSize = "9"

    try:
        worksheet.sheet_properties.pageSetUpPr.fitToPage = (
            True
        )

    except Exception:
        pass

    worksheet.page_setup.fitToWidth = 1
    worksheet.page_setup.fitToHeight = 1

    try:
        worksheet.page_setup.scale = None

    except Exception:
        pass

    try:
        worksheet.sheet_view.showGridLines = False

    except Exception:
        pass

    try:
        worksheet.print_options.horizontalCentered = (
            True
        )

        worksheet.print_options.verticalCentered = (
            True
        )

    except Exception:
        pass

    try:
        worksheet.page_margins.left = 0.15
        worksheet.page_margins.right = 0.15
        worksheet.page_margins.top = 0.20
        worksheet.page_margins.bottom = 0.20
        worksheet.page_margins.header = 0.05
        worksheet.page_margins.footer = 0.05

    except Exception:
        pass

    # 전체 열과 행을 같은 크기로 정리
    for column_number in range(
        1,
        max_column + 1,
    ):
        column_letter = get_column_letter(
            column_number
        )

        worksheet.column_dimensions[
            column_letter
        ].width = 3.2

    for row_number in range(
        1,
        max_row + 1,
    ):
        worksheet.row_dimensions[
            row_number
        ].height = 18

    thin_side = Side(
        style="thin",
        color="808080",
    )

    thin_border = Border(
        left=thin_side,
        right=thin_side,
        top=thin_side,
        bottom=thin_side,
    )

    for row in worksheet.iter_rows(
        min_row=1,
        max_row=max_row,
        min_col=1,
        max_col=max_column,
    ):
        for cell in row:
            try:
                cell.border = thin_border

                old_alignment = cell.alignment

                cell.alignment = Alignment(
                    horizontal=(
                        old_alignment.horizontal
                        or "center"
                    ),
                    vertical="center",
                    wrap_text=True,
                    shrink_to_fit=True,
                    text_rotation=(
                        old_alignment.text_rotation
                        or 0
                    ),
                )

            except Exception:
                pass

    try:
        last_column = get_column_letter(
            max_column
        )

        worksheet.print_area = (
            f"A1:{last_column}{max_row}"
        )

    except Exception:
        pass


def _v87_install_excel_sheet_patch():
    global _v71_write_widget_sheet

    if globals().get(
        "_v87_excel_sheet_patch_installed",
        False,
    ):
        return

    original_writer = globals().get(
        "_v71_write_widget_sheet"
    )

    if not callable(original_writer):
        return

    globals()[
        "_v87_excel_sheet_patch_installed"
    ] = True

    def patched_writer(
        workbook,
        sheet_name,
        root_widget,
        excluded_roots=None,
    ):
        worksheet = original_writer(
            workbook,
            sheet_name,
            root_widget,
            excluded_roots=excluded_roots,
        )

        _v87_apply_a4_report_format(
            worksheet,
            sheet_name,
        )

        return worksheet

    _v71_write_widget_sheet = patched_writer


