def _v87_enable_assistant_grade_buttons(
    namespace,
):
    grade_variables = namespace.get(
        "var_grades",
        [],
    )

    for project_index in range(
        len(grade_variables)
    ):
        for role_index in (
            1,
            2,
            3,
        ):
            grade_variable = _v87_safe_get(
                grade_variables,
                project_index,
                role_index,
            )

            if grade_variable is None:
                continue

            try:
                _v71_electric_set_grade_widget_state(
                    namespace,
                    grade_variable,
                    True,
                )

            except Exception:
                pass


def _v87_electric_sync_sub_keep_grades(
    namespace,
    project_index,
):
    """
    연면적별 날짜 자동연동은 유지하고
    상주 보조등급은 사용자의 선택값을 유지합니다.
    """
    original = globals().get(
        "_v87_original_electric_sync_sub_resident"
    )

    if not callable(original):
        return

    grade_variables = namespace.get(
        "var_grades",
        [],
    )

    saved_grades = []

    for role_index in (
        1,
        2,
        3,
    ):
        variable = _v87_safe_get(
            grade_variables,
            project_index,
            role_index,
        )

        try:
            saved_grades.append(
                (
                    variable,
                    str(variable.get()),
                )
            )

        except Exception:
            saved_grades.append(
                (
                    variable,
                    None,
                )
            )

    original(
        namespace,
        project_index,
    )

    for variable, saved_value in saved_grades:
        if variable is None:
            continue

        if saved_value is not None:
            try:
                variable.set(
                    saved_value
                )

            except Exception:
                pass

        try:
            _v71_electric_set_grade_widget_state(
                namespace,
                variable,
                True,
            )

        except Exception:
            pass


def _v87_install_electric_assistant_grade_patch():
    global _v71_electric_sync_sub_resident
    global _v87_original_electric_sync_sub_resident

    if globals().get(
        "_v87_assistant_grade_patch_installed",
        False,
    ):
        return

    original = globals().get(
        "_v71_electric_sync_sub_resident"
    )

    if not callable(original):
        return

    globals()[
        "_v87_assistant_grade_patch_installed"
    ] = True

    _v87_original_electric_sync_sub_resident = (
        original
    )

    _v71_electric_sync_sub_resident = (
        _v87_electric_sync_sub_keep_grades
    )


