# 전기 비선택 산출방식 표 값 제거
# =================================================================

def _v87_electric_method_is_fixed(
    namespace,
    project_index,
):
    area_entries = namespace.get(
        "entry_area",
        [],
    )

    area_widget = _v87_safe_get(
        area_entries,
        project_index,
    )

    raw_area = _v87_entry_text(
        area_widget
    ).replace(
        ",",
        "",
    )

    if raw_area:
        try:
            return float(raw_area) < 10000

        except Exception:
            pass

    method_labels = namespace.get(
        "label_area_method_display",
        [],
    )

    method_label = _v87_safe_get(
        method_labels,
        project_index,
    )

    try:
        method_text = str(
            method_label.cget("text")
        )

    except Exception:
        method_text = ""

    if "실비" in method_text:
        return False

    if "정액" in method_text:
        return True

    return None


def _v87_enforce_electric_cost_method(
    namespace,
    project_index,
):
    is_fixed = _v87_electric_method_is_fixed(
        namespace,
        project_index,
    )

    if is_fixed is None:
        return

    fixed_100 = namespace.get(
        "cost_entries_100",
        [],
    )

    fixed_split = namespace.get(
        "cost_entries_split",
        [],
    )

    actual_split = namespace.get(
        "cost_entries_actual_split",
        [],
    )

    step1_entries = namespace.get(
        "entry_step1",
        [],
    )

    step2_entries = namespace.get(
        "entry_step2",
        [],
    )

    step1_labels = namespace.get(
        "lbl_step1_formula",
        [],
    )

    step2_labels = namespace.get(
        "lbl_step2_formula",
        [],
    )

    if is_fixed:
        # 정액적산방식인 경우 실비표 제거
        actual_entries = _v87_safe_get(
            actual_split,
            project_index,
        )

        _v87_clear_entry_collection(
            actual_entries
        )

    else:
        # 실비정액가산방식인 경우 정액표 제거
        fixed_100_entries = _v87_safe_get(
            fixed_100,
            project_index,
        )

        fixed_split_entries = _v87_safe_get(
            fixed_split,
            project_index,
        )

        _v87_clear_entry_collection(
            fixed_100_entries
        )

        _v87_clear_entry_collection(
            fixed_split_entries
        )

        _v87_clear_entry(
            _v87_safe_get(
                step1_entries,
                project_index,
            )
        )

        _v87_clear_entry(
            _v87_safe_get(
                step2_entries,
                project_index,
            )
        )

        for labels in (
            step1_labels,
            step2_labels,
        ):
            label = _v87_safe_get(
                labels,
                project_index,
            )

            try:
                label.configure(
                    text=""
                )

            except Exception:
                pass


def _v87_schedule_method_cleanup(
    namespace,
    project_index,
):
    root = namespace.get(
        "root"
    )

    def execute():
        _v87_enforce_electric_cost_method(
            namespace,
            project_index,
        )

    if root is not None:
        try:
            root.after_idle(
                execute
            )
            return

        except Exception:
            pass

    execute()


def _v87_wrap_electric_calculation_function(
    namespace,
    function_name,
):
    original = namespace.get(
        function_name
    )

    if not callable(original):
        return

    marker_name = (
        "_v87_wrapped_"
        + function_name
    )

    if namespace.get(marker_name):
        return

    namespace[marker_name] = True

    def wrapped(*args, **kwargs):
        result = original(
            *args,
            **kwargs
        )

        project_index = None

        for value in args[:2]:
            if isinstance(value, int):
                project_index = value
                break

        if project_index is None:
            project_index = kwargs.get(
                "index"
            )

        if isinstance(
            project_index,
            int,
        ):
            _v87_schedule_method_cleanup(
                namespace,
                project_index,
            )

        else:
            for index in range(
                len(
                    namespace.get(
                        "entry_area",
                        [],
                    )
                )
            ):
                _v87_schedule_method_cleanup(
                    namespace,
                    index,
                )

        return result

    namespace[function_name] = wrapped


def _v87_install_electric_cost_method_patch(
    namespace,
):
    for function_name in (
        "electric_toggle_cost_table",
        "electric_update_actual_cost_table",
        "electric_calculate_steps",
        "electric_handle_area_input",
        "electric_update_live_data",
        "electric_update_calc_all",
    ):
        _v87_wrap_electric_calculation_function(
            namespace,
            function_name,
        )

    root = namespace.get(
        "root"
    )

    area_entries = namespace.get(
        "entry_area",
        [],
    )

    for project_index, area_entry in enumerate(
        area_entries
    ):
        if area_entry is None:
            continue

        def schedule_cleanup(
            event=None,
            index=project_index,
        ):
            def execute():
                _v87_enforce_electric_cost_method(
                    namespace,
                    index,
                )

                _v87_enable_assistant_grade_buttons(
                    namespace
                )

            if root is not None:
                try:
                    root.after(
                        20,
                        execute,
                    )
                    return

                except Exception:
                    pass

            execute()

        try:
            area_entry.bind(
                "<Return>",
                schedule_cleanup,
                add="+",
            )

            area_entry.bind(
                "<FocusOut>",
                schedule_cleanup,
                add="+",
            )

        except Exception:
            pass

    for project_index in range(
        len(area_entries)
    ):
        _v87_schedule_method_cleanup(
            namespace,
            project_index,
        )


