# 사업4 비상주 감리원수 통합 산출조서 재연동
# =================================================================

def _v87_refresh_project4_personnel(
    namespace,
    trade_name,
):
    """
    사업4(index 3)의 입력표를 먼저 갱신한 뒤
    통합 정상·조정요율 산출조서를 갱신합니다.
    """
    project_index = 3

    refresh_names = (
        "electric_toggle_cost_table",
        "electric_update_actual_cost_table",
        "electric_update_fire_actual_cost_table",
        "communication_toggle_cost_table",
        "communication_update_actual_cost_table",
        "fire_toggle_cost_table",
        "fire_update_actual_cost_table",
    )

    for function_name in refresh_names:
        function = namespace.get(
            function_name
        )

        if not callable(function):
            continue

        try:
            function(
                project_index
            )

        except TypeError:
            try:
                function()

            except Exception:
                pass

        except Exception:
            pass

    if trade_name == "전기":
        _v87_enforce_electric_cost_method(
            namespace,
            project_index,
        )


def _v87_find_integrated_update_name(
    namespace,
    trade_name,
):
    preferred = {
        "전기": (
            "electric_update_integrated_sheets"
        ),
        "통신": (
            "communication_update_integrated_sheets"
        ),
        "소방": (
            "fire_update_integrated_sheets"
        ),
    }.get(trade_name)

    if (
        preferred
        and callable(namespace.get(preferred))
    ):
        return preferred

    for function_name in (
        "electric_update_integrated_sheets",
        "communication_update_integrated_sheets",
        "fire_update_integrated_sheets",
        "update_integrated_sheets",
    ):
        if callable(
            namespace.get(function_name)
        ):
            return function_name

    return None


def _v87_install_integrated_personnel_patch(
    namespace,
    trade_name,
):
    """
    사업4 비상주 감리원수를 통합 정상·조정요율 산출조서에
    연동합니다.

    성능 최적화:
    - 계산 중 발생한 trace 이벤트 무시
    - 기존 예약을 취소하고 마지막 요청만 실행
    - 150ms 디바운스 적용
    - KeyRelease 전체 재계산 제거
    - FocusOut 또는 Enter 시 계산
    """
    function_name = (
        _v87_find_integrated_update_name(
            namespace,
            trade_name,
        )
    )

    if not function_name:
        return

    marker = (
        "_v87_integrated_personnel_patch_"
        + function_name
    )

    if namespace.get(marker):
        return

    original = namespace.get(
        function_name
    )

    if not callable(original):
        return

    namespace[marker] = True

    busy_key = (
        "_v87_integrated_personnel_busy"
    )

    pending_key = (
        "_v87_integrated_personnel_pending_job"
    )

    namespace[busy_key] = False
    namespace[pending_key] = None

    def wrapped(*args, **kwargs):
        """
        통합 산출조서 갱신 전 사업4 비상주 감리원수를
        한 번만 다시 계산합니다.
        """
        if namespace.get(busy_key):
            return original(
                *args,
                **kwargs
            )

        namespace[busy_key] = True

        try:
            _v87_refresh_project4_personnel(
                namespace,
                trade_name,
            )

            return original(
                *args,
                **kwargs
            )

        finally:
            namespace[busy_key] = False

    namespace[function_name] = wrapped

    root = namespace.get(
        "root"
    )

    def execute_integrated_refresh():
        """
        예약된 통합 산출조서 갱신을 실행합니다.
        """
        namespace[pending_key] = None

        if namespace.get(busy_key):
            return

        update_function = namespace.get(
            function_name
        )

        if not callable(update_function):
            return

        try:
            update_function()

        except Exception:
            pass

    def schedule_integrated_refresh(*args):
        """
        여러 변경 이벤트가 연속 발생해도
        마지막 요청만 한 번 실행합니다.
        """
        if namespace.get(busy_key):
            return

        if root is None:
            execute_integrated_refresh()
            return

        previous_job = namespace.get(
            pending_key
        )

        if previous_job is not None:
            try:
                root.after_cancel(
                    previous_job
                )

            except Exception:
                pass

            namespace[pending_key] = None

        try:
            new_job = root.after(
                150,
                execute_integrated_refresh,
            )

            namespace[pending_key] = new_job

        except Exception:
            namespace[pending_key] = None
            execute_integrated_refresh()

    # ------------------------------------------------------------
    # 사업4 비상주 감리원 등급 변경 감지
    # ------------------------------------------------------------

    grade_variables = namespace.get(
        "var_grades",
        [],
    )

    for role_index in (
        4,
        5,
        6,
    ):
        variable = _v87_safe_get(
            grade_variables,
            3,
            role_index,
        )

        if variable is None:
            continue

        try:
            variable.trace_add(
                "write",
                schedule_integrated_refresh,
            )

        except Exception:
            pass

    # ------------------------------------------------------------
    # 사업4 비상주 활성화 상태 변경 감지
    # ------------------------------------------------------------

    nonresident_variables = namespace.get(
        "var_nonresident",
        [],
    )

    nonresident_variable = _v87_safe_get(
        nonresident_variables,
        3,
    )

    if nonresident_variable is not None:
        try:
            nonresident_variable.trace_add(
                "write",
                schedule_integrated_refresh,
            )

        except Exception:
            pass

    # ------------------------------------------------------------
    # 사업4 비상주 투입일·종료일 변경 감지
    #
    # 키를 누를 때마다 전체 통합표를 계산하지 않습니다.
    # Enter 입력 또는 다른 입력칸으로 이동했을 때만 계산합니다.
    # ------------------------------------------------------------

    for collection_name in (
        "entry_nonres_start",
        "entry_nonres_end",
    ):
        collection = namespace.get(
            collection_name,
            [],
        )

        project_entries = _v87_safe_get(
            collection,
            3,
        )

        try:
            project_entries = list(
                project_entries
            )

        except Exception:
            project_entries = []

        for entry in project_entries:
            try:
                entry.bind(
                    "<FocusOut>",
                    schedule_integrated_refresh,
                    add="+",
                )

                entry.bind(
                    "<Return>",
                    schedule_integrated_refresh,
                    add="+",
                )

            except Exception:
                pass

    # 설치가 완료된 직후 최초 한 번만 갱신합니다.
    schedule_integrated_refresh()


