def _v87_install_trade_patches(
    namespace,
    trade_name,
):
    if namespace.get(
        "_v87_trade_patches_installed",
        False,
    ):
        if trade_name == "전기":
            _v87_enable_assistant_grade_buttons(
                namespace
            )

        return

    namespace[
        "_v87_trade_patches_installed"
    ] = True

    # 전기·통신·소방 사업4 감리원수 재연동
    _v87_install_integrated_personnel_patch(
        namespace,
        trade_name,
    )

    if trade_name == "전기":
        _v87_enable_assistant_grade_buttons(
            namespace
        )

        _v87_install_electric_cost_method_patch(
            namespace
        )

        root = namespace.get(
            "root"
        )

        if root is not None:
            try:
                root.after_idle(
                    lambda: (
                        _v87_enable_assistant_grade_buttons(
                            namespace
                        )
                    )
                )

                root.after(
                    300,
                    lambda: (
                        _v87_enable_assistant_grade_buttons(
                            namespace
                        )
                    ),
                )

            except Exception:
                pass


def _v89_previous_v71_apply_runtime_patch(
    namespace,
    trade_name,
):
    """
    최종본107 기존 패치를 먼저 적용한 후
    최종본107 패치를 추가합니다.
    """
    _v87_install_excel_sheet_patch()

    if trade_name == "전기":
        _v87_install_electric_assistant_grade_patch()

    result = _v85_apply_runtime_patch(
        namespace,
        trade_name,
    )

    _v87_install_trade_patches(
        namespace,
        trade_name,
    )

    return result

