# 최종본107 공통/전기/통신/소방 개선 패치
# ================================================================

import re as _v89_re


def _v89_get(widget, default=""):
    if widget is None:
        return default

    try:
        return str(widget.get())
    except Exception:
        return default


def _v89_put(
    widget,
    value,
    target_state=None,
    background=None,
):
    """
    Entry의 상태를 보존하면서 값이 실제로 바뀌는 경우에만 수정합니다.
    동일 값에 대한 delete/insert를 하지 않아 trace와 계산 호출을 줄입니다.
    """
    if widget is None:
        return

    new_value = "" if value is None else str(value)

    try:
        current_value = str(widget.get())
    except Exception:
        current_value = None

    try:
        old_state = str(widget.cget("state"))
    except Exception:
        old_state = "normal"

    final_state = (
        target_state
        if target_state in ("normal", "readonly", "disabled")
        else old_state
    )

    if current_value != new_value:
        try:
            cursor_position = widget.index("insert")
        except Exception:
            cursor_position = None

        try:
            widget.configure(state="normal")
        except Exception:
            pass

        try:
            widget.delete(0, "end")

            if new_value:
                widget.insert(0, new_value)
        except Exception:
            pass

        if cursor_position is not None:
            try:
                widget.icursor(
                    min(cursor_position, len(new_value))
                )
            except Exception:
                pass

    if background:
        try:
            widget.configure(
                bg=background,
                readonlybackground=background,
                disabledbackground=background,
            )
        except Exception:
            try:
                widget.configure(bg=background)
            except Exception:
                pass

    if final_state in ("normal", "readonly", "disabled"):
        try:
            widget.configure(state=final_state)
        except Exception:
            pass


def _v89_list_item(collection, project_index, role_index=None):
    try:
        item = collection[project_index]

        if role_index is not None:
            item = item[role_index]

        return item
    except Exception:
        return None


def _v89_set_variable(variable, value):
    if variable is None:
        return

    try:
        if str(variable.get()) != str(value):
            variable.set(value)
    except Exception:
        pass


def _v89_call(namespace, function_name, *args):
    function = namespace.get(function_name)

    if not callable(function):
        return None

    try:
        return function(*args)
    except TypeError:
        try:
            return function()
        except Exception:
            return None
    except Exception:
        return None


# ================================================================
# 1. 연면적 정수 입력
# ================================================================

def _v89_clean_area_widget(widget):
    """
    연면적 입력값에서 콤마와 소수점을 제거하고 정수만 남깁니다.

    예:
        12,345.67 -> 1,234,567이 아니라 12,345
        12345.9   -> 12,345
        abc123    -> 123
    """
    if widget is None:
        return 0

    raw_text = _v89_get(widget).strip()

    if not raw_text:
        return 0

    # 사용자가 입력한 첫 번째 소수점 이하 부분은 버립니다.
    integer_part = raw_text.split(".", 1)[0]

    digits = "".join(
        character
        for character in integer_part
        if character.isdigit()
    )

    if not digits:
        _v89_put(
            widget,
            "",
            target_state="normal",
            background="#ffebcc",
        )
        return 0

    try:
        integer_value = max(0, int(digits))
    except Exception:
        integer_value = 0

    formatted = f"{integer_value:,}"

    _v89_put(
        widget,
        formatted,
        target_state="normal",
        background="#ffebcc",
    )

    return integer_value


def _v89_validate_area(namespace, project_index):
    area_entries = namespace.get("entry_area", [])

    area_widget = _v89_list_item(
        area_entries,
        project_index,
    )

    return _v89_clean_area_widget(area_widget)


# ================================================================
# 2. 자동 동기화 및 디바운스
# ================================================================

def _v89_refresh_sheets(namespace, project_index=None):
    """
    화면 입력값을 산출조서에 반영합니다.

    사업1~3:
        개별 및 통합 산출조서 갱신

    사업4:
        통합 정상요율·통합 조정요율 산출조서 갱신
    """
    busy = namespace.setdefault(
        "_v89_refresh_busy",
        False,
    )

    if busy:
        return

    namespace["_v89_refresh_busy"] = True

    try:
        if project_index is not None:
            try:
                project_index = int(project_index)
            except Exception:
                project_index = None

        # 사업별 계산
        if project_index is not None:
            if namespace.get(
                "_v89_trade_name"
            ) == "전기":
                immediate = globals().get(
                    "_v88_electric_sync_project_immediate"
                )

                if callable(immediate):
                    try:
                        immediate(namespace, project_index)
                    except Exception:
                        pass

            _v89_call(
                namespace,
                "electric_calculate_steps",
                project_index,
            )

            _v89_call(
                namespace,
                "electric_toggle_cost_table",
                project_index,
            )

            _v89_call(
                namespace,
                "electric_update_actual_cost_table",
                project_index,
            )

            _v89_call(
                namespace,
                "electric_update_fire_supervision_table",
                project_index,
            )

            _v89_call(
                namespace,
                "electric_update_fire_actual_cost_table",
                project_index,
            )

        # 사업4 직접 입력은 통합 시트만 다시 그립니다.
        if project_index == 3:
            _v89_call(
                namespace,
                "electric_update_integrated_sheets",
            )

        else:
            _v89_call(
                namespace,
                "electric_update_individual_sheet_only",
            )

            _v89_call(
                namespace,
                "electric_update_integrated_sheets",
            )

        # 세 시트 상단 요약 갱신
        summary_function = namespace.get(
            "electric_update_sheet_summary"
        )

        if callable(summary_function):
            for sheet_name in (
                "개별(정상요율) 산출조서",
                "통합(정상요율) 산출조서",
                "통합(조정요율) 산출조서",
            ):
                try:
                    summary_function(sheet_name)
                except Exception:
                    pass

        _v89_call(
            namespace,
            "electric_update_comparison_table",
        )

        # 전기 산출표 표시 조건을 계산 마지막에 다시 적용
        if namespace.get("_v89_trade_name") == "전기":
            _v89_apply_all_electric_area_modes(namespace)

        # 소방 필요 인원 전체 연동
        if namespace.get("_v89_trade_name") == "소방":
            _v89_apply_fire_required_roles(
                namespace,
                project_index,
            )

    finally:
        namespace["_v89_refresh_busy"] = False


def _v89_schedule_refresh(
    namespace,
    project_index=None,
    delay_ms=None,
):
    """
    연속 키 입력 중에는 이전 계산을 취소하고 마지막 입력만 계산합니다.
    Tkinter 위젯은 메인 스레드 전용이므로 별도 작업 스레드는 사용하지 않습니다.
    """
    root = namespace.get("root")

    if delay_ms is None:
        delay_ms = 70 if project_index == 3 else 95

    if root is None:
        _v89_refresh_sheets(
            namespace,
            project_index,
        )
        return

    pending = namespace.setdefault(
        "_v89_pending_refresh_jobs",
        {},
    )

    job_key = (
        "all"
        if project_index is None
        else int(project_index)
    )

    old_job = pending.pop(job_key, None)

    if old_job is not None:
        try:
            root.after_cancel(old_job)
        except Exception:
            pass

    def run_refresh():
        pending.pop(job_key, None)

        try:
            if not root.winfo_exists():
                return
        except Exception:
            return

        _v89_refresh_sheets(
            namespace,
            project_index,
        )

    try:
        pending[job_key] = root.after(
            int(delay_ms),
            run_refresh,
        )
    except Exception:
        _v89_refresh_sheets(
            namespace,
            project_index,
        )


def _v89_bind_entry_refresh(
    namespace,
    widget,
    project_index,
    area_widget=False,
):
    if widget is None:
        return

    def key_handler(event=None):
        if area_widget:
            _v89_validate_area(
                namespace,
                project_index,
            )

        _v89_schedule_refresh(
            namespace,
            project_index,
        )

    def paste_handler(event=None):
        root = namespace.get("root")

        if root is not None:
            try:
                root.after(
                    1,
                    key_handler,
                )
                return
            except Exception:
                pass

        key_handler()

    for event_name, handler in (
        ("<KeyRelease>", key_handler),
        ("<FocusOut>", key_handler),
        ("<<Paste>>", paste_handler),
    ):
        try:
            widget.bind(
                event_name,
                handler,
                add="+",
            )
        except Exception:
            pass


def _v89_install_common_entry_links(namespace):
    """
    저장 버튼과 무관하게 기본 입력사항을 산출조서에 연동합니다.
    """
    collection_names = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_total_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_ratio",
        "entry_ground_floors",
        "entry_basement_floors",
    )

    for collection_name in collection_names:
        collection = namespace.get(
            collection_name,
            [],
        )

        if not isinstance(collection, (list, tuple)):
            continue

        for project_index, widget in enumerate(collection):
            if widget is None:
                continue

            _v89_bind_entry_refresh(
                namespace,
                widget,
                project_index,
                area_widget=(
                    collection_name == "entry_area"
                ),
            )

    # 요율, 임금, 보험료 등 공통 입력
    for collection_name in (
        "entry_overhead",
        "entry_tech_fee",
        "entry_daily_wage",
        "entry_man_months",
    ):
        collection = namespace.get(
            collection_name,
            [],
        )

        for item in collection:
            widgets = (
                item
                if isinstance(item, (list, tuple))
                else [item]
            )

            for widget in widgets:
                if widget is None:
                    continue

                try:
                    widget.bind(
                        "<KeyRelease>",
                        lambda event: _v89_schedule_refresh(
                            namespace,
                            None,
                            100,
                        ),
                        add="+",
                    )
                except Exception:
                    pass

    for single_name in (
        "ent_work_days",
        "ent_insurance",
    ):
        widget = namespace.get(single_name)

        if widget is None:
            continue

        try:
            widget.bind(
                "<KeyRelease>",
                lambda event: _v89_schedule_refresh(
                    namespace,
                    None,
                    100,
                ),
                add="+",
            )
        except Exception:
            pass

    # 체크·라디오 변수도 자동 연동
    for variable_collection_name in (
        "var_resident",
        "var_nonresident",
        "var_integrated",
        "type_vars",
        "lv_vars",
    ):
        collection = namespace.get(
            variable_collection_name,
            [],
        )

        for project_index, variable in enumerate(collection):
            try:
                variable.trace_add(
                    "write",
                    lambda *args, idx=project_index: (
                        _v89_schedule_refresh(
                            namespace,
                            idx,
                        )
                    ),
                )
            except Exception:
                pass

    # 등급 변수
    for project_index, grade_collection in enumerate(
        namespace.get("var_grades", [])
    ):
        for variable in grade_collection:
            try:
                variable.trace_add(
                    "write",
                    lambda *args, idx=project_index: (
                        _v89_schedule_refresh(
                            namespace,
                            idx,
                        )
                    ),
                )
            except Exception:
                pass


