def _v89_unlock_project4(namespace):
    """
    통합배치 사업4 입력창을 직접 수정 가능한 연보라색 Entry로 유지합니다.
    """
    collection_names = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_total_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_ground_floors",
        "entry_basement_floors",
    )

    for collection_name in collection_names:
        collection = namespace.get(
            collection_name,
            [],
        )

        widget = _v89_list_item(
            collection,
            3,
        )

        if widget is None:
            continue

        try:
            widget.configure(
                state="normal",
                bg="#ebd4f5",
                readonlybackground="#ebd4f5",
                disabledbackground="#ebd4f5",
            )
        except Exception:
            pass

        _v89_bind_entry_refresh(
            namespace,
            widget,
            3,
            area_widget=(
                collection_name == "entry_area"
            ),
        )


