def _v89_clear_entries(entries, background="#eeeeee"):
    for entry in entries:
        if entry is None:
            continue

        _v89_put(
            entry,
            "",
            target_state="readonly",
            background=background,
        )


def _v89_set_entries_active(
    entries,
    active,
    active_background="white",
):
    color = (
        active_background
        if active
        else "#eeeeee"
    )

    for entry in entries:
        if entry is None:
            continue

        try:
            entry.configure(
                readonlybackground=color,
                disabledbackground=color,
            )
        except Exception:
            pass


# 최종본214: 계산값 갱신 시에도 소계·합계 음영을 고정합니다.
_V214_SUBTOTAL_BACKGROUND = "#d9e2f3"
_V214_TOTAL_BACKGROUND = "#d9d9d9"


def _v214_set_entry_background(widget, color):
    if widget is None:
        return

    try:
        widget.configure(
            bg=color,
            readonlybackground=color,
            disabledbackground=color,
        )
    except Exception:
        try:
            widget.configure(
                readonlybackground=color,
                disabledbackground=color,
            )
        except Exception:
            pass


def _v214_apply_electric_cost_summary_colors(
    namespace,
    project_index=None,
):
    """전기 정액적산·실비정액 표의 소계와 합계 음영을 복원합니다."""
    if namespace.get("_v89_trade_name") != "전기":
        return

    if project_index is None:
        project_indices = range(
            len(namespace.get("entry_area", []))
        )
    else:
        project_indices = (project_index,)

    summary_specs = (
        (
            "cost_entries_100",
            ((24, _V214_TOTAL_BACKGROUND),),
        ),
        (
            "cost_entries_split",
            (
                (24, _V214_SUBTOTAL_BACKGROUND),
                (43, _V214_SUBTOTAL_BACKGROUND),
                (44, _V214_TOTAL_BACKGROUND),
            ),
        ),
        (
            "cost_entries_actual_split",
            (
                (24, _V214_SUBTOTAL_BACKGROUND),
                (43, _V214_SUBTOTAL_BACKGROUND),
                (44, _V214_TOTAL_BACKGROUND),
            ),
        ),
    )

    for index in project_indices:
        for collection_name, color_specs in summary_specs:
            entries = _v89_list_item(
                namespace.get(collection_name, []),
                index,
            )

            if not isinstance(entries, (list, tuple)):
                continue

            for entry_index, color in color_specs:
                entry = _v89_list_item(entries, entry_index)
                _v214_set_entry_background(entry, color)


def _v89_apply_electric_area_mode(namespace, project_index):
    if namespace.get("_v89_trade_name") != "전기":
        return

    area_widget = _v89_list_item(
        namespace.get("entry_area", []),
        project_index,
    )

    raw_area = _v89_get(
        area_widget
    ).replace(",", "").strip()

    if not raw_area:
        return

    try:
        area = int(float(raw_area))
    except Exception:
        return

    is_fixed = area < 10000

    fixed_entries = []

    for collection_name in (
        "cost_entries_100",
        "cost_entries_split",
    ):
        project_entries = _v89_list_item(
            namespace.get(collection_name, []),
            project_index,
        )

        if isinstance(project_entries, (list, tuple)):
            fixed_entries.extend(project_entries)

    for collection_name in (
        "entry_step1",
        "entry_step2",
    ):
        widget = _v89_list_item(
            namespace.get(collection_name, []),
            project_index,
        )

        if widget is not None:
            fixed_entries.append(widget)

    actual_entries = _v89_list_item(
        namespace.get(
            "cost_entries_actual_split",
            [],
        ),
        project_index,
    )

    if not isinstance(actual_entries, (list, tuple)):
        actual_entries = []

    # 10,000㎡ 미만: 실비정액가산 표 값 제거
    if is_fixed:
        _v89_set_entries_active(
            fixed_entries,
            True,
        )

        _v89_clear_entries(
            actual_entries,
        )

    # 10,000㎡ 이상: 정액적산 표 값 제거
    else:
        _v89_clear_entries(
            fixed_entries,
        )

        _v89_set_entries_active(
            actual_entries,
            True,
        )

    # LabelFrame 제목 색상
    try:
        fixed_frame = (
            _v89_list_item(
                namespace.get("entry_step1", []),
                project_index,
            )
            .master
            .master
        )

        fixed_frame.configure(
            fg="black" if is_fixed else "#999999"
        )
    except Exception:
        pass

    try:
        actual_frame = actual_entries[0].master.master

        actual_frame.configure(
            fg="black" if not is_fixed else "#999999"
        )
    except Exception:
        pass

    # 활성 표의 값이 생겨도 요약 행의 고유 음영을 마지막에 다시 적용합니다.
    _v214_apply_electric_cost_summary_colors(
        namespace,
        project_index,
    )


def _v89_apply_all_electric_area_modes(namespace):
    if namespace.get("_v89_trade_name") != "전기":
        return

    for project_index in range(
        len(namespace.get("entry_area", []))
    ):
        _v89_apply_electric_area_mode(
            namespace,
            project_index,
        )


def _v89_wrap_electric_calculations(namespace):
    """
    기존 계산 함수가 비활성 표를 다시 채운 후에도 마지막 단계에서
    10,000㎡ 표시 조건을 재적용합니다.
    """
    if namespace.get("_v89_trade_name") != "전기":
        return

    for function_name in (
        "electric_toggle_cost_table",
        "electric_update_actual_cost_table",
        "electric_calculate_steps",
    ):
        original = namespace.get(function_name)

        if not callable(original):
            continue

        if getattr(original, "_v89_wrapped", False):
            continue

        def wrapper(
            project_index,
            *args,
            __original=original,
            **kwargs
        ):
            result = __original(
                project_index,
                *args,
                **kwargs
            )

            _v89_apply_electric_area_mode(
                namespace,
                project_index,
            )

            return result

        wrapper._v89_wrapped = True
        wrapper.__name__ = function_name

        namespace[function_name] = wrapper


# ================================================================
# 5. 소방 필요 인원 전체 날짜·등급 연동
# ================================================================

def _v89_fire_required_counts(text):
    """
    최소 필요배치인원수 문구에서 역할별 필요 인원을 추출합니다.

    예:
        상주(책임) 1명, 상주(보조) 2명 배치
        비상주 1명 배치
    """
    normalized = str(text or "").replace(" ", "")

    def find_count(patterns):
        for pattern in patterns:
            match = _v89_re.search(
                pattern,
                normalized,
            )

            if match:
                try:
                    return max(0, int(match.group(1)))
                except Exception:
                    return 1

        return 0

    responsible_count = find_count(
        (
            r"상주\(책임\).*?(\d+)명",
            r"책임감리원.*?(\d+)명",
            r"책임.*?(\d+)명",
        )
    )

    assistant_count = find_count(
        (
            r"상주\(보조\).*?(\d+)명",
            r"보조감리원.*?(\d+)명",
            r"보조.*?(\d+)명",
        )
    )

    nonresident_count = find_count(
        (
            r"비상주감리원.*?(\d+)명",
            r"비상주.*?(\d+)명",
        )
    )

    # 문구에 역할은 있지만 숫자가 생략된 경우 1명으로 처리
    if responsible_count == 0 and (
        "상주(책임)" in text
        or "책임감리원" in text
    ):
        responsible_count = 1

    if assistant_count == 0 and (
        "상주(보조)" in text
        or "보조감리원" in text
    ):
        assistant_count = 1

    if nonresident_count == 0 and "비상주" in text:
        nonresident_count = 1

    return {
        "responsible": min(1, responsible_count),
        "assistant": min(3, assistant_count),
        "nonresident": min(3, nonresident_count),
    }


def _v89_fire_reference_value(refs, key, default=""):
    try:
        return str(refs[key].get()).strip()
    except Exception:
        return default


def _v89_enable_grade_widgets(
    namespace,
    variable,
    enabled,
):
    helper = globals().get(
        "_v71_electric_set_grade_widget_state"
    )

    if callable(helper):
        try:
            helper(
                namespace,
                variable,
                enabled,
            )
            return
        except Exception:
            pass

    root = namespace.get("root")

    if root is None or variable is None:
        return

    variable_name = str(variable)

    def walk(widget):
        try:
            children = widget.winfo_children()
        except Exception:
            children = []

        for child in children:
            yield child
            yield from walk(child)

    for widget in walk(root):
        try:
            if str(widget.cget("variable")) == variable_name:
                widget.configure(
                    state=(
                        "normal"
                        if enabled
                        else "disabled"
                    )
                )
        except Exception:
            pass


def _v89_fire_apply_role(
    namespace,
    project_index,
    grade_index,
    start_widget,
    end_widget,
    enabled,
    grade,
):
    start_source = _v89_list_item(
        namespace.get(
            "entry_elec_start_date",
            [],
        ),
        project_index,
    )

    end_source = _v89_list_item(
        namespace.get(
            "entry_elec_end_date",
            [],
        ),
        project_index,
    )

    start_value = _v89_get(start_source)
    end_value = _v89_get(end_source)

    grade_variable = _v89_list_item(
        namespace.get("var_grades", []),
        project_index,
        grade_index,
    )

    if enabled:
        _v89_put(
            start_widget,
            start_value,
            target_state="normal",
            background="#ebd4f5",
        )

        _v89_put(
            end_widget,
            end_value,
            target_state="normal",
            background="#ebd4f5",
        )

        selected_grade = str(grade or "").replace(
            " 이상",
            "",
        ).strip()

        valid_grades = (
            "기술사",
            "특급",
            "고급",
            "중급",
            "초급",
        )

        if selected_grade not in valid_grades:
            selected_grade = "초급"

        _v89_set_variable(
            grade_variable,
            selected_grade,
        )

        _v89_enable_grade_widgets(
            namespace,
            grade_variable,
            True,
        )

    else:
        _v89_enable_grade_widgets(
            namespace,
            grade_variable,
            True,
        )


def _v89_apply_fire_project_roles(
    namespace,
    project_index,
):
    refs_collection = namespace.get(
        "fire_supervision_all_refs",
        [],
    )

    refs = _v89_list_item(
        refs_collection,
        project_index,
    )

    if not isinstance(refs, dict):
        return

    count_text = _v89_fire_reference_value(
        refs,
        "count",
        "",
    )

    counts = _v89_fire_required_counts(
        count_text
    )

    responsible_grade = _v89_fire_reference_value(
        refs,
        "responsible",
        "초급",
    )

    assistant_grade = _v89_fire_reference_value(
        refs,
        "assistant",
        "초급",
    )

    nonresident_grade = _v89_fire_reference_value(
        refs,
        "nonresident",
        "초급",
    )

    # 상주 책임
    responsible_start = _v89_list_item(
        namespace.get(
            "entry_res_start_display",
            [],
        ),
        project_index,
    )

    responsible_end = _v89_list_item(
        namespace.get(
            "entry_res_end_display",
            [],
        ),
        project_index,
    )

    _v89_fire_apply_role(
        namespace,
        project_index,
        0,
        responsible_start,
        responsible_end,
        counts["responsible"] > 0,
        responsible_grade,
    )

    # 상주 보조1~3
    for role_index in range(3):
        start_widget = _v89_list_item(
            namespace.get(
                "entry_sub_res_start",
                [],
            ),
            project_index,
            role_index,
        )

        end_widget = _v89_list_item(
            namespace.get(
                "entry_sub_res_end",
                [],
            ),
            project_index,
            role_index,
        )

        _v89_fire_apply_role(
            namespace,
            project_index,
            role_index + 1,
            start_widget,
            end_widget,
            role_index < counts["assistant"],
            assistant_grade,
        )

    # 비상주1~3
    for role_index in range(3):
        start_widget = _v89_list_item(
            namespace.get(
                "entry_nonres_start",
                [],
            ),
            project_index,
            role_index,
        )

        end_widget = _v89_list_item(
            namespace.get(
                "entry_nonres_end",
                [],
            ),
            project_index,
            role_index,
        )

        _v89_fire_apply_role(
            namespace,
            project_index,
            role_index + 4,
            start_widget,
            end_widget,
            role_index < counts["nonresident"],
            nonresident_grade,
        )

    _v89_call(
        namespace,
        "electric_update_fire_actual_cost_table",
        project_index,
    )

    _v89_call(
        namespace,
        "electric_update_actual_cost_table",
        project_index,
    )


def _v89_apply_fire_required_roles(
    namespace,
    project_index=None,
):
    if namespace.get("_v89_trade_name") != "소방":
        return

    if project_index is None:
        indices = range(
            len(
                namespace.get(
                    "fire_supervision_all_refs",
                    [],
                )
            )
        )
    else:
        try:
            indices = [int(project_index)]
        except Exception:
            return

    busy_projects = namespace.setdefault(
        "_v89_fire_role_busy",
        set(),
    )

    for index in indices:
        if index in busy_projects:
            continue

        busy_projects.add(index)

        try:
            _v89_apply_fire_project_roles(
                namespace,
                index,
            )
        finally:
            busy_projects.discard(index)


def _v89_wrap_fire_supervision_update(namespace):
    if namespace.get("_v89_trade_name") != "소방":
        return

    function_name = (
        "electric_update_fire_supervision_table"
    )

    original = namespace.get(function_name)

    if not callable(original):
        return

    if getattr(original, "_v89_wrapped", False):
        return

    def wrapper(index=None, *args, **kwargs):
        result = original(
            index,
            *args,
            **kwargs
        )

        _v89_apply_fire_required_roles(
            namespace,
            index,
        )

        return result

    wrapper._v89_wrapped = True
    wrapper.__name__ = function_name

    namespace[function_name] = wrapper


# ================================================================
# 6. Excel 산출조서 셀 병합
# ================================================================

def _v89_ranges_intersect(
    min_row1,
    min_col1,
    max_row1,
    max_col1,
    min_row2,
    min_col2,
    max_row2,
    max_col2,
):
    return not (
        max_row1 < min_row2
        or max_row2 < min_row1
        or max_col1 < min_col2
        or max_col2 < min_col1
    )


def _v89_merge_safe(
    worksheet,
    start_row,
    start_column,
    end_row,
    end_column,
):
    if (
        end_row < start_row
        or end_column < start_column
        or (
            start_row == end_row
            and start_column == end_column
        )
    ):
        return False

    for merged_range in list(
        worksheet.merged_cells.ranges
    ):
        if _v89_ranges_intersect(
            start_row,
            start_column,
            end_row,
            end_column,
            merged_range.min_row,
            merged_range.min_col,
            merged_range.max_row,
            merged_range.max_col,
        ):
            if (
                merged_range.min_row == start_row
                and merged_range.min_col == start_column
                and merged_range.max_row == end_row
                and merged_range.max_col == end_column
            ):
                return True

            return False

    try:
        worksheet.merge_cells(
            start_row=start_row,
            start_column=start_column,
            end_row=end_row,
            end_column=end_column,
        )
        return True
    except Exception:
        return False


def _v89_copy_border_to_range(
    worksheet,
    start_row,
    start_column,
    end_row,
    end_column,
):
    try:
        from openpyxl.styles import Border, Side
    except Exception:
        return

    thin = Side(
        style="thin",
        color="808080",
    )

    for row in range(start_row, end_row + 1):
        for column in range(
            start_column,
            end_column + 1,
        ):
            cell = worksheet.cell(
                row=row,
                column=column,
            )

            left = thin if column == start_column else cell.border.left
            right = thin if column == end_column else cell.border.right
            top = thin if row == start_row else cell.border.top
            bottom = thin if row == end_row else cell.border.bottom

            try:
                cell.border = Border(
                    left=left,
                    right=right,
                    top=top,
                    bottom=bottom,
                )
            except Exception:
                pass


def _v89_find_text_row(
    worksheet,
    texts,
    start_row=1,
):
    normalized_texts = tuple(
        str(text).replace(" ", "")
        for text in texts
    )

    for row in range(
        start_row,
        worksheet.max_row + 1,
    ):
        for column in range(
            1,
            min(worksheet.max_column, 12) + 1,
        ):
            value = worksheet.cell(
                row=row,
                column=column,
            ).value

            normalized = str(
                value or ""
            ).replace(" ", "")

            if normalized in normalized_texts:
                return row, column

    return None, None


def _v89_merge_report_sheet(worksheet):
    """
    산출조서 화면 구조에 맞춰 Excel 셀을 병합합니다.
    """
    try:
        from openpyxl.styles import Alignment, Font
    except Exception:
        return

    max_column = max(
        9,
        min(worksheet.max_column, 12),
    )

    # 제목
    if worksheet.max_row >= 1:
        _v89_copy_border_to_range(
            worksheet,
            1,
            1,
            1,
            max_column,
        )

        _v89_merge_safe(
            worksheet,
            1,
            1,
            1,
            max_column,
        )

        try:
            worksheet.cell(1, 1).alignment = Alignment(
                horizontal="center",
                vertical="center",
                wrap_text=True,
            )

            worksheet.cell(1, 1).font = Font(
                name="맑은 고딕",
                size=16,
                bold=True,
            )

            worksheet.row_dimensions[1].height = 28
        except Exception:
            pass

    # 상단 요약: 용역명/규모/연면적/감리기간
    summary_keys = (
        "용역명",
        "규모",
        "연면적",
        "감리기간",
    )

    for row in range(
        2,
        min(worksheet.max_row, 12) + 1,
    ):
        first_text = str(
            worksheet.cell(row, 1).value or ""
        ).replace(" ", "")

        if first_text not in summary_keys:
            continue

        _v89_copy_border_to_range(
            worksheet,
            row,
            2,
            row,
            max_column,
        )

        _v89_merge_safe(
            worksheet,
            row,
            2,
            row,
            max_column,
        )

        try:
            worksheet.cell(row, 2).alignment = Alignment(
                horizontal="left",
                vertical="center",
                wrap_text=True,
            )
            worksheet.row_dimensions[row].height = 24
        except Exception:
            pass

    # 감리원 자격 헤더
    header_row, header_column = _v89_find_text_row(
        worksheet,
        ("감리원 자격", "감리원자격"),
    )

    if header_row is not None:
        end_column = min(
            header_column + 2,
            max_column,
        )

        _v89_copy_border_to_range(
            worksheet,
            header_row,
            header_column,
            header_row,
            end_column,
        )

        _v89_merge_safe(
            worksheet,
            header_row,
            header_column,
            header_row,
            end_column,
        )

    # 직접인건비 세로 병합
    labor_row, labor_column = _v89_find_text_row(
        worksheet,
        ("직접인건비",),
    )

    first_formula_row, _ = _v89_find_text_row(
        worksheet,
        (
            "1. 직접인건비 계",
            "1.직접인건비계",
        ),
        start_row=(
            labor_row + 1
            if labor_row is not None
            else 1
        ),
    )

    if (
        labor_row is not None
        and first_formula_row is not None
        and first_formula_row > labor_row
    ):
        labor_end = first_formula_row - 1

        _v89_copy_border_to_range(
            worksheet,
            labor_row,
            labor_column,
            labor_end,
            labor_column,
        )

        _v89_merge_safe(
            worksheet,
            labor_row,
            labor_column,
            labor_end,
            labor_column,
        )

    # 같은 사업명이 연속된 행은 사업명 셀 세로 병합
    if (
        labor_row is not None
        and first_formula_row is not None
    ):
        project_column = 2
        row = labor_row

        while row < first_formula_row:
            value = worksheet.cell(
                row,
                project_column,
            ).value

            if value in (None, ""):
                row += 1
                continue

            end_row = row

            while end_row + 1 < first_formula_row:
                next_value = worksheet.cell(
                    end_row + 1,
                    project_column,
                ).value

                if next_value == value:
                    end_row += 1
                    continue

                # 내보내기 구조에 따라 다음 행 사업명 칸이 빈칸이면
                # 같은 사업의 인원행으로 판단합니다.
                if next_value in (None, ""):
                    end_row += 1
                    continue

                break

            if end_row > row:
                _v89_copy_border_to_range(
                    worksheet,
                    row,
                    project_column,
                    end_row,
                    project_column,
                )

                _v89_merge_safe(
                    worksheet,
                    row,
                    project_column,
                    end_row,
                    project_column,
                )

            row = end_row + 1

    # 하단 산식: A~F 병합, G=요율, H=금액, I=비고
    formula_markers = (
        "1.직접인건비계",
        "2.주재비",
        "3.출장여비",
        "4.제경비",
        "5.기술료",
        "6.손해배상보험",
        "산출금액",
        "[소계]",
        "부가가치세",
        "감리비총계",
    )

    for row in range(1, worksheet.max_row + 1):
        first_value = str(
            worksheet.cell(row, 1).value or ""
        )

        normalized = (
            first_value
            .replace(" ", "")
            .replace("\n", "")
        )

        if not any(
            normalized.startswith(marker)
            for marker in formula_markers
        ):
            continue

        merge_end_column = min(6, max_column)

        _v89_copy_border_to_range(
            worksheet,
            row,
            1,
            row,
            max_column,
        )

        _v89_merge_safe(
            worksheet,
            row,
            1,
            row,
            merge_end_column,
        )

        try:
            worksheet.cell(row, 1).alignment = Alignment(
                horizontal="left",
                vertical="center",
                wrap_text=True,
            )

            worksheet.cell(row, 7).alignment = Alignment(
                horizontal="center",
                vertical="center",
                wrap_text=True,
            )

            worksheet.cell(row, 8).alignment = Alignment(
                horizontal="right",
                vertical="center",
            )

            worksheet.row_dimensions[row].height = 23
        except Exception:
            pass

    # 관련 근거/구분 문장은 전체 폭 병합
    for row in range(1, worksheet.max_row + 1):
        value = str(
            worksheet.cell(row, 1).value or ""
        ).strip()

        if not value:
            continue

        if not (
            value.startswith("•")
            or "관련근거" in value.replace(" ", "")
            or "노임단가기준" in value.replace(" ", "")
            or "감리원수산출기준" in value.replace(" ", "")
        ):
            continue

        _v89_merge_safe(
            worksheet,
            row,
            1,
            row,
            max_column,
        )

        try:
            worksheet.cell(row, 1).alignment = Alignment(
                horizontal="left",
                vertical="center",
                wrap_text=True,
            )
        except Exception:
            pass

    # 시트 화면/인쇄 설정
    try:
        worksheet.sheet_view.showGridLines = False
        worksheet.freeze_panes = "A2"
        worksheet.page_setup.orientation = "portrait"
        worksheet.page_setup.fitToWidth = 1
        worksheet.page_setup.fitToHeight = 0
        worksheet.sheet_properties.pageSetUpPr.fitToPage = True
        worksheet.print_options.horizontalCentered = True

        worksheet.page_margins.left = 0.25
        worksheet.page_margins.right = 0.25
        worksheet.page_margins.top = 0.35
        worksheet.page_margins.bottom = 0.35
    except Exception:
        pass


def _v89_prepare_workbook(workbook):
    """
    개별 정상요율, 통합 정상요율, 통합 조정요율 시트만 정리합니다.
    """
    for worksheet in workbook.worksheets:
        title = str(
            worksheet.title
        ).replace(" ", "")

        if "산출조서" not in title:
            continue

        if not (
            "개별" in title
            or "통합" in title
        ):
            continue

        _v89_merge_report_sheet(
            worksheet
        )


def _v89_export_excel(namespace, trade_name):
    """
    기존 Excel 내보내기를 실행하되 Workbook.save 직전에
    최종본107 병합 정리를 적용합니다.
    """
    try:
        import openpyxl
        from openpyxl.workbook.workbook import Workbook
    except Exception:
        exporter = globals().get(
            "_v71_export_screen_excel"
        )

        if callable(exporter):
            return exporter(namespace, trade_name)

        return None

    exporter = globals().get(
        "_v71_export_screen_excel"
    )

    if not callable(exporter):
        for name in (
            "electric_export_to_excel",
            "communication_export_to_excel",
            "fire_export_to_excel",
            "export_to_excel",
        ):
            candidate = namespace.get(name)

            if callable(candidate):
                exporter = candidate
                break

    if not callable(exporter):
        return None

    original_save = Workbook.save

    def patched_save(workbook, filename):
        try:
            _v89_prepare_workbook(workbook)
        except Exception:
            pass

        return original_save(
            workbook,
            filename,
        )

    Workbook.save = patched_save

    try:
        return exporter(
            namespace,
            trade_name,
        )
    finally:
        Workbook.save = original_save


def _v89_patch_excel_buttons(namespace, trade_name):
    root = namespace.get("root")

    if root is None:
        return

    def walk(widget):
        yield widget

        try:
            children = widget.winfo_children()
        except Exception:
            children = []

        for child in children:
            yield from walk(child)

    def export_command():
        return _v89_export_excel(
            namespace,
            trade_name,
        )

    for widget in walk(root):
        try:
            if widget.winfo_class() not in (
                "Button",
                "TButton",
            ):
                continue

            text = str(
                widget.cget("text")
            ).replace(" ", "")

            if "엑셀" in text:
                widget.configure(
                    command=export_command
                )
        except Exception:
            pass

    for function_name in (
        "electric_export_to_excel",
        "communication_export_to_excel",
        "fire_export_to_excel",
        "export_to_excel",
    ):
        if function_name in namespace:
            namespace[function_name] = export_command


