def _v90_previous_v89_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    if namespace.get(
        "_v89_runtime_patch_installed"
    ):
        return

    namespace[
        "_v89_runtime_patch_installed"
    ] = True

    normalized_trade = str(
        trade_name or ""
    ).strip()

    if normalized_trade not in (
        "전기",
        "통신",
        "소방",
    ):
        for function_name in (
            "electric_current_trade_name",
            "communication_current_trade_name",
            "fire_current_trade_name",
            "current_trade_name",
        ):
            function = namespace.get(
                function_name
            )

            if not callable(function):
                continue

            try:
                candidate = str(
                    function()
                ).strip()

                if candidate in (
                    "전기",
                    "통신",
                    "소방",
                ):
                    normalized_trade = candidate
                    break
            except Exception:
                pass

    namespace["_v89_trade_name"] = normalized_trade

    _v89_install_common_entry_links(
        namespace
    )

    _v89_unlock_project4(
        namespace
    )

    _v89_wrap_electric_calculations(
        namespace
    )

    _v89_wrap_fire_supervision_update(
        namespace
    )

    _v89_patch_excel_buttons(
        namespace,
        normalized_trade,
    )

    root = namespace.get("root")

    def initial_refresh():
        # 최초 표시 전에 연면적을 정수 형식으로 통일
        for project_index in range(
            len(namespace.get("entry_area", []))
        ):
            _v89_validate_area(
                namespace,
                project_index,
            )

        _v89_refresh_sheets(
            namespace,
            None,
        )

        _v89_unlock_project4(
            namespace
        )

    if root is not None:
        try:
            root.after_idle(initial_refresh)
            root.after(300, initial_refresh)
        except Exception:
            initial_refresh()
    else:
        initial_refresh()

