import re as _v90_re


# ----------------------------------------------------------------
# 공통 유틸리티
# ----------------------------------------------------------------

def _v90_get(widget, default=""):
    if widget is None:
        return default

    try:
        return str(widget.get())
    except Exception:
        return default


def _v90_put(
    widget,
    value,
    state=None,
    background=None,
):
    """
    Entry 상태를 보존하면서 값이 달라질 때만 수정한다.
    동일한 값을 반복 delete/insert하지 않아 trace 호출을 줄인다.
    """
    if widget is None:
        return False

    new_value = "" if value is None else str(value)

    try:
        old_value = str(widget.get())
    except Exception:
        return False

    try:
        old_state = str(widget.cget("state"))
    except Exception:
        old_state = "normal"

    final_state = (
        state
        if state in ("normal", "readonly", "disabled")
        else old_state
    )

    changed = old_value != new_value

    if changed:
        try:
            cursor = widget.index("insert")
        except Exception:
            cursor = None

        try:
            if old_state != "normal":
                widget.configure(state="normal")
        except Exception:
            pass

        try:
            widget.delete(0, "end")

            if new_value:
                widget.insert(0, new_value)
        except Exception:
            pass

        if cursor is not None:
            try:
                widget.icursor(min(cursor, len(new_value)))
            except Exception:
                pass

    if background:
        for option_name in (
            "bg",
            "readonlybackground",
            "disabledbackground",
        ):
            try:
                widget.configure(
                    **{option_name: background}
                )
            except Exception:
                pass

    try:
        if final_state in (
            "normal",
            "readonly",
            "disabled",
        ):
            widget.configure(state=final_state)
    except Exception:
        pass

    return changed


def _v90_set_variable(variable, value):
    if variable is None:
        return False

    try:
        old_value = variable.get()
    except Exception:
        return False

    if str(old_value) == str(value):
        return False

    try:
        variable.set(value)
        return True
    except Exception:
        return False


def _v90_item(collection, index, sub_index=None):
    try:
        result = collection[index]

        if sub_index is not None:
            result = result[sub_index]

        return result
    except Exception:
        return None


def _v90_walk(widget):
    yield widget

    try:
        children = widget.winfo_children()
    except Exception:
        children = []

    for child in children:
        yield from _v90_walk(child)


def _v90_trade_prefix(namespace):
    trade_name = str(
        namespace.get("_v90_trade_name", "")
    ).strip()

    if trade_name == "통신":
        return "communication"

    if trade_name == "소방":
        return "fire"

    return "electric"


def _v90_find_function(namespace, suffix):
    """
    공종별 prefix가 다른 함수 중 suffix가 일치하는 함수를 찾는다.
    """
    prefix = _v90_trade_prefix(namespace)

    candidates = (
        f"{prefix}{suffix}",
        f"electric{suffix}",
        f"communication{suffix}",
        f"fire{suffix}",
        suffix.lstrip("_"),
    )

    for name in candidates:
        function = namespace.get(name)

        if callable(function):
            return name, function

    for name, value in list(namespace.items()):
        if callable(value) and str(name).endswith(suffix):
            return name, value

    return None, None


def _v90_call(namespace, suffix, *args):
    _, function = _v90_find_function(
        namespace,
        suffix,
    )

    if not callable(function):
        return None

    try:
        return function(*args)
    except TypeError:
        try:
            return function()
        except Exception:
            return None
    except Exception:
        return None


def _v90_call_original(namespace, key, *args):
    function = namespace.get(
        "_v90_original_functions",
        {},
    ).get(key)

    if not callable(function):
        return None

    try:
        return function(*args)
    except TypeError:
        try:
            return function()
        except Exception:
            return None
    except Exception:
        return None


def _v90_normalize_name(value):
    return "".join(
        character.lower()
        for character in str(value or "")
        if character.isalnum()
    )


def _v90_name_tokens(value):
    stop_words = {
        "공사",
        "사업",
        "서울대학교",
        "서울대",
        "신축",
        "증축",
        "증설",
        "개량",
        "개축",
        "재축",
        "리모델링",
        "전기",
        "통신",
        "소방",
        "감리",
        "용역",
    }

    result = []

    for token in _v90_re.findall(
        r"[가-힣A-Za-z0-9]+",
        str(value or ""),
    ):
        cleaned = token.strip()

        if len(cleaned) < 2:
            continue

        if cleaned in stop_words:
            continue

        result.append(cleaned.lower())

    return result


def _v90_number(widget, default=0):
    raw = _v90_get(widget).replace(",", "").strip()

    if not raw:
        return default

    try:
        return int(float(raw))
    except Exception:
        return default


def _v90_format_integer(value):
    try:
        value = int(float(value))
    except Exception:
        value = 0

    return f"{value:,}" if value else ""


def _v90_date_digits(widget):
    value = "".join(
        character
        for character in _v90_get(widget)
        if character.isdigit()
    )

    return value if len(value) == 8 else ""


def _v90_format_date(value):
    value = "".join(
        character
        for character in str(value or "")
        if character.isdigit()
    )

    if len(value) != 8:
        return ""

    return (
        f"{value[:4]}."
        f"{value[4:6]}."
        f"{value[6:8]}"
    )


# ----------------------------------------------------------------
# 계산 및 산출조서 디바운스
# ----------------------------------------------------------------

def _v90_after_cancel(namespace, key):
    root = namespace.get("root")

    jobs = namespace.setdefault(
        "_v90_after_jobs",
        {},
    )

    job = jobs.pop(key, None)

    if root is None or job is None:
        return

    try:
        root.after_cancel(job)
    except Exception:
        pass


def _v90_after(
    namespace,
    key,
    delay,
    callback,
):
    root = namespace.get("root")

    _v90_after_cancel(namespace, key)

    if root is None:
        callback()
        return

    jobs = namespace.setdefault(
        "_v90_after_jobs",
        {},
    )

    def run():
        jobs.pop(key, None)

        try:
            if not root.winfo_exists():
                return
        except Exception:
            return

        callback()

    try:
        jobs[key] = root.after(
            int(delay),
            run,
        )
    except Exception:
        callback()


def _v90_schedule_project_calculation(
    namespace,
    project_index,
    delay=180,
):
    try:
        project_index = int(project_index)
    except Exception:
        return

    _v90_after(
        namespace,
        f"project:{project_index}",
        delay,
        lambda idx=project_index: (
            _v90_flush_project_calculation(
                namespace,
                idx,
            )
        ),
    )


def _v90_flush_project_calculation(
    namespace,
    project_index,
):
    busy = namespace.setdefault(
        "_v90_calculation_busy",
        set(),
    )

    if project_index in busy:
        return

    busy.add(project_index)

    try:
        originals = namespace.get(
            "_v90_calculation_originals",
            {},
        )

        ordered_suffixes = (
            "_calculate_steps",
            "_check_required_supervisor",
            "_toggle_cost_table",
            "_update_actual_cost_table",
            "_update_communication_info_for_project",
            "_update_fire_supervision_table",
            "_update_fire_actual_cost_table",
        )

        called = set()

        for suffix in ordered_suffixes:
            function = originals.get(suffix)

            if not callable(function):
                continue

            function_id = id(function)

            if function_id in called:
                continue

            called.add(function_id)

            try:
                function(project_index)
            except TypeError:
                try:
                    function()
                except Exception:
                    pass
            except Exception:
                pass

        # 사업4 입력값은 통합 산출조서에 연결한다.
        if project_index == 3:
            _v90_schedule_render(
                namespace,
                integrated_only=True,
                delay=40,
            )
        else:
            _v90_schedule_render(
                namespace,
                integrated_only=False,
                delay=60,
            )

    finally:
        busy.discard(project_index)


def _v90_schedule_render(
    namespace,
    integrated_only=False,
    delay=260,
):
    if integrated_only:
        namespace["_v90_integrated_render_requested"] = True
    else:
        namespace["_v90_full_render_requested"] = True

    _v90_after(
        namespace,
        "render",
        delay,
        lambda: _v90_flush_render(namespace),
    )


def _v90_flush_render(namespace):
    if namespace.get("_v90_render_busy"):
        return

    namespace["_v90_render_busy"] = True

    try:
        full_render = bool(
            namespace.pop(
                "_v90_full_render_requested",
                False,
            )
        )

        integrated_requested = bool(
            namespace.pop(
                "_v90_integrated_render_requested",
                False,
            )
        )

        originals = namespace.get(
            "_v90_render_originals",
            {},
        )

        if full_render:
            individual = originals.get(
                "_update_individual_sheet_only"
            )

            if callable(individual):
                try:
                    individual()
                except Exception:
                    pass

        if full_render or integrated_requested:
            integrated = originals.get(
                "_update_integrated_sheets"
            )

            if callable(integrated):
                try:
                    integrated()
                except Exception:
                    pass

        comparison = originals.get(
            "_update_comparison_table"
        )

        if callable(comparison):
            try:
                comparison()
            except Exception:
                pass

        summary = originals.get(
            "_update_sheet_summary"
        )

        if callable(summary):
            for sheet_name in (
                "개별(정상요율) 산출조서",
                "통합(정상요율) 산출조서",
                "통합(조정요율) 산출조서",
            ):
                try:
                    summary(sheet_name)
                except Exception:
                    pass

        root = namespace.get("root")

        if root is not None:
            try:
                root.update_idletasks()
            except Exception:
                pass

    finally:
        namespace["_v90_render_busy"] = False


def _v90_install_calculation_debounce(namespace):
    namespace.setdefault(
        "_v90_calculation_originals",
        {},
    )

    originals = namespace[
        "_v90_calculation_originals"
    ]

    suffixes = (
        "_calculate_steps",
        "_check_required_supervisor",
        "_toggle_cost_table",
        "_update_actual_cost_table",
        "_update_communication_info_for_project",
        "_update_fire_supervision_table",
        "_update_fire_actual_cost_table",
    )

    for suffix in suffixes:
        function_name, original = _v90_find_function(
            namespace,
            suffix,
        )

        if not function_name or not callable(original):
            continue

        if getattr(original, "_v90_debounced", False):
            continue

        originals[suffix] = original

        def wrapper(
            project_index=0,
            *args,
            __suffix=suffix,
            **kwargs
        ):
            if namespace.get(
                "_v90_calculation_busy"
            ):
                return None

            try:
                index = int(project_index)
            except Exception:
                index = 0

            _v90_schedule_project_calculation(
                namespace,
                index,
            )

            return None

        wrapper._v90_debounced = True
        wrapper.__name__ = function_name

        namespace[function_name] = wrapper


def _v90_install_render_debounce(namespace):
    namespace.setdefault(
        "_v90_render_originals",
        {},
    )

    originals = namespace[
        "_v90_render_originals"
    ]

    suffixes = (
        "_update_individual_sheet_only",
        "_update_integrated_sheets",
        "_update_comparison_table",
        "_update_sheet_summary",
    )

    for suffix in suffixes:
        function_name, original = _v90_find_function(
            namespace,
            suffix,
        )

        if not function_name or not callable(original):
            continue

        if getattr(original, "_v90_render_wrapper", False):
            continue

        originals[suffix] = original

        if suffix == "_update_sheet_summary":
            # summary는 render flush에서 직접 처리한다.
            def wrapper(
                *args,
                __suffix=suffix,
                **kwargs
            ):
                _v90_schedule_render(
                    namespace,
                    integrated_only=False,
                )
                return None

        elif suffix == "_update_integrated_sheets":
            def wrapper(
                *args,
                __suffix=suffix,
                **kwargs
            ):
                if namespace.get("_v90_render_busy"):
                    return None

                _v90_schedule_render(
                    namespace,
                    integrated_only=True,
                )
                return None

        else:
            def wrapper(
                *args,
                __suffix=suffix,
                **kwargs
            ):
                if namespace.get("_v90_render_busy"):
                    return None

                _v90_schedule_render(
                    namespace,
                    integrated_only=False,
                )
                return None

        wrapper._v90_render_wrapper = True
        wrapper.__name__ = function_name

        namespace[function_name] = wrapper

    # 기존 trigger_ui_update가 별도 타이머를 만들지 않도록 통합한다.
    trigger_name, trigger_original = _v90_find_function(
        namespace,
        "_trigger_ui_update",
    )

    if trigger_name and callable(trigger_original):
        namespace.setdefault(
            "_v90_original_functions",
            {},
        )[trigger_name] = trigger_original

        def trigger_wrapper(*args, **kwargs):
            _v90_schedule_render(
                namespace,
                integrated_only=False,
            )

        trigger_wrapper._v90_render_wrapper = True
        trigger_wrapper.__name__ = trigger_name

        namespace[trigger_name] = trigger_wrapper


def _v90_v89_schedule_refresh_compat(
    namespace,
    project_index=None,
    delay_ms=None,
):
    """
    최종본89에서 추가한 빠른 반복 갱신을 최종본107 디바운스로 통합한다.
    """
    if not isinstance(namespace, dict):
        return

    if project_index is None:
        _v90_schedule_render(
            namespace,
            integrated_only=False,
            delay=max(220, int(delay_ms or 0)),
        )
        return

    try:
        project_index = int(project_index)
    except Exception:
        project_index = 0

    _v90_schedule_project_calculation(
        namespace,
        project_index,
        delay=max(160, int(delay_ms or 0)),
    )


# ----------------------------------------------------------------
# 통합배치 양방향 연동
# ----------------------------------------------------------------

def _v90_project4_widgets(namespace):
    result = {}

    collection_names = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_total_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_ground_floors",
        "entry_basement_floors",
        "entry_ratio",
    )

    for collection_name in collection_names:
        collection = namespace.get(
            collection_name,
            [],
        )

        widget = _v90_item(
            collection,
            3,
        )

        if widget is not None:
            result[collection_name] = widget

    return result


def _v90_active_integrated_variables(namespace):
    trade_name = namespace.get(
        "_v90_trade_name"
    )

    candidates = []

    if trade_name == "통신":
        candidates.append(
            namespace.get(
                "communication_integrated_vars",
                [],
            )
        )

    elif trade_name == "소방":
        candidates.append(
            namespace.get(
                "fire_integrated_vars",
                [],
            )
        )

    candidates.append(
        namespace.get("var_integrated", [])
    )

    for collection in candidates:
        if (
            isinstance(collection, (list, tuple))
            and len(collection) >= 3
        ):
            return collection

    return []


def _v90_all_integrated_variable_collections(namespace):
    result = []

    for name in (
        "var_integrated",
        "communication_integrated_vars",
        "fire_integrated_vars",
    ):
        collection = namespace.get(name, [])

        if not isinstance(collection, (list, tuple)):
            continue

        if len(collection) < 3:
            continue

        if collection not in result:
            result.append(collection)

    return result


def _v90_selected_indices(namespace):
    variables = _v90_active_integrated_variables(
        namespace
    )

    selected = []

    for index in range(min(3, len(variables))):
        try:
            value = variables[index].get()
        except Exception:
            value = "X"

        if str(value).upper() in (
            "O",
            "1",
            "TRUE",
        ):
            selected.append(index)

    return selected


def _v90_mirror_integrated_variables(
    namespace,
    selected_indices,
):
    selected_set = set(selected_indices)

    for collection in (
        _v90_all_integrated_variable_collections(
            namespace
        )
    ):
        for index in range(min(3, len(collection))):
            value = (
                "O"
                if index in selected_set
                else "X"
            )

            _v90_set_variable(
                collection[index],
                value,
            )


def _v90_snapshot_project4(namespace):
    snapshot = {}

    for name, widget in _v90_project4_widgets(
        namespace
    ).items():
        snapshot[name] = _v90_get(widget)

    return snapshot


def _v90_restore_project4(namespace, snapshot):
    for name, value in snapshot.items():
        widget = _v90_project4_widgets(
            namespace
        ).get(name)

        _v90_put(
            widget,
            value,
            state="normal",
            background="#ebd4f5",
        )


def _v90_match_project4_names(namespace):
    """
    사업4 사업명에 포함된 사업1~3 이름과 핵심 단어를 이용해
    통합배치 O/X를 결정한다.
    """
    names = namespace.get("entry_names", [])

    project4_name = _v90_get(
        _v90_item(names, 3)
    ).strip()

    normalized_project4 = _v90_normalize_name(
        project4_name
    )

    selected = []

    if normalized_project4:
        for index in range(3):
            project_name = _v90_get(
                _v90_item(names, index)
            ).strip()

            if not project_name:
                continue

            normalized_project = _v90_normalize_name(
                project_name
            )

            full_match = (
                bool(normalized_project)
                and normalized_project in normalized_project4
            )

            tokens = _v90_name_tokens(
                project_name
            )

            token_match = any(
                _v90_normalize_name(token)
                in normalized_project4
                for token in tokens
            )

            if full_match or token_match:
                selected.append(index)

    return selected


def _v90_project4_to_checks(namespace):
    if namespace.get("_v90_integration_busy"):
        return

    namespace["_v90_integration_busy"] = True

    try:
        snapshot = _v90_snapshot_project4(
            namespace
        )

        selected = _v90_match_project4_names(
            namespace
        )

        _v90_mirror_integrated_variables(
            namespace,
            selected,
        )

        # 기존 trace 함수가 사업4를 합산값으로 덮어썼을 수 있으므로
        # 사용자가 직접 입력한 내용을 다시 복구한다.
        _v90_restore_project4(
            namespace,
            snapshot,
        )

    finally:
        namespace["_v90_integration_busy"] = False

    _v90_schedule_project_calculation(
        namespace,
        3,
        delay=100,
    )

    _v90_schedule_render(
        namespace,
        integrated_only=True,
        delay=140,
    )


def _v90_sum_collection(
    namespace,
    collection_name,
    selected,
):
    collection = namespace.get(
        collection_name,
        [],
    )

    total = 0

    for index in selected:
        total += _v90_number(
            _v90_item(collection, index),
            0,
        )

    return total


def _v90_extreme_date(
    namespace,
    collection_name,
    selected,
    minimum=True,
):
    collection = namespace.get(
        collection_name,
        [],
    )

    dates = []

    for index in selected:
        value = _v90_date_digits(
            _v90_item(collection, index)
        )

        if value:
            dates.append(value)

    if not dates:
        return ""

    return _v90_format_date(
        min(dates) if minimum else max(dates)
    )


def _v90_same_variable_value(
    namespace,
    collection_name,
    selected,
):
    collection = namespace.get(
        collection_name,
        [],
    )

    values = []

    for index in selected:
        variable = _v90_item(
            collection,
            index,
        )

        try:
            value = variable.get()
        except Exception:
            continue

        if value not in (None, "", "none"):
            values.append(value)

    if not values:
        return None

    if all(value == values[0] for value in values):
        return values[0]

    return None


def _v90_checks_to_project4(namespace):
    """
    통합배치 O가 선택된 사업1~3을 사업4 입력 박스에 합산한다.
    """
    if namespace.get("_v90_integration_busy"):
        return

    namespace["_v90_integration_busy"] = True

    try:
        selected = _v90_selected_indices(
            namespace
        )

        _v90_mirror_integrated_variables(
            namespace,
            selected,
        )

        project4 = _v90_project4_widgets(
            namespace
        )

        names = namespace.get(
            "entry_names",
            [],
        )

        selected_names = []

        for index in selected:
            name = _v90_get(
                _v90_item(names, index)
            ).strip()

            selected_names.append(
                name if name else f"사업{index + 1}"
            )

        _v90_put(
            project4.get("entry_names"),
            ", ".join(selected_names),
            state="normal",
            background="#ebd4f5",
        )

        numeric_collections = (
            "entry_contract_cost",
            "entry_contractor_material_cost",
            "entry_total_cost",
            "entry_area",
        )

        for collection_name in numeric_collections:
            total = _v90_sum_collection(
                namespace,
                collection_name,
                selected,
            )

            _v90_put(
                project4.get(collection_name),
                _v90_format_integer(total),
                state="normal",
                background="#ebd4f5",
            )

        for collection_name in (
            "entry_ground_floors",
            "entry_basement_floors",
        ):
            collection = namespace.get(
                collection_name,
                [],
            )

            values = [
                _v90_number(
                    _v90_item(collection, index),
                    0,
                )
                for index in selected
            ]

            maximum = max(values) if values else 0

            _v90_put(
                project4.get(collection_name),
                str(maximum) if maximum else "",
                state="normal",
                background="#ebd4f5",
            )

        start_date = _v90_extreme_date(
            namespace,
            "entry_start_date",
            selected,
            minimum=True,
        )

        end_date = _v90_extreme_date(
            namespace,
            "entry_end_date",
            selected,
            minimum=False,
        )

        trade_start_date = _v90_extreme_date(
            namespace,
            "entry_elec_start_date",
            selected,
            minimum=True,
        )

        trade_end_date = _v90_extreme_date(
            namespace,
            "entry_elec_end_date",
            selected,
            minimum=False,
        )

        _v90_put(
            project4.get("entry_start_date"),
            start_date,
            state="normal",
            background="#ebd4f5",
        )

        _v90_put(
            project4.get("entry_end_date"),
            end_date,
            state="normal",
            background="#ebd4f5",
        )

        _v90_put(
            project4.get("entry_elec_start_date"),
            trade_start_date or start_date,
            state="normal",
            background="#ebd4f5",
        )

        _v90_put(
            project4.get("entry_elec_end_date"),
            trade_end_date or end_date,
            state="normal",
            background="#ebd4f5",
        )

        same_type = _v90_same_variable_value(
            namespace,
            "type_vars",
            selected,
        )

        if same_type is not None:
            _v90_set_variable(
                _v90_item(
                    namespace.get("type_vars", []),
                    3,
                ),
                same_type,
            )

        same_level = _v90_same_variable_value(
            namespace,
            "lv_vars",
            selected,
        )

        if same_level is not None:
            _v90_set_variable(
                _v90_item(
                    namespace.get("lv_vars", []),
                    3,
                ),
                same_level,
            )

    finally:
        namespace["_v90_integration_busy"] = False

    _v90_schedule_project_calculation(
        namespace,
        3,
        delay=90,
    )

    _v90_schedule_render(
        namespace,
        integrated_only=True,
        delay=130,
    )


def _v90_project4_has_focus(namespace):
    root = namespace.get("root")

    if root is None:
        return False

    try:
        focused = root.focus_get()
    except Exception:
        return False

    if focused is None:
        return False

    return focused in set(
        _v90_project4_widgets(namespace).values()
    )


def _v90_wrap_existing_project4_function(namespace):
    """
    기존 update_project4_title이 사업4 직접 입력 중 값을 덮어쓰지 않게 한다.
    """
    function_name, original = _v90_find_function(
        namespace,
        "_update_project4_title",
    )

    if not function_name or not callable(original):
        return

    if getattr(original, "_v90_project4_wrapper", False):
        return

    namespace.setdefault(
        "_v90_original_functions",
        {},
    )[function_name] = original

    def wrapper(*args, **kwargs):
        if namespace.get("_v90_integration_busy"):
            return None

        if _v90_project4_has_focus(namespace):
            _v90_after(
                namespace,
                "project4-manual",
                140,
                lambda: _v90_project4_to_checks(
                    namespace
                ),
            )
            return None

        result = None

        try:
            result = original(*args, **kwargs)
        except Exception:
            pass

        _v90_after(
            namespace,
            "project4-from-checks",
            80,
            lambda: _v90_checks_to_project4(
                namespace
            ),
        )

        return result

    wrapper._v90_project4_wrapper = True
    wrapper.__name__ = function_name

    namespace[function_name] = wrapper


def _v90_bind_project4(namespace):
    project4 = _v90_project4_widgets(
        namespace
    )

    name_widget = project4.get(
        "entry_names"
    )

    if name_widget is not None:
        def manual_name_handler(event=None):
            _v90_after(
                namespace,
                "project4-manual",
                180,
                lambda: _v90_project4_to_checks(
                    namespace
                ),
            )

        for event_name in (
            "<KeyRelease>",
            "<FocusOut>",
        ):
            try:
                name_widget.bind(
                    event_name,
                    manual_name_handler,
                    add="+",
                )
            except Exception:
                pass

        try:
            name_widget.bind(
                "<<Paste>>",
                lambda event: _v90_after(
                    namespace,
                    "project4-paste",
                    10,
                    lambda: _v90_project4_to_checks(
                        namespace
                    ),
                ),
                add="+",
            )
        except Exception:
            pass

    for widget in project4.values():
        if widget is None:
            continue

        try:
            widget.configure(
                state="normal",
                bg="#ebd4f5",
                readonlybackground="#ebd4f5",
                disabledbackground="#ebd4f5",
            )
        except Exception:
            pass

        def project4_value_handler(
            event=None,
            target=widget,
        ):
            if target is name_widget:
                return

            _v90_schedule_project_calculation(
                namespace,
                3,
                delay=180,
            )

            _v90_schedule_render(
                namespace,
                integrated_only=True,
                delay=230,
            )

        try:
            widget.bind(
                "<KeyRelease>",
                project4_value_handler,
                add="+",
            )
        except Exception:
            pass

        try:
            widget.bind(
                "<FocusOut>",
                project4_value_handler,
                add="+",
            )
        except Exception:
            pass

    # O/X 변경 감시
    for collection in (
        _v90_all_integrated_variable_collections(
            namespace
        )
    ):
        for index, variable in enumerate(
            collection[:3]
        ):
            try:
                variable.trace_add(
                    "write",
                    lambda *args, idx=index: (
                        _v90_after(
                            namespace,
                            "project4-from-checks",
                            100,
                            lambda: _v90_checks_to_project4(
                                namespace
                            ),
                        )
                    ),
                )
            except Exception:
                pass


# ----------------------------------------------------------------
# 저장 버튼 제거
# ----------------------------------------------------------------

def _v90_hide_save_buttons(namespace):
    root = namespace.get("root")

    if root is None:
        return

    save_button_names = (
        "btn_save",
        "save_button",
        "button_save",
    )

    for name in save_button_names:
        widget = namespace.get(name)

        if widget is None:
            continue

        try:
            widget.pack_forget()
        except Exception:
            pass

        try:
            widget.grid_remove()
        except Exception:
            pass

        try:
            widget.place_forget()
        except Exception:
            pass

    for widget in _v90_walk(root):
        try:
            if widget.winfo_class() not in (
                "Button",
                "TButton",
            ):
                continue

            text = str(
                widget.cget("text")
            ).strip()

            if text == "저장":
                try:
                    widget.pack_forget()
                except Exception:
                    pass

                try:
                    widget.grid_remove()
                except Exception:
                    pass

                try:
                    widget.place_forget()
                except Exception:
                    pass
        except Exception:
            pass

    # 기존 안내문에서 저장 버튼 문구 제거
    for widget in _v90_walk(root):
        try:
            if widget.winfo_class() not in (
                "Label",
                "TLabel",
            ):
                continue

            text = str(widget.cget("text"))

            if "저장" in text and "눌러" in text:
                widget.configure(
                    text="입력값이 산출조서에 자동으로 반영됩니다.",
                    fg="gray",
                )
        except Exception:
            pass


# ----------------------------------------------------------------
# 공종 선택/시트 이동 시 값 유지
# ----------------------------------------------------------------

def _v90_snapshot_values(namespace):
    snapshot = {
        "entries": {},
        "variables": {},
    }

    entry_collections = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_total_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_ratio",
        "entry_ground_floors",
        "entry_basement_floors",
        "entry_overhead",
        "entry_tech_fee",
        "entry_daily_wage",
    )

    for collection_name in entry_collections:
        collection = namespace.get(
            collection_name,
            [],
        )

        values = []

        if isinstance(collection, (list, tuple)):
            for widget in collection:
                if isinstance(widget, (list, tuple)):
                    values.append([
                        _v90_get(child)
                        for child in widget
                    ])
                else:
                    values.append(_v90_get(widget))

        snapshot["entries"][collection_name] = values

    for name in (
        "ent_work_days",
        "ent_insurance",
    ):
        snapshot["entries"][name] = _v90_get(
            namespace.get(name)
        )

    variable_collections = (
        "var_resident",
        "var_nonresident",
        "var_integrated",
        "communication_integrated_vars",
        "fire_integrated_vars",
        "type_vars",
        "lv_vars",
        "var_grades",
    )

    for collection_name in variable_collections:
        collection = namespace.get(
            collection_name,
            [],
        )

        values = []

        if isinstance(collection, (list, tuple)):
            for variable in collection:
                if isinstance(variable, (list, tuple)):
                    child_values = []

                    for child in variable:
                        try:
                            child_values.append(child.get())
                        except Exception:
                            child_values.append(None)

                    values.append(child_values)

                else:
                    try:
                        values.append(variable.get())
                    except Exception:
                        values.append(None)

        snapshot["variables"][collection_name] = values

    namespace["_v90_saved_input_state"] = snapshot


def _v90_restore_values(namespace):
    snapshot = namespace.get(
        "_v90_saved_input_state"
    )

    if not isinstance(snapshot, dict):
        return

    namespace["_v90_restore_busy"] = True

    try:
        for collection_name, values in (
            snapshot.get("entries", {}).items()
        ):
            if collection_name in (
                "ent_work_days",
                "ent_insurance",
            ):
                _v90_put(
                    namespace.get(collection_name),
                    values,
                )
                continue

            collection = namespace.get(
                collection_name,
                [],
            )

            for index, value in enumerate(values):
                if isinstance(value, list):
                    target_group = _v90_item(
                        collection,
                        index,
                    )

                    if not isinstance(
                        target_group,
                        (list, tuple),
                    ):
                        continue

                    for child_index, child_value in enumerate(
                        value
                    ):
                        _v90_put(
                            _v90_item(
                                target_group,
                                child_index,
                            ),
                            child_value,
                        )
                else:
                    _v90_put(
                        _v90_item(
                            collection,
                            index,
                        ),
                        value,
                    )

        for collection_name, values in (
            snapshot.get("variables", {}).items()
        ):
            collection = namespace.get(
                collection_name,
                [],
            )

            for index, value in enumerate(values):
                if isinstance(value, list):
                    target_group = _v90_item(
                        collection,
                        index,
                    )

                    if not isinstance(
                        target_group,
                        (list, tuple),
                    ):
                        continue

                    for child_index, child_value in enumerate(
                        value
                    ):
                        if child_value is not None:
                            _v90_set_variable(
                                _v90_item(
                                    target_group,
                                    child_index,
                                ),
                                child_value,
                            )
                else:
                    if value is not None:
                        _v90_set_variable(
                            _v90_item(
                                collection,
                                index,
                            ),
                            value,
                        )

    finally:
        namespace["_v90_restore_busy"] = False

    _v90_schedule_render(
        namespace,
        integrated_only=False,
        delay=120,
    )


def _v90_wrap_navigation(namespace):
    # 공종 선택 화면으로 돌아가기
    return_name, return_original = _v90_find_function(
        namespace,
        "_return_to_selection",
    )

    if return_name and callable(return_original):
        if not getattr(
            return_original,
            "_v90_navigation_wrapper",
            False,
        ):
            def return_wrapper(*args, **kwargs):
                _v90_snapshot_values(namespace)
                _v90_flush_render(namespace)

                return return_original(
                    *args,
                    **kwargs
                )

            return_wrapper._v90_navigation_wrapper = True
            return_wrapper.__name__ = return_name

            namespace[return_name] = return_wrapper

    # 선택 공종 실행
    open_name, open_original = _v90_find_function(
        namespace,
        "_open_selected_supervision",
    )

    if open_name and callable(open_original):
        if not getattr(
            open_original,
            "_v90_navigation_wrapper",
            False,
        ):
            def open_wrapper(*args, **kwargs):
                result = open_original(
                    *args,
                    **kwargs
                )

                root = namespace.get("root")

                def after_open():
                    _v90_restore_values(namespace)
                    _v90_hide_save_buttons(namespace)
                    _v90_schedule_render(
                        namespace,
                        integrated_only=False,
                        delay=100,
                    )

                if root is not None:
                    try:
                        root.after_idle(after_open)
                        root.after(150, after_open)
                    except Exception:
                        after_open()
                else:
                    after_open()

                return result

            open_wrapper._v90_navigation_wrapper = True
            open_wrapper.__name__ = open_name

            namespace[open_name] = open_wrapper

    # 시트 이동 시 입력값을 변경하거나 초기화하지 않고
    # 대기 중 계산만 완료한다.
    show_name, show_original = _v90_find_function(
        namespace,
        "_show_sheet",
    )

    if show_name and callable(show_original):
        if not getattr(
            show_original,
            "_v90_navigation_wrapper",
            False,
        ):
            def show_wrapper(*args, **kwargs):
                _v90_flush_render(namespace)

                result = show_original(
                    *args,
                    **kwargs
                )

                _v90_hide_save_buttons(namespace)

                return result

            show_wrapper._v90_navigation_wrapper = True
            show_wrapper.__name__ = show_name

            namespace[show_name] = show_wrapper


# ----------------------------------------------------------------
# 일반 입력값 자동 산출조서 연동
# ----------------------------------------------------------------

def _v90_bind_common_inputs(namespace):
    collections = (
        "entry_names",
        "entry_contract_cost",
        "entry_contractor_material_cost",
        "entry_total_cost",
        "entry_area",
        "entry_start_date",
        "entry_end_date",
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_ratio",
        "entry_ground_floors",
        "entry_basement_floors",
    )

    for collection_name in collections:
        collection = namespace.get(
            collection_name,
            [],
        )

        if not isinstance(collection, (list, tuple)):
            continue

        for project_index, widget in enumerate(collection):
            if widget is None:
                continue

            def handler(
                event=None,
                idx=project_index,
            ):
                _v90_schedule_project_calculation(
                    namespace,
                    idx,
                )

            try:
                widget.bind(
                    "<KeyRelease>",
                    handler,
                    add="+",
                )
            except Exception:
                pass

            try:
                widget.bind(
                    "<FocusOut>",
                    handler,
                    add="+",
                )
            except Exception:
                pass

            try:
                widget.bind(
                    "<<Paste>>",
                    lambda event, idx=project_index: (
                        _v90_after(
                            namespace,
                            f"paste:{idx}",
                            10,
                            lambda i=idx: (
                                _v90_schedule_project_calculation(
                                    namespace,
                                    i,
                                )
                            ),
                        )
                    ),
                    add="+",
                )
            except Exception:
                pass

    for collection_name in (
        "entry_overhead",
        "entry_tech_fee",
        "entry_daily_wage",
        "entry_man_months",
    ):
        collection = namespace.get(
            collection_name,
            [],
        )

        for item in collection:
            widgets = (
                item
                if isinstance(item, (list, tuple))
                else [item]
            )

            for widget in widgets:
                if widget is None:
                    continue

                try:
                    widget.bind(
                        "<KeyRelease>",
                        lambda event: (
                            _v90_schedule_render(
                                namespace,
                                integrated_only=False,
                                delay=260,
                            )
                        ),
                        add="+",
                    )
                except Exception:
                    pass

    for name in (
        "ent_work_days",
        "ent_insurance",
    ):
        widget = namespace.get(name)

        if widget is None:
            continue

        try:
            widget.bind(
                "<KeyRelease>",
                lambda event: _v90_schedule_render(
                    namespace,
                    integrated_only=False,
                    delay=260,
                ),
                add="+",
            )
        except Exception:
            pass


