def _v91_previous_v90_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    if namespace.get(
        "_v90_runtime_patch_installed"
    ):
        _v90_hide_save_buttons(namespace)
        return

    namespace[
        "_v90_runtime_patch_installed"
    ] = True

    normalized_trade = str(
        trade_name or ""
    ).strip()

    if normalized_trade not in (
        "전기",
        "통신",
        "소방",
    ):
        for suffix in (
            "_current_trade_name",
        ):
            _, function = _v90_find_function(
                namespace,
                suffix,
            )

            if not callable(function):
                continue

            try:
                candidate = str(function()).strip()

                if candidate in (
                    "전기",
                    "통신",
                    "소방",
                ):
                    normalized_trade = candidate
                    break
            except Exception:
                pass

    if normalized_trade not in (
        "전기",
        "통신",
        "소방",
    ):
        normalized_trade = str(
            namespace.get(
                "current_supervision_type",
                "전기",
            )
        ).strip()

    if normalized_trade not in (
        "전기",
        "통신",
        "소방",
    ):
        normalized_trade = "전기"

    namespace["_v90_trade_name"] = normalized_trade

    # 최종본89 자동 갱신 타이머를 최종본107 디바운스로 교체
    globals()[
        "_v89_schedule_refresh"
    ] = _v90_v89_schedule_refresh_compat

    _v90_install_calculation_debounce(
        namespace
    )

    _v90_install_render_debounce(
        namespace
    )

    _v90_wrap_existing_project4_function(
        namespace
    )

    _v90_bind_project4(
        namespace
    )

    _v90_bind_common_inputs(
        namespace
    )

    _v90_wrap_navigation(
        namespace
    )

    _v90_hide_save_buttons(
        namespace
    )

    root = namespace.get("root")

    def initial_sync():
        _v90_hide_save_buttons(namespace)

        # 기존 O 상태를 우선 사업4에 반영한다.
        if _v90_selected_indices(namespace):
            _v90_checks_to_project4(namespace)

        _v90_schedule_render(
            namespace,
            integrated_only=False,
            delay=100,
        )

    if root is not None:
        try:
            root.after_idle(initial_sync)
            root.after(300, initial_sync)
            root.after(900, initial_sync)
        except Exception:
            initial_sync()
    else:
        initial_sync()

# ================================================================
# 최종본107
# 1. Excel 산출조서 실제 위젯 영역 셀 병합
# 2. 소방 최소 필요배치인원 날짜 자동 연동
# ================================================================

import re as _v91_re
from copy import copy as _v91_copy


# ----------------------------------------------------------------
# 공통 위젯 함수
# ----------------------------------------------------------------

def _v91_get_widget_value(widget):
    if widget is None:
        return ""

    try:
        return str(widget.get())
    except Exception:
        return ""


def _v91_set_widget_value(widget, value):
    """
    Entry의 기존 상태를 유지하면서 값이 달라질 때만 변경한다.
    """
    if widget is None:
        return False

    value = "" if value is None else str(value)

    try:
        old_value = str(widget.get())
    except Exception:
        return False

    if old_value == value:
        return False

    try:
        old_state = str(widget.cget("state"))
    except Exception:
        old_state = "normal"

    try:
        if old_state != "normal":
            widget.configure(state="normal")
    except Exception:
        pass

    changed = False

    try:
        widget.delete(0, "end")

        if value:
            widget.insert(0, value)

        changed = True
    except Exception:
        pass

    try:
        if old_state in ("readonly", "disabled"):
            widget.configure(state=old_state)
    except Exception:
        pass

    return changed


def _v91_get_item(collection, project_index, role_index=None):
    try:
        result = collection[project_index]

        if role_index is not None:
            result = result[role_index]

        return result
    except Exception:
        return None


def _v91_schedule(namespace, key, delay, callback):
    root = namespace.get("root")

    jobs = namespace.setdefault(
        "_v91_after_jobs",
        {},
    )

    old_job = jobs.pop(key, None)

    if root is not None and old_job is not None:
        try:
            root.after_cancel(old_job)
        except Exception:
            pass

    def run():
        jobs.pop(key, None)

        try:
            callback()
        except Exception:
            pass

    if root is None:
        run()
        return

    try:
        jobs[key] = root.after(
            int(delay),
            run,
        )
    except Exception:
        run()


# ================================================================
# Excel 셀 병합 보정
# ================================================================

def _v91_ranges_intersect(first, second):
    first_min_row, first_min_col, first_max_row, first_max_col = first
    second_min_row, second_min_col, second_max_row, second_max_col = second

    return not (
        first_max_row < second_min_row
        or first_min_row > second_max_row
        or first_max_col < second_min_col
        or first_min_col > second_max_col
    )


def _v91_range_contains(outer, inner):
    outer_min_row, outer_min_col, outer_max_row, outer_max_col = outer
    inner_min_row, inner_min_col, inner_max_row, inner_max_col = inner

    return (
        outer_min_row <= inner_min_row
        and outer_min_col <= inner_min_col
        and outer_max_row >= inner_max_row
        and outer_max_col >= inner_max_col
    )


def _v91_nonempty_cells(ws, cell_range):
    min_row, min_col, max_row, max_col = cell_range
    result = []

    for row in range(min_row, max_row + 1):
        for column in range(min_col, max_col + 1):
            cell = ws.cell(
                row=row,
                column=column,
            )

            if cell.__class__.__name__ == "MergedCell":
                continue

            value = cell.value

            if value is None:
                continue

            if isinstance(value, str) and not value.strip():
                continue

            result.append(cell)

    return result


def _v91_merge_single_range(ws, cell_range):
    """
    범위 안에 실제 값이 0개 또는 1개인 경우만 병합한다.

    이미 병합된 범위가 후보 범위 안에 완전히 들어가면 기존 병합을
    해제하고 더 넓은 위젯 범위로 다시 병합한다.

    일부만 겹치는 병합 영역이 있으면 충돌 방지를 위해 건너뛴다.
    """
    min_row, min_col, max_row, max_col = cell_range

    if (
        min_row == max_row
        and min_col == max_col
    ):
        return False

    nonempty_cells = _v91_nonempty_cells(
        ws,
        cell_range,
    )

    if len(nonempty_cells) > 1:
        return False

    intersecting_ranges = []

    for merged_range in list(
        ws.merged_cells.ranges
    ):
        merged_tuple = (
            merged_range.min_row,
            merged_range.min_col,
            merged_range.max_row,
            merged_range.max_col,
        )

        if not _v91_ranges_intersect(
            cell_range,
            merged_tuple,
        ):
            continue

        if not _v91_range_contains(
            cell_range,
            merged_tuple,
        ):
            return False

        intersecting_ranges.append(
            str(merged_range)
        )

    target_cell = ws.cell(
        row=min_row,
        column=min_col,
    )

    source_cell = (
        nonempty_cells[0]
        if nonempty_cells
        else target_cell
    )

    value = source_cell.value

    try:
        font = _v91_copy(source_cell.font)
        fill = _v91_copy(source_cell.fill)
        border = _v91_copy(source_cell.border)
        alignment = _v91_copy(source_cell.alignment)
        protection = _v91_copy(source_cell.protection)
        number_format = source_cell.number_format
    except Exception:
        font = None
        fill = None
        border = None
        alignment = None
        protection = None
        number_format = None

    for merged_range in intersecting_ranges:
        try:
            ws.unmerge_cells(merged_range)
        except Exception:
            return False

    try:
        target_cell = ws.cell(
            row=min_row,
            column=min_col,
        )

        target_cell.value = value

        if font is not None:
            target_cell.font = font

        if fill is not None:
            target_cell.fill = fill

        if border is not None:
            target_cell.border = border

        if alignment is not None:
            target_cell.alignment = alignment

        if protection is not None:
            target_cell.protection = protection

        if number_format is not None:
            target_cell.number_format = number_format

        ws.merge_cells(
            start_row=min_row,
            start_column=min_col,
            end_row=max_row,
            end_column=max_col,
        )

        return True

    except Exception:
        return False


def _v91_build_export_candidates(
    root_widget,
    excluded_roots=None,
):
    """
    기존 Excel 출력 함수와 동일한 좌표 기준으로
    각 Tkinter 위젯의 Excel 병합 후보 범위를 계산한다.
    """
    collect_function = globals().get(
        "_v71_collect_export_items"
    )

    relative_function = globals().get(
        "_v71_relative_position"
    )

    if not callable(collect_function):
        return []

    try:
        items = collect_function(
            root_widget,
            excluded_roots=excluded_roots,
        )
    except Exception:
        return []

    normalized_items = []

    for item in items:
        try:
            copied = dict(item)

            copied["x"] = max(
                0,
                int(float(item.get("x", 0))),
            )

            copied["y"] = max(
                0,
                int(float(item.get("y", 0))),
            )

            copied["width"] = max(
                8,
                int(float(item.get("width", 8))),
            )

            copied["height"] = max(
                8,
                int(float(item.get("height", 8))),
            )

            normalized_items.append(copied)

        except Exception:
            pass

    if not normalized_items:
        return []

    minimum_x = min(
        item["x"]
        for item in normalized_items
    )

    minimum_y = min(
        item["y"]
        for item in normalized_items
    )

    def snap(value, unit=4):
        try:
            return int(
                round(float(value) / unit) * unit
            )
        except Exception:
            return 0

    for item in normalized_items:
        original_x = max(
            0,
            item["x"] - minimum_x,
        )

        original_y = max(
            0,
            item["y"] - minimum_y,
        )

        right = original_x + item["width"]
        bottom = original_y + item["height"]

        item["x"] = snap(original_x)
        item["y"] = snap(original_y)
        item["right"] = snap(right)
        item["bottom"] = snap(bottom)

        if item["right"] <= item["x"]:
            item["right"] = item["x"] + 8

        if item["bottom"] <= item["y"]:
            item["bottom"] = item["y"] + 8

    x_boundaries = {0}
    y_boundaries = {0}

    for item in normalized_items:
        x_boundaries.add(item["x"])
        x_boundaries.add(item["right"])
        y_boundaries.add(item["y"])
        y_boundaries.add(item["bottom"])

        if (
            item.get("kind") == "labelframe_title"
            and callable(relative_function)
        ):
            frame_widget = item.get("widget")

            try:
                frame_x, frame_y = relative_function(
                    frame_widget,
                    root_widget,
                )

                frame_x = snap(
                    max(
                        0,
                        int(frame_x) - minimum_x,
                    )
                )

                frame_y = snap(
                    max(
                        0,
                        int(frame_y) - minimum_y,
                    )
                )

                frame_width = max(
                    20,
                    int(frame_widget.winfo_width()),
                )

                frame_height = max(
                    20,
                    int(frame_widget.winfo_height()),
                )

                frame_right = snap(
                    frame_x + frame_width
                )

                frame_bottom = snap(
                    frame_y + frame_height
                )

                if frame_right <= frame_x:
                    frame_right = frame_x + 20

                if frame_bottom <= frame_y:
                    frame_bottom = frame_y + 20

                x_boundaries.add(frame_x)
                x_boundaries.add(frame_right)
                y_boundaries.add(frame_y)
                y_boundaries.add(frame_bottom)

            except Exception:
                pass

    x_boundaries = sorted(x_boundaries)
    y_boundaries = sorted(y_boundaries)

    if len(x_boundaries) < 2:
        return []

    if len(y_boundaries) < 2:
        return []

    x_index = {
        coordinate: index
        for index, coordinate
        in enumerate(x_boundaries)
    }

    y_index = {
        coordinate: index
        for index, coordinate
        in enumerate(y_boundaries)
    }

    candidates = []

    input_classes = {
        "Entry",
        "TEntry",
        "TCombobox",
        "Spinbox",
        "Text",
        "Listbox",
    }

    label_classes = {
        "Label",
        "TLabel",
        "Button",
        "TButton",
        "Checkbutton",
        "TCheckbutton",
        "Radiobutton",
        "TRadiobutton",
    }

    for item in normalized_items:
        try:
            start_col = x_index[item["x"]] + 1
            end_col = x_index[item["right"]]

            start_row = y_index[item["y"]] + 1
            end_row = y_index[item["bottom"]]

            end_col = max(start_col, end_col)
            end_row = max(start_row, end_row)

            if (
                start_col == end_col
                and start_row == end_row
            ):
                continue

            widget = item.get("widget")

            try:
                widget_class = str(
                    widget.winfo_class()
                )
            except Exception:
                widget_class = ""

            if widget_class in input_classes:
                priority = 0
            elif widget_class in label_classes:
                priority = 1
            elif item.get("kind") == "labelframe_title":
                priority = 2
            else:
                priority = 3

            area = (
                (end_col - start_col + 1)
                * (end_row - start_row + 1)
            )

            candidates.append(
                (
                    priority,
                    -area,
                    (
                        start_row,
                        start_col,
                        end_row,
                        end_col,
                    ),
                )
            )

        except Exception:
            pass

    candidates.sort(
        key=lambda item: (
            item[0],
            item[1],
            item[2][0],
            item[2][1],
        )
    )

    result = []
    seen = set()

    for _, _, cell_range in candidates:
        if cell_range in seen:
            continue

        seen.add(cell_range)
        result.append(cell_range)

    return result


def _v91_merge_exported_widget_cells(
    ws,
    root_widget,
    excluded_roots=None,
):
    """
    화면상 하나의 위젯인데 Excel에서 여러 칸으로 분해된 영역을
    실제 Excel 병합 셀로 보정한다.
    """
    candidates = _v91_build_export_candidates(
        root_widget,
        excluded_roots=excluded_roots,
    )

    merged_count = 0

    for cell_range in candidates:
        if _v91_merge_single_range(
            ws,
            cell_range,
        ):
            merged_count += 1

    try:
        ws.sheet_view.showGridLines = False
    except Exception:
        pass

    return merged_count


def _v91_install_excel_merge_patch():
    if globals().get(
        "_v91_excel_merge_patch_installed"
    ):
        return

    original = globals().get(
        "_v71_write_widget_sheet"
    )

    if not callable(original):
        return

    if getattr(
        original,
        "_v91_excel_merge_wrapper",
        False,
    ):
        globals()[
            "_v91_excel_merge_patch_installed"
        ] = True
        return

    globals()[
        "_v91_original_write_widget_sheet"
    ] = original

    def wrapper(
        workbook,
        sheet_name,
        root_widget,
        excluded_roots=None,
    ):
        ws = original(
            workbook,
            sheet_name,
            root_widget,
            excluded_roots=excluded_roots,
        )

        try:
            _v91_merge_exported_widget_cells(
                ws,
                root_widget,
                excluded_roots=excluded_roots,
            )
        except Exception:
            pass

        return ws

    wrapper._v91_excel_merge_wrapper = True
    wrapper.__name__ = "_v71_write_widget_sheet"

    globals()[
        "_v71_write_widget_sheet"
    ] = wrapper

    globals()[
        "_v91_excel_merge_patch_installed"
    ] = True


# ================================================================
# 소방 최소 필요배치인원 날짜 연동
# ================================================================

def _v91_get_fire_count_text(namespace, project_index):
    try:
        all_refs = namespace.get(
            "fire_supervision_all_refs",
            [],
        )

        refs = all_refs[project_index]

        return _v91_get_widget_value(
            refs.get("count")
        )
    except Exception:
        return ""


def _v91_parse_role_count(count_text, role_name):
    """
    예:
        상주(보조) 1명
        비상주 2명
    """
    count_text = str(count_text or "")

    if role_name == "assistant":
        patterns = (
            r"상주\s*\(\s*보조\s*\)\s*(\d+)\s*명",
            r"상주보조\s*(\d+)\s*명",
            r"보조\s*(\d+)\s*명",
        )
    else:
        patterns = (
            r"비상주\s*(\d+)\s*명",
        )

    for pattern in patterns:
        match = _v91_re.search(
            pattern,
            count_text,
        )

        if match:
            try:
                return max(
                    0,
                    int(match.group(1)),
                )
            except Exception:
                return 0

    return 0


def _v91_copy_fire_date_pair(
    start_source,
    end_source,
    start_target,
    end_target,
):
    start_value = _v91_get_widget_value(
        start_source
    )

    end_value = _v91_get_widget_value(
        end_source
    )

    changed_start = _v91_set_widget_value(
        start_target,
        start_value,
    )

    changed_end = _v91_set_widget_value(
        end_target,
        end_value,
    )

    return changed_start or changed_end


def _v91_fire_sync_required_dates(
    namespace,
    project_index=None,
):
    """
    최소 필요배치인원으로 표시된 소방 감리원의 날짜를
    상주책임 투입일·종료일과 동일하게 만든다.
    """
    if str(
        namespace.get("_v90_trade_name", "")
    ).strip() != "소방":
        return

    if namespace.get("_v91_fire_date_busy"):
        return

    namespace["_v91_fire_date_busy"] = True

    changed_projects = []

    try:
        responsible_starts = namespace.get(
            "entry_res_start_display",
            [],
        )

        responsible_ends = namespace.get(
            "entry_res_end_display",
            [],
        )

        assistant_starts = namespace.get(
            "entry_sub_res_start",
            [],
        )

        assistant_ends = namespace.get(
            "entry_sub_res_end",
            [],
        )

        nonresident_starts = namespace.get(
            "entry_nonres_start",
            [],
        )

        nonresident_ends = namespace.get(
            "entry_nonres_end",
            [],
        )

        if project_index is None:
            indices = range(
                min(
                    4,
                    len(responsible_starts),
                    len(responsible_ends),
                )
            )
        else:
            try:
                indices = [int(project_index)]
            except Exception:
                indices = []

        for index in indices:
            responsible_start = _v91_get_item(
                responsible_starts,
                index,
            )

            responsible_end = _v91_get_item(
                responsible_ends,
                index,
            )

            if (
                responsible_start is None
                or responsible_end is None
            ):
                continue

            count_text = _v91_get_fire_count_text(
                namespace,
                index,
            )

            assistant_count = _v91_parse_role_count(
                count_text,
                "assistant",
            )

            nonresident_count = _v91_parse_role_count(
                count_text,
                "nonresident",
            )

            # 기존 표의 기본 규칙에 대한 안전 보완
            if (
                not count_text
                or (
                    assistant_count == 0
                    and nonresident_count == 0
                )
            ):
                try:
                    area_widget = _v91_get_item(
                        namespace.get(
                            "entry_area",
                            [],
                        ),
                        index,
                    )

                    area_text = (
                        _v91_get_widget_value(area_widget)
                        .replace(",", "")
                        .strip()
                    )

                    area = float(
                        area_text or 0
                    )

                    if area >= 30000:
                        assistant_count = 1
                    elif area > 0:
                        nonresident_count = 1

                except Exception:
                    pass

            project_changed = False

            assistant_start_group = _v91_get_item(
                assistant_starts,
                index,
            )

            assistant_end_group = _v91_get_item(
                assistant_ends,
                index,
            )

            if not isinstance(
                assistant_start_group,
                (list, tuple),
            ):
                assistant_start_group = [
                    assistant_start_group
                ]

            if not isinstance(
                assistant_end_group,
                (list, tuple),
            ):
                assistant_end_group = [
                    assistant_end_group
                ]

            assistant_limit = min(
                assistant_count,
                len(assistant_start_group),
                len(assistant_end_group),
            )

            for role_index in range(
                assistant_limit
            ):
                if _v91_copy_fire_date_pair(
                    responsible_start,
                    responsible_end,
                    assistant_start_group[role_index],
                    assistant_end_group[role_index],
                ):
                    project_changed = True

            nonresident_start_group = _v91_get_item(
                nonresident_starts,
                index,
            )

            nonresident_end_group = _v91_get_item(
                nonresident_ends,
                index,
            )

            if not isinstance(
                nonresident_start_group,
                (list, tuple),
            ):
                nonresident_start_group = [
                    nonresident_start_group
                ]

            if not isinstance(
                nonresident_end_group,
                (list, tuple),
            ):
                nonresident_end_group = [
                    nonresident_end_group
                ]

            nonresident_limit = min(
                nonresident_count,
                len(nonresident_start_group),
                len(nonresident_end_group),
            )

            for role_index in range(
                nonresident_limit
            ):
                if _v91_copy_fire_date_pair(
                    responsible_start,
                    responsible_end,
                    nonresident_start_group[role_index],
                    nonresident_end_group[role_index],
                ):
                    project_changed = True

            if project_changed:
                changed_projects.append(index)

    finally:
        namespace["_v91_fire_date_busy"] = False

    update_function = namespace.get(
        "fire_update_fire_actual_cost_table"
    )

    if callable(update_function):
        for index in changed_projects:
            try:
                update_function(index)
            except Exception:
                pass

    schedule_render = globals().get(
        "_v90_schedule_render"
    )

    if changed_projects and callable(schedule_render):
        try:
            schedule_render(
                namespace,
                integrated_only=False,
                delay=120,
            )
        except Exception:
            pass


def _v91_bind_fire_responsible_dates(namespace):
    if str(
        namespace.get("_v90_trade_name", "")
    ).strip() != "소방":
        return

    if namespace.get(
        "_v91_fire_dates_bound"
    ):
        return

    namespace[
        "_v91_fire_dates_bound"
    ] = True

    starts = namespace.get(
        "entry_res_start_display",
        [],
    )

    ends = namespace.get(
        "entry_res_end_display",
        [],
    )

    maximum = min(
        len(starts),
        len(ends),
        4,
    )

    for project_index in range(maximum):
        for widget in (
            starts[project_index],
            ends[project_index],
        ):
            if widget is None:
                continue

            def handler(
                event=None,
                index=project_index,
            ):
                _v91_schedule(
                    namespace,
                    f"fire-date:{index}",
                    30,
                    lambda idx=index: (
                        _v91_fire_sync_required_dates(
                            namespace,
                            idx,
                        )
                    ),
                )

            try:
                widget.bind(
                    "<KeyRelease>",
                    handler,
                    add="+",
                )
            except Exception:
                pass

            try:
                widget.bind(
                    "<FocusOut>",
                    handler,
                    add="+",
                )
            except Exception:
                pass

            try:
                widget.bind(
                    "<<Paste>>",
                    handler,
                    add="+",
                )
            except Exception:
                pass


def _v91_wrap_fire_supervision_update(namespace):
    """
    최소 필요배치인원과 등급이 다시 계산된 다음 날짜도 다시 연동한다.
    """
    function_name = (
        "fire_update_fire_supervision_table"
    )

    original = namespace.get(function_name)

    if not callable(original):
        return

    if getattr(
        original,
        "_v91_fire_supervision_wrapper",
        False,
    ):
        return

    def wrapper(index=None, *args, **kwargs):
        result = original(
            index,
            *args,
            **kwargs
        )

        _v91_schedule(
            namespace,
            "fire-required-date-sync",
            260,
            lambda idx=index: (
                _v91_fire_sync_required_dates(
                    namespace,
                    idx,
                )
            ),
        )

        return result

    wrapper._v91_fire_supervision_wrapper = True
    wrapper.__name__ = function_name

    namespace[function_name] = wrapper


def _v91_install_fire_date_patch(namespace):
    if str(
        namespace.get("_v90_trade_name", "")
    ).strip() != "소방":
        return

    _v91_wrap_fire_supervision_update(
        namespace
    )

    _v91_bind_fire_responsible_dates(
        namespace
    )

    root = namespace.get("root")

    def initial_sync():
        _v91_fire_sync_required_dates(
            namespace
        )

    if root is not None:
        try:
            root.after_idle(initial_sync)
            root.after(500, initial_sync)
            root.after(1200, initial_sync)
        except Exception:
            initial_sync()
    else:
        initial_sync()


# ================================================================
# 최종본107 설치
# ================================================================

def _v92_previous_v91_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    _v91_install_excel_merge_patch()

    if namespace.get(
        "_v91_runtime_patch_installed"
    ):
        if str(
            namespace.get("_v90_trade_name", "")
        ).strip() == "소방":
            _v91_install_fire_date_patch(
                namespace
            )
        return

    namespace[
        "_v91_runtime_patch_installed"
    ] = True

    if trade_name in (
        "전기",
        "통신",
        "소방",
    ):
        namespace[
            "_v90_trade_name"
        ] = trade_name

    _v91_install_fire_date_patch(
        namespace
    )

# ================================================================
# 최종본107 보정 패치
#
# 1. 사업4 사업명 분석 → 사업1·2·3 통합배치 O/X 자동 선택
# 2. Excel 산출조서 잔여 분할 셀 병합
# 3. 소방 최소 필요배치 역할별 날짜·등급 정확한 연동
# ================================================================

import re as _v92_re
from copy import copy as _v92_copy


# ----------------------------------------------------------------
# 공통 함수
# ----------------------------------------------------------------

def _v92_get(widget, default=""):
    if widget is None:
        return default

    try:
        return str(widget.get())
    except Exception:
        return default


def _v92_put(widget, value):
    if widget is None:
        return False

    value = "" if value is None else str(value)

    try:
        current = str(widget.get())
    except Exception:
        return False

    if current == value:
        return False

    try:
        old_state = str(widget.cget("state"))
    except Exception:
        old_state = "normal"

    try:
        if old_state != "normal":
            widget.configure(state="normal")
    except Exception:
        pass

    changed = False

    try:
        widget.delete(0, "end")

        if value:
            widget.insert(0, value)

        changed = True
    except Exception:
        pass

    try:
        if old_state in ("readonly", "disabled"):
            widget.configure(state=old_state)
    except Exception:
        pass

    return changed


def _v92_set_variable(variable, value):
    if variable is None:
        return False

    try:
        if str(variable.get()) == str(value):
            return False
    except Exception:
        return False

    try:
        variable.set(value)
        return True
    except Exception:
        return False


def _v92_item(collection, index, sub_index=None):
    try:
        result = collection[index]

        if sub_index is not None:
            result = result[sub_index]

        return result
    except Exception:
        return None


def _v92_schedule(namespace, key, delay, callback):
    root = namespace.get("root")

    jobs = namespace.setdefault(
        "_v92_after_jobs",
        {},
    )

    old_job = jobs.pop(key, None)

    if root is not None and old_job is not None:
        try:
            root.after_cancel(old_job)
        except Exception:
            pass

    def run():
        jobs.pop(key, None)

        try:
            callback()
        except Exception:
            pass

    if root is None:
        run()
        return

    try:
        jobs[key] = root.after(
            int(delay),
            run,
        )
    except Exception:
        run()


def _v92_normalize(value):
    return "".join(
        character.lower()
        for character in str(value or "")
        if character.isalnum()
    )


def _v92_tokens(value):
    """
    사업명에서 비교 가치가 낮은 공통 단어를 제거한다.
    """
    stop_words = {
        "공사",
        "사업",
        "현장",
        "서울대학교",
        "서울대",
        "감리",
        "용역",
        "건축",
        "건설",
        "전기",
        "통신",
        "소방",
        "신축",
        "증축",
        "개축",
        "재축",
        "증설",
        "개량",
        "보수",
        "리모델링",
    }

    result = []

    for token in _v92_re.findall(
        r"[가-힣A-Za-z0-9]+",
        str(value or ""),
    ):
        token = token.strip().lower()

        if len(token) < 2:
            continue

        if token in stop_words:
            continue

        result.append(token)

    return result


# ================================================================
# 1. 사업4 사업명 → 통합배치 O/X 자동 선택
# ================================================================

def _v92_project_name_matches(
    project_name,
    integrated_name,
):
    project_normalized = _v92_normalize(
        project_name
    )

    integrated_normalized = _v92_normalize(
        integrated_name
    )

    if not project_normalized:
        return False

    if not integrated_normalized:
        return False

    # 전체 사업명이 사업4 사업명에 포함되는 경우
    if project_normalized in integrated_normalized:
        return True

    # 반대로 사업4 내용이 사업명 전체와 일치하는 경우
    if integrated_normalized == project_normalized:
        return True

    project_tokens = _v92_tokens(
        project_name
    )

    integrated_tokens = set(
        _v92_tokens(integrated_name)
    )

    # 공백·쉼표 등이 제거된 사업4 문자열에서도 핵심 단어 검사
    for token in project_tokens:
        normalized_token = _v92_normalize(
            token
        )

        if not normalized_token:
            continue

        if normalized_token in integrated_normalized:
            return True

        if token in integrated_tokens:
            return True

    return False


def _v92_integrated_variable_groups(namespace):
    groups = []
    group_ids = set()

    for name in (
        "var_integrated",
        "communication_integrated_vars",
        "fire_integrated_vars",
    ):
        group = namespace.get(name)

        if not isinstance(
            group,
            (list, tuple),
        ):
            continue

        if len(group) < 3:
            continue

        group_id = id(group)

        if group_id in group_ids:
            continue

        group_ids.add(group_id)
        groups.append(group)

    return groups


def _v92_update_integration_rules(namespace):
    for function_name in (
        "electric_update_integration_rules",
        "electric_update_communication_integration_rules",
        "communication_update_integration_rules",
        "communication_update_communication_integration_rules",
        "fire_update_communication_integration_rules",
        "fire_update_fire_integration_rules",
        "update_integration_rules",
    ):
        function = namespace.get(function_name)

        if not callable(function):
            continue

        try:
            function()
        except Exception:
            pass


def _v92_project4_name_to_radio(namespace):
    if namespace.get(
        "_v92_project4_match_busy"
    ):
        return

    names = namespace.get(
        "entry_names",
        [],
    )

    project4_widget = _v92_item(
        names,
        3,
    )

    project4_name = _v92_get(
        project4_widget
    ).strip()

    selected = []

    if project4_name:
        for index in range(3):
            project_name = _v92_get(
                _v92_item(names, index)
            ).strip()

            if _v92_project_name_matches(
                project_name,
                project4_name,
            ):
                selected.append(index)

    namespace[
        "_v92_project4_match_busy"
    ] = True

    try:
        for group in _v92_integrated_variable_groups(
            namespace
        ):
            for index in range(3):
                _v92_set_variable(
                    group[index],
                    "O" if index in selected else "X",
                )

        # 기존 trace가 사업4 명칭을 다시 작성하더라도
        # 현재 입력값을 즉시 보존한다.
        _v92_put(
            project4_widget,
            project4_name,
        )

    finally:
        namespace[
            "_v92_project4_match_busy"
        ] = False

    _v92_update_integration_rules(
        namespace
    )

    schedule_render = globals().get(
        "_v90_schedule_render"
    )

    if callable(schedule_render):
        try:
            schedule_render(
                namespace,
                integrated_only=True,
                delay=100,
            )
        except Exception:
            pass


def _v92_bind_project4_name(namespace):
    if namespace.get(
        "_v92_project4_name_bound"
    ):
        return

    names = namespace.get(
        "entry_names",
        [],
    )

    project4_widget = _v92_item(
        names,
        3,
    )

    if project4_widget is None:
        return

    namespace[
        "_v92_project4_name_bound"
    ] = True

    def handler(event=None):
        _v92_schedule(
            namespace,
            "project4-name-match",
            250,
            lambda: _v92_project4_name_to_radio(
                namespace
            ),
        )

    for event_name in (
        "<KeyRelease>",
        "<FocusOut>",
        "<<Paste>>",
    ):
        try:
            project4_widget.bind(
                event_name,
                handler,
                add="+",
            )
        except Exception:
            pass

    # 사업1~3의 사업명이 변경된 경우도 사업4와 다시 비교
    for index in range(3):
        widget = _v92_item(
            names,
            index,
        )

        if widget is None:
            continue

        try:
            widget.bind(
                "<KeyRelease>",
                handler,
                add="+",
            )
        except Exception:
            pass

        try:
            widget.bind(
                "<FocusOut>",
                handler,
                add="+",
            )
        except Exception:
            pass


# ================================================================
# 2. Excel 산출조서 잔여 분할 셀 병합
# ================================================================

def _v92_cell_value_exists(cell):
    if cell.__class__.__name__ == "MergedCell":
        return False

    value = cell.value

    if value is None:
        return False

    if isinstance(value, str):
        return bool(value.strip())

    return True


def _v92_fill_signature(cell):
    try:
        fill = cell.fill

        foreground = fill.fgColor

        return (
            str(fill.fill_type),
            str(foreground.type),
            str(foreground.rgb),
            str(foreground.indexed),
            str(foreground.theme),
        )
    except Exception:
        return None


def _v92_merged_ranges_for_row(ws, row):
    result = []

    for merged in list(
        ws.merged_cells.ranges
    ):
        if merged.min_row <= row <= merged.max_row:
            result.append(
                (
                    merged.min_row,
                    merged.min_col,
                    merged.max_row,
                    merged.max_col,
                    str(merged),
                )
            )

    return result


def _v92_range_intersects(
    first_min_row,
    first_min_col,
    first_max_row,
    first_max_col,
    second,
):
    (
        second_min_row,
        second_min_col,
        second_max_row,
        second_max_col,
        _,
    ) = second

    return not (
        first_max_row < second_min_row
        or first_min_row > second_max_row
        or first_max_col < second_min_col
        or first_min_col > second_max_col
    )


def _v92_copy_cell_style(source, target):
    try:
        target.font = _v92_copy(source.font)
    except Exception:
        pass

    try:
        target.fill = _v92_copy(source.fill)
    except Exception:
        pass

    try:
        target.border = _v92_copy(source.border)
    except Exception:
        pass

    try:
        target.alignment = _v92_copy(
            source.alignment
        )
    except Exception:
        pass

    try:
        target.protection = _v92_copy(
            source.protection
        )
    except Exception:
        pass

    try:
        target.number_format = (
            source.number_format
        )
    except Exception:
        pass


def _v92_merge_blank_run(
    ws,
    row,
    start_column,
    end_column,
):
    if end_column - start_column + 1 < 2:
        return False

    row_merges = _v92_merged_ranges_for_row(
        ws,
        row,
    )

    for merged in row_merges:
        if _v92_range_intersects(
            row,
            start_column,
            row,
            end_column,
            merged,
        ):
            return False

    cells = [
        ws.cell(
            row=row,
            column=column,
        )
        for column in range(
            start_column,
            end_column + 1,
        )
    ]

    if any(
        _v92_cell_value_exists(cell)
        for cell in cells
    ):
        return False

    # 색상이 서로 다른 영역은 별도의 입력 또는 출력 영역이므로
    # 강제로 합치지 않는다.
    signatures = {
        _v92_fill_signature(cell)
        for cell in cells
    }

    if len(signatures) > 1:
        return False

    first_cell = cells[0]

    try:
        ws.merge_cells(
            start_row=row,
            start_column=start_column,
            end_row=row,
            end_column=end_column,
        )

        merged_cell = ws.cell(
            row=row,
            column=start_column,
        )

        _v92_copy_cell_style(
            first_cell,
            merged_cell,
        )

        try:
            merged_cell.alignment = _v92_copy(
                first_cell.alignment
            )

            merged_cell.alignment = (
                merged_cell.alignment.copy(
                    horizontal="center",
                    vertical="center",
                )
            )
        except Exception:
            pass

        return True

    except Exception:
        return False


def _v92_merge_fragmented_rows(ws):
    """
    기존 위젯 좌표 병합 후에도 남아 있는 가로 분할 셀을 병합한다.

    병합 조건:
      - 같은 행에 텍스트 또는 숫자가 하나 이상 존재
      - 값 사이 또는 값 오른쪽에 연속된 빈 셀이 2개 이상
      - 동일한 배경색
      - 기존 병합 범위와 충돌하지 않음
    """
    max_row = ws.max_row
    max_column = ws.max_column

    if max_row < 1 or max_column < 2:
        return 0

    merged_count = 0

    for row in range(1, max_row + 1):
        value_columns = []

        for column in range(
            1,
            max_column + 1,
        ):
            cell = ws.cell(
                row=row,
                column=column,
            )

            if _v92_cell_value_exists(cell):
                value_columns.append(column)

        # 완전히 빈 줄은 표 구조를 보존하기 위해 병합하지 않는다.
        if not value_columns:
            continue

        occupied = set()

        for merged in _v92_merged_ranges_for_row(
            ws,
            row,
        ):
            for column in range(
                merged[1],
                merged[3] + 1,
            ):
                occupied.add(column)

        start = None

        for column in range(
            1,
            max_column + 2,
        ):
            if column <= max_column:
                cell = ws.cell(
                    row=row,
                    column=column,
                )

                blank = (
                    not _v92_cell_value_exists(cell)
                    and column not in occupied
                )
            else:
                blank = False

            if blank and start is None:
                start = column

            if not blank and start is not None:
                end = column - 1

                left_has_value = (
                    start > 1
                    and _v92_cell_value_exists(
                        ws.cell(
                            row=row,
                            column=start - 1,
                        )
                    )
                )

                right_has_value = (
                    end < max_column
                    and _v92_cell_value_exists(
                        ws.cell(
                            row=row,
                            column=end + 1,
                        )
                    )
                )

                # 값과 관계없는 좌측 여백은 병합하지 않는다.
                if (
                    left_has_value
                    or right_has_value
                ):
                    if _v92_merge_blank_run(
                        ws,
                        row,
                        start,
                        end,
                    ):
                        merged_count += 1

                start = None

    return merged_count


def _v92_install_excel_merge_patch():
    if globals().get(
        "_v92_excel_merge_patch_installed"
    ):
        return

    original = globals().get(
        "_v71_write_widget_sheet"
    )

    if not callable(original):
        return

    if getattr(
        original,
        "_v92_excel_merge_wrapper",
        False,
    ):
        globals()[
            "_v92_excel_merge_patch_installed"
        ] = True
        return

    def wrapper(
        workbook,
        sheet_name,
        root_widget,
        excluded_roots=None,
    ):
        ws = original(
            workbook,
            sheet_name,
            root_widget,
            excluded_roots=excluded_roots,
        )

        # 최종본107 위젯 영역 병합을 먼저 다시 적용
        merge_widget_function = globals().get(
            "_v91_merge_exported_widget_cells"
        )

        if callable(merge_widget_function):
            try:
                merge_widget_function(
                    ws,
                    root_widget,
                    excluded_roots=excluded_roots,
                )
            except Exception:
                pass

        # 남아 있는 분할 셀 추가 병합
        try:
            _v92_merge_fragmented_rows(ws)
        except Exception:
            pass

        try:
            ws.sheet_view.showGridLines = False
            ws.freeze_panes = None
        except Exception:
            pass

        return ws

    wrapper._v92_excel_merge_wrapper = True
    wrapper.__name__ = "_v71_write_widget_sheet"

    globals()[
        "_v92_original_write_widget_sheet"
    ] = original

    globals()[
        "_v71_write_widget_sheet"
    ] = wrapper

    globals()[
        "_v92_excel_merge_patch_installed"
    ] = True


