# 3. 소방 최소 필요배치 역할별 날짜·등급 연동
# ================================================================

def _v92_fire_count_text(namespace, index):
    refs_collection = namespace.get(
        "fire_supervision_all_refs",
        [],
    )

    refs = _v92_item(
        refs_collection,
        index,
    )

    if not isinstance(refs, dict):
        return ""

    return _v92_get(
        refs.get("count")
    ).strip()


def _v92_fire_grade_text(
    namespace,
    index,
    role_key,
):
    refs_collection = namespace.get(
        "fire_supervision_all_refs",
        [],
    )

    refs = _v92_item(
        refs_collection,
        index,
    )

    if not isinstance(refs, dict):
        return ""

    return _v92_get(
        refs.get(role_key)
    ).strip()


def _v92_role_required(
    count_text,
    role_key,
):
    text = _v92_re.sub(
        r"\s+",
        "",
        str(count_text or ""),
    )

    if role_key == "responsible":
        return bool(
            _v92_re.search(
                r"상주\(책임\)\d*명",
                text,
            )
            or "상주책임" in text
        )

    if role_key == "assistant":
        return bool(
            _v92_re.search(
                r"상주\(보조\)\d*명",
                text,
            )
            or "상주보조" in text
        )

    if role_key == "nonresident":
        return bool(
            _v92_re.search(
                r"비상주\d*명",
                text,
            )
        )

    return False


def _v92_fire_project_dates(namespace, index):
    """
    소방공사 착공일·준공일을 우선 사용한다.
    값이 없으면 건축공사 착공일·준공일을 사용한다.
    """
    start = _v92_get(
        _v92_item(
            namespace.get(
                "entry_elec_start_date",
                [],
            ),
            index,
        )
    ).strip()

    end = _v92_get(
        _v92_item(
            namespace.get(
                "entry_elec_end_date",
                [],
            ),
            index,
        )
    ).strip()

    if not start:
        start = _v92_get(
            _v92_item(
                namespace.get(
                    "entry_start_date",
                    [],
                ),
                index,
            )
        ).strip()

    if not end:
        end = _v92_get(
            _v92_item(
                namespace.get(
                    "entry_end_date",
                    [],
                ),
                index,
            )
        ).strip()

    return start, end


def _v92_fire_role_widgets(
    namespace,
    index,
    role_key,
):
    if role_key == "responsible":
        start_widget = _v92_item(
            namespace.get(
                "entry_res_start_display",
                [],
            ),
            index,
        )

        end_widget = _v92_item(
            namespace.get(
                "entry_res_end_display",
                [],
            ),
            index,
        )

        grade_variable = _v92_item(
            namespace.get(
                "var_grades",
                [],
            ),
            index,
            0,
        )

        return (
            [start_widget],
            [end_widget],
            [grade_variable],
        )

    if role_key == "assistant":
        start_widgets = _v92_item(
            namespace.get(
                "entry_sub_res_start",
                [],
            ),
            index,
        )

        end_widgets = _v92_item(
            namespace.get(
                "entry_sub_res_end",
                [],
            ),
            index,
        )

        if not isinstance(
            start_widgets,
            (list, tuple),
        ):
            start_widgets = [start_widgets]

        if not isinstance(
            end_widgets,
            (list, tuple),
        ):
            end_widgets = [end_widgets]

        grade_variables = [
            _v92_item(
                namespace.get(
                    "var_grades",
                    [],
                ),
                index,
                role_index,
            )
            for role_index in (1, 2, 3)
        ]

        return (
            list(start_widgets),
            list(end_widgets),
            grade_variables,
        )

    start_widgets = _v92_item(
        namespace.get(
            "entry_nonres_start",
            [],
        ),
        index,
    )

    end_widgets = _v92_item(
        namespace.get(
            "entry_nonres_end",
            [],
        ),
        index,
    )

    if not isinstance(
        start_widgets,
        (list, tuple),
    ):
        start_widgets = [start_widgets]

    if not isinstance(
        end_widgets,
        (list, tuple),
    ):
        end_widgets = [end_widgets]

    grade_variables = [
        _v92_item(
            namespace.get(
                "var_grades",
                [],
            ),
            index,
            role_index,
        )
        for role_index in (4, 5, 6)
    ]

    return (
        list(start_widgets),
        list(end_widgets),
        grade_variables,
    )


def _v92_required_role_count(
    count_text,
    role_key,
):
    text = _v92_re.sub(
        r"\s+",
        "",
        str(count_text or ""),
    )

    if role_key == "responsible":
        patterns = (
            r"상주\(책임\)(\d+)명",
            r"상주책임(\d+)명",
        )
    elif role_key == "assistant":
        patterns = (
            r"상주\(보조\)(\d+)명",
            r"상주보조(\d+)명",
        )
    else:
        patterns = (
            r"비상주(\d+)명",
        )

    for pattern in patterns:
        match = _v92_re.search(
            pattern,
            text,
        )

        if match:
            try:
                return max(
                    1,
                    int(match.group(1)),
                )
            except Exception:
                return 1

    return (
        1
        if _v92_role_required(
            count_text,
            role_key,
        )
        else 0
    )


def _v92_sync_fire_required_roles(
    namespace,
    project_index=None,
):
    trade_name = str(
        namespace.get(
            "_v90_trade_name",
            namespace.get(
                "current_supervision_type",
                "",
            ),
        )
    ).strip()

    if trade_name != "소방":
        return

    if namespace.get(
        "_v92_fire_sync_busy"
    ):
        return

    namespace[
        "_v92_fire_sync_busy"
    ] = True

    changed_indices = []

    try:
        if project_index is None:
            indices = range(4)
        else:
            try:
                indices = [int(project_index)]
            except Exception:
                indices = []

        for index in indices:
            count_text = _v92_fire_count_text(
                namespace,
                index,
            )

            if not count_text:
                continue

            project_start, project_end = (
                _v92_fire_project_dates(
                    namespace,
                    index,
                )
            )

            project_changed = False

            for role_key in (
                "responsible",
                "assistant",
                "nonresident",
            ):
                required_count = (
                    _v92_required_role_count(
                        count_text,
                        role_key,
                    )
                )

                grade = _v92_fire_grade_text(
                    namespace,
                    index,
                    role_key,
                )

                (
                    start_widgets,
                    end_widgets,
                    grade_variables,
                ) = _v92_fire_role_widgets(
                    namespace,
                    index,
                    role_key,
                )

                maximum = max(
                    len(start_widgets),
                    len(end_widgets),
                    len(grade_variables),
                )

                for role_index in range(maximum):
                    is_required = (
                        role_index < required_count
                    )

                    start_widget = _v92_item(
                        start_widgets,
                        role_index,
                    )

                    end_widget = _v92_item(
                        end_widgets,
                        role_index,
                    )

                    grade_variable = _v92_item(
                        grade_variables,
                        role_index,
                    )

                    if is_required:
                        if _v92_put(
                            start_widget,
                            project_start,
                        ):
                            project_changed = True

                        if _v92_put(
                            end_widget,
                            project_end,
                        ):
                            project_changed = True

                        if grade:
                            if _v92_set_variable(
                                grade_variable,
                                grade,
                            ):
                                project_changed = True

                    else:
                        # 필요하지 않은 역할은 날짜 및 등급 제거
                        if _v92_put(
                            start_widget,
                            "",
                        ):
                            project_changed = True

                        if _v92_put(
                            end_widget,
                            "",
                        ):
                            project_changed = True

                        if _v92_set_variable(
                            grade_variable,
                            "none",
                        ):
                            project_changed = True

            if project_changed:
                changed_indices.append(index)

    finally:
        namespace[
            "_v92_fire_sync_busy"
        ] = False

    update_cost = namespace.get(
        "fire_update_fire_actual_cost_table"
    )

    if callable(update_cost):
        for index in changed_indices:
            try:
                update_cost(index)
            except Exception:
                pass

    schedule_render = globals().get(
        "_v90_schedule_render"
    )

    if changed_indices and callable(
        schedule_render
    ):
        try:
            schedule_render(
                namespace,
                integrated_only=False,
                delay=120,
            )
        except Exception:
            pass


def _v92_wrap_fire_supervision_update(namespace):
    function_name = (
        "fire_update_fire_supervision_table"
    )

    original = namespace.get(
        function_name
    )

    if not callable(original):
        return

    if getattr(
        original,
        "_v92_fire_wrapper",
        False,
    ):
        return

    def wrapper(index=None, *args, **kwargs):
        result = original(
            index,
            *args,
            **kwargs
        )

        _v92_schedule(
            namespace,
            "fire-role-sync",
            50,
            lambda idx=index: (
                _v92_sync_fire_required_roles(
                    namespace,
                    idx,
                )
            ),
        )

        return result

    wrapper._v92_fire_wrapper = True
    wrapper.__name__ = function_name

    namespace[function_name] = wrapper


def _v92_bind_fire_project_dates(namespace):
    if namespace.get(
        "_v92_fire_dates_bound"
    ):
        return

    namespace[
        "_v92_fire_dates_bound"
    ] = True

    for collection_name in (
        "entry_elec_start_date",
        "entry_elec_end_date",
        "entry_start_date",
        "entry_end_date",
        "entry_area",
        "entry_ground_floors",
        "entry_basement_floors",
        "entry_total_cost",
    ):
        collection = namespace.get(
            collection_name,
            [],
        )

        if not isinstance(
            collection,
            (list, tuple),
        ):
            continue

        for index, widget in enumerate(
            collection[:4]
        ):
            if widget is None:
                continue

            def handler(
                event=None,
                project_index=index,
            ):
                _v92_schedule(
                    namespace,
                    f"fire-input:{project_index}",
                    120,
                    lambda idx=project_index: (
                        _v92_sync_fire_required_roles(
                            namespace,
                            idx,
                        )
                    ),
                )

            for event_name in (
                "<KeyRelease>",
                "<FocusOut>",
                "<<Paste>>",
            ):
                try:
                    widget.bind(
                        event_name,
                        handler,
                        add="+",
                    )
                except Exception:
                    pass


def _v92_install_fire_patch(namespace):
    trade_name = str(
        namespace.get(
            "_v90_trade_name",
            namespace.get(
                "current_supervision_type",
                "",
            ),
        )
    ).strip()

    if trade_name != "소방":
        return

    _v92_wrap_fire_supervision_update(
        namespace
    )

    _v92_bind_fire_project_dates(
        namespace
    )

    root = namespace.get("root")

    def initial_sync():
        _v92_sync_fire_required_roles(
            namespace
        )

    if root is not None:
        try:
            root.after_idle(initial_sync)
            root.after(400, initial_sync)
            root.after(1000, initial_sync)
        except Exception:
            initial_sync()
    else:
        initial_sync()


# ================================================================
# 최종본107 패치 설치
# ================================================================

def _v93_previous_v92_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    if trade_name in (
        "전기",
        "통신",
        "소방",
    ):
        namespace[
            "_v90_trade_name"
        ] = trade_name

    _v92_install_excel_merge_patch()

    _v92_bind_project4_name(
        namespace
    )

    _v92_install_fire_patch(
        namespace
    )

    if namespace.get(
        "_v92_runtime_patch_installed"
    ):
        return

    namespace[
        "_v92_runtime_patch_installed"
    ] = True

    root = namespace.get("root")

    def initial_update():
        _v92_project4_name_to_radio(
            namespace
        )

        _v92_sync_fire_required_roles(
            namespace
        )

    if root is not None:
        try:
            root.after_idle(initial_update)
            root.after(700, initial_update)
        except Exception:
            initial_update()
    else:
        initial_update()

# ================================================================
# 최종본107 - 산출조서 Excel 고정 양식 출력
# ================================================================

import re as _v93_re
from copy import copy as _v93_copy


def _v93_text(value):
    if value is None:
        return ""

    if isinstance(value, float):
        if value.is_integer():
            return str(int(value))

    return str(value).strip()


def _v93_normalized_text(value):
    return _v93_re.sub(
        r"\s+",
        " ",
        _v93_text(value).replace("\n", " "),
    ).strip()


def _v93_is_numbered_cost(text):
    return bool(
        _v93_re.match(
            r"^\s*\d+\s*[.]",
            _v93_normalized_text(text),
        )
    )


def _v93_is_amount(value):
    text = _v93_text(value)

    if not text:
        return False

    text = (
        text.replace(",", "")
        .replace("원", "")
        .replace("㎡", "")
        .replace("m²", "")
        .strip()
    )

    try:
        float(text)
        return True
    except Exception:
        return False


def _v93_extract_rows(ws):
    """
    기존 시트에서 보이는 값만 행 단위로 수집한다.
    MergedCell은 제외하고 실제 값이 있는 셀만 사용한다.
    """
    rows = []

    for row_number in range(
        1,
        ws.max_row + 1,
    ):
        values = []

        for column_number in range(
            1,
            ws.max_column + 1,
        ):
            cell = ws.cell(
                row=row_number,
                column=column_number,
            )

            if (
                cell.__class__.__name__
                == "MergedCell"
            ):
                continue

            value = cell.value
            text = _v93_text(value)

            if not text:
                continue

            values.append(
                {
                    "column": column_number,
                    "value": value,
                    "text": text,
                }
            )

        if values:
            rows.append(
                {
                    "source_row": row_number,
                    "values": values,
                    "texts": [
                        item["text"]
                        for item in values
                    ],
                }
            )

    return rows


def _v93_find_title(rows, sheet_name):
    for row in rows:
        joined = " ".join(row["texts"])

        if "감리용역비 산출조서" in joined:
            return _v93_normalized_text(joined)

    return f"감리용역비 산출조서 ({sheet_name})"


def _v93_find_metadata(rows):
    aliases = {
        "용역명": ("용역명",),
        "규모": ("규모",),
        "연면적": ("연면적",),
        "감리기간": ("감리기간",),
    }

    result = {
        "용역명": "",
        "규모": "",
        "연면적": "",
        "감리기간": "",
    }

    for row in rows:
        texts = row["texts"]

        if not texts:
            continue

        joined = " ".join(texts)

        for output_name, keywords in aliases.items():
            if not any(
                keyword in texts[0]
                for keyword in keywords
            ):
                continue

            if len(texts) >= 2:
                result[output_name] = (
                    " ".join(texts[1:])
                )
            else:
                # 한 셀에 "연면적 [값]" 형태로 들어간 경우
                value = joined

                for keyword in keywords:
                    value = value.replace(
                        keyword,
                        "",
                        1,
                    )

                result[output_name] = (
                    value.strip(" :")
                )

    return result


def _v93_find_header_index(rows):
    for index, row in enumerate(rows):
        joined = " ".join(row["texts"])

        if (
            "항목" in joined
            and "사업" in joined
            and (
                "감리원" in joined
                or "자격" in joined
            )
        ):
            return index

    return -1


def _v93_find_first_cost_index(rows):
    for index, row in enumerate(rows):
        if any(
            _v93_is_numbered_cost(text)
            for text in row["texts"]
        ):
            return index

    return -1


def _v93_find_note_index(rows):
    for index, row in enumerate(rows):
        joined = " ".join(row["texts"])

        if (
            "관련 근거" in joined
            or "관련근거" in joined
        ):
            return index

    return -1


def _v93_clean_personnel_rows(rows):
    """
    직접인건비 구역의 행을 정리한다.
    """
    header_index = _v93_find_header_index(
        rows
    )

    cost_index = _v93_find_first_cost_index(
        rows
    )

    if header_index < 0:
        return []

    if cost_index < 0:
        cost_index = len(rows)

    personnel = []

    for row in rows[
        header_index + 1:cost_index
    ]:
        texts = [
            _v93_normalized_text(text)
            for text in row["texts"]
            if _v93_normalized_text(text)
        ]

        if not texts:
            continue

        if (
            len(texts) == 1
            and "직접인건비" in texts[0]
        ):
            continue

        joined = " ".join(texts)

        role_exists = any(
            role in joined
            for role in (
                "상주",
                "비상주",
                "책임",
                "보조",
            )
        )

        grade_exists = any(
            grade in joined
            for grade in (
                "기술사",
                "특급",
                "고급",
                "중급",
                "초급",
            )
        )

        if role_exists or grade_exists:
            personnel.append(texts)

    return personnel


def _v93_clean_cost_rows(rows):
    first_cost_index = _v93_find_first_cost_index(
        rows
    )

    note_index = _v93_find_note_index(
        rows
    )

    if first_cost_index < 0:
        return []

    if note_index < 0:
        note_index = len(rows)

    result = []

    accepted_totals = (
        "산출금액",
        "소계",
        "부가가치세",
        "감리비 총계",
        "감리비총계",
    )

    for row in rows[
        first_cost_index:note_index
    ]:
        texts = [
            _v93_normalized_text(text)
            for text in row["texts"]
            if _v93_normalized_text(text)
        ]

        if not texts:
            continue

        first = texts[0]
        joined = " ".join(texts)

        if (
            _v93_is_numbered_cost(first)
            or any(
                keyword in joined
                for keyword in accepted_totals
            )
        ):
            result.append(texts)

    return result


def _v93_clean_note_rows(rows):
    note_index = _v93_find_note_index(
        rows
    )

    if note_index < 0:
        return []

    result = []

    for row in rows[note_index:]:
        texts = [
            _v93_normalized_text(text)
            for text in row["texts"]
            if _v93_normalized_text(text)
        ]

        if not texts:
            continue

        joined = " ".join(texts)

        # 잘게 분리된 글자를 한 줄로 합친다.
        joined = joined.replace(
            "관련 근 거",
            "관련 근거",
        )

        result.append(joined)

    return result


def _v93_get_border_styles():
    from openpyxl.styles import Border, Side

    thin = Side(
        style="thin",
        color="000000",
    )

    medium = Side(
        style="medium",
        color="000000",
    )

    thin_border = Border(
        left=thin,
        right=thin,
        top=thin,
        bottom=thin,
    )

    medium_border = Border(
        left=medium,
        right=medium,
        top=medium,
        bottom=medium,
    )

    return thin_border, medium_border


def _v93_apply_border(
    ws,
    min_row,
    min_col,
    max_row,
    max_col,
    border,
):
    for row in range(
        min_row,
        max_row + 1,
    ):
        for column in range(
            min_col,
            max_col + 1,
        ):
            ws.cell(
                row=row,
                column=column,
            ).border = _v93_copy(border)


def _v93_merge(
    ws,
    start_row,
    start_col,
    end_row,
    end_col,
    value=None,
):
    if (
        start_row != end_row
        or start_col != end_col
    ):
        ws.merge_cells(
            start_row=start_row,
            start_column=start_col,
            end_row=end_row,
            end_column=end_col,
        )

    cell = ws.cell(
        row=start_row,
        column=start_col,
    )

    if value is not None:
        cell.value = value

    return cell


def _v93_split_personnel_values(values):
    """
    직접인건비 인원행을 8개 데이터로 정리한다.

    반환:
        사업, 역할, 분야, 등급, 감리원수, 단가, 금액, 비고
    """
    cleaned = [
        _v93_normalized_text(value)
        for value in values
        if _v93_normalized_text(value)
    ]

    cleaned = [
        value
        for value in cleaned
        if value not in (
            "직접인건비",
            "항목",
            "사업",
            "감리원자격",
            "감리원 자격",
            "감리원수",
            "단가",
            "금액",
            "비고",
        )
    ]

    role_index = None
    grade_index = None

    for index, value in enumerate(cleaned):
        if any(
            word in value
            for word in (
                "상주",
                "비상주",
                "책임",
                "보조",
            )
        ):
            role_index = index
            break

    for index, value in enumerate(cleaned):
        if value in (
            "기술사",
            "특급",
            "고급",
            "중급",
            "초급",
        ):
            grade_index = index
            break

    project = ""
    role = ""
    field = ""
    grade = ""
    count = ""
    unit_price = ""
    amount = ""
    remark = ""

    if role_index is not None:
        role = cleaned[role_index]

        if role_index > 0:
            project = cleaned[role_index - 1]
    elif cleaned:
        project = cleaned[0]

    if grade_index is not None:
        grade = cleaned[grade_index]

        if grade_index > 0:
            candidate = cleaned[grade_index - 1]

            if candidate != role:
                field = candidate

    numeric_values = []

    start_numeric = (
        grade_index + 1
        if grade_index is not None
        else 0
    )

    for value in cleaned[start_numeric:]:
        if (
            _v93_is_amount(value)
            or value == "0"
        ):
            numeric_values.append(value)

    if len(numeric_values) >= 1:
        count = numeric_values[0]

    if len(numeric_values) >= 2:
        unit_price = numeric_values[1]

    if len(numeric_values) >= 3:
        amount = numeric_values[2]

    if not field:
        for value in cleaned:
            if value in (
                "전기",
                "통신",
                "소방",
            ):
                field = value
                break

    return (
        project,
        role,
        field,
        grade,
        count,
        unit_price,
        amount,
        remark,
    )


def _v93_split_cost_values(values):
    cleaned = [
        _v93_normalized_text(value)
        for value in values
        if _v93_normalized_text(value)
    ]

    if not cleaned:
        return "", "", ""

    description = cleaned[0]
    rate = ""
    amount = ""

    for value in cleaned[1:]:
        if (
            "%" in value
            or "적용" in value
            or "미만" in value
            or "이상" in value
        ):
            if not rate:
                rate = value

    for value in reversed(cleaned[1:]):
        if _v93_is_amount(value):
            amount = value
            break

    # 값이 2개이고 두 번째가 금액이면 요율 칸은 비운다.
    if (
        len(cleaned) == 2
        and _v93_is_amount(cleaned[1])
    ):
        amount = cleaned[1]

    return description, rate, amount


def _v93_rebuild_calculation_sheet(
    ws,
    sheet_name,
):
    """
    기존 픽셀 기반 시트를 값 중심의 고정 보고서 양식으로 재작성한다.
    """
    from openpyxl.styles import (
        Alignment,
        Font,
        PatternFill,
    )
    from openpyxl.worksheet.page import PageMargins

    rows = _v93_extract_rows(ws)

    if not rows:
        return ws

    title = _v93_find_title(
        rows,
        sheet_name,
    )

    metadata = _v93_find_metadata(rows)
    personnel_rows = _v93_clean_personnel_rows(
        rows
    )
    cost_rows = _v93_clean_cost_rows(rows)
    note_rows = _v93_clean_note_rows(rows)

    # 기존 병합 해제
    for merged_range in list(
        ws.merged_cells.ranges
    ):
        try:
            ws.unmerge_cells(
                str(merged_range)
            )
        except Exception:
            pass

    # 기존 행과 열을 제거
    if ws.max_row:
        ws.delete_rows(
            1,
            ws.max_row,
        )

    if ws.max_column:
        ws.delete_cols(
            1,
            ws.max_column,
        )

    thin_border, medium_border = (
        _v93_get_border_styles()
    )

    title_fill = PatternFill(
        fill_type="solid",
        fgColor="B4C6E7",
    )

    header_fill = PatternFill(
        fill_type="solid",
        fgColor="FFF2CC",
    )

    blue_fill = PatternFill(
        fill_type="solid",
        fgColor="B4C6E7",
    )

    total_fill = PatternFill(
        fill_type="solid",
        fgColor="EADCA6",
    )

    white_fill = PatternFill(
        fill_type="solid",
        fgColor="FFFFFF",
    )

    light_gray_fill = PatternFill(
        fill_type="solid",
        fgColor="F2F2F2",
    )

    center = Alignment(
        horizontal="center",
        vertical="center",
        wrap_text=True,
    )

    left = Alignment(
        horizontal="left",
        vertical="center",
        wrap_text=True,
    )

    right = Alignment(
        horizontal="right",
        vertical="center",
        wrap_text=True,
    )

    normal_font = Font(
        name="맑은 고딕",
        size=9,
    )

    bold_font = Font(
        name="맑은 고딕",
        size=9,
        bold=True,
    )

    title_font = Font(
        name="맑은 고딕",
        size=16,
        bold=True,
    )

    # ------------------------------------------------------------
    # 열 너비: 두 번째 사진 형태의 9개 논리 열
    # ------------------------------------------------------------
    column_widths = {
        "A": 16,
        "B": 9,
        "C": 17,
        "D": 15,
        "E": 15,
        "F": 13,
        "G": 16,
        "H": 18,
        "I": 18,
    }

    for column, width in column_widths.items():
        ws.column_dimensions[column].width = width

    current_row = 1

    # ------------------------------------------------------------
    # 제목
    # ------------------------------------------------------------
    title_cell = _v93_merge(
        ws,
        current_row,
        1,
        current_row,
        9,
        title,
    )

    title_cell.font = title_font
    title_cell.fill = title_fill
    title_cell.alignment = center

    _v93_apply_border(
        ws,
        current_row,
        1,
        current_row,
        9,
        medium_border,
    )

    ws.row_dimensions[
        current_row
    ].height = 30

    current_row += 2

    # ------------------------------------------------------------
    # 기본정보
    # ------------------------------------------------------------
    for label in (
        "용역명",
        "규모",
        "연면적",
        "감리기간",
    ):
        label_cell = ws.cell(
            row=current_row,
            column=1,
            value=label,
        )

        value_cell = _v93_merge(
            ws,
            current_row,
            2,
            current_row,
            9,
            metadata.get(label, ""),
        )

        label_cell.font = bold_font
        label_cell.alignment = center
        label_cell.fill = white_fill

        value_cell.font = normal_font
        value_cell.alignment = left
        value_cell.fill = white_fill

        _v93_apply_border(
            ws,
            current_row,
            1,
            current_row,
            9,
            thin_border,
        )

        ws.row_dimensions[
            current_row
        ].height = 21

        current_row += 1

    # ------------------------------------------------------------
    # 직접인건비 표 머리글
    # ------------------------------------------------------------
    headers = (
        ("항목", 1, 1),
        ("사업", 2, 2),
        ("감리원 자격", 3, 5),
        ("감리원수", 6, 6),
        ("단가", 7, 7),
        ("금액", 8, 8),
        ("비고", 9, 9),
    )

    for text, start_column, end_column in headers:
        cell = _v93_merge(
            ws,
            current_row,
            start_column,
            current_row,
            end_column,
            text,
        )

        cell.font = bold_font
        cell.fill = header_fill
        cell.alignment = center

    _v93_apply_border(
        ws,
        current_row,
        1,
        current_row,
        9,
        medium_border,
    )

    ws.row_dimensions[
        current_row
    ].height = 23

    current_row += 1

    personnel_start_row = current_row

    if not personnel_rows:
        personnel_rows = [[]]

    parsed_personnel = [
        _v93_split_personnel_values(row)
        for row in personnel_rows
    ]

    for (
        project,
        role,
        field,
        grade,
        count,
        unit_price,
        amount,
        remark,
    ) in parsed_personnel:
        values = (
            "",
            project,
            role,
            field,
            grade,
            count,
            unit_price,
            amount,
            remark,
        )

        for column, value in enumerate(
            values,
            start=1,
        ):
            cell = ws.cell(
                row=current_row,
                column=column,
                value=value,
            )

            cell.font = normal_font
            cell.fill = white_fill
            cell.alignment = (
                right
                if column in (6, 7, 8)
                else center
            )

        _v93_apply_border(
            ws,
            current_row,
            1,
            current_row,
            9,
            thin_border,
        )

        ws.row_dimensions[
            current_row
        ].height = 22

        current_row += 1

    personnel_end_row = current_row - 1

    direct_cell = _v93_merge(
        ws,
        personnel_start_row,
        1,
        personnel_end_row,
        1,
        "직접인건비",
    )

    direct_cell.font = bold_font
    direct_cell.alignment = center

    # 같은 사업명이 연속되는 경우 사업 열도 세로 병합
    merge_start = personnel_start_row

    while merge_start <= personnel_end_row:
        project_value = _v93_text(
            ws.cell(
                row=merge_start,
                column=2,
            ).value
        )

        merge_end = merge_start

        while merge_end + 1 <= personnel_end_row:
            next_value = _v93_text(
                ws.cell(
                    row=merge_end + 1,
                    column=2,
                ).value
            )

            if next_value != project_value:
                break

            merge_end += 1

        if (
            project_value
            and merge_end > merge_start
        ):
            _v93_merge(
                ws,
                merge_start,
                2,
                merge_end,
                2,
                project_value,
            )

        merge_start = merge_end + 1

    # ------------------------------------------------------------
    # 계산 내역
    # ------------------------------------------------------------
    current_row += 1

    if not cost_rows:
        cost_rows = [
            ["1. 직접인건비 계", "", "0"],
            ["2. 주제비(상주직접인건비의 30%)", "30% 적용", "0"],
            ["3. 출장여비(비상주직접인건비의 10%)", "10% 적용", "0"],
            ["4. 제경비(직접인건비의 110~120%)", "", "0"],
            ["5. 기술료((1+4)의 20~40%)", "", "0"],
            ["6. 손해배상보험", "", "0"],
            ["산출금액", "", "0"],
            ["[ 소계 ]", "", "0"],
            ["부가가치세", "10%", "0"],
            ["감리비 총계", "", "0"],
        ]

    for values in cost_rows:
        description, rate, amount = (
            _v93_split_cost_values(values)
        )

        is_total = any(
            keyword in description.replace(" ", "")
            for keyword in (
                "감리비총계",
                "산출금액",
            )
        )

        is_final_total = (
            "감리비총계"
            in description.replace(" ", "")
        )

        description_cell = _v93_merge(
            ws,
            current_row,
            1,
            current_row,
            3,
            description,
        )

        rate_cell = _v93_merge(
            ws,
            current_row,
            4,
            current_row,
            5,
            rate,
        )

        _v93_merge(
            ws,
            current_row,
            6,
            current_row,
            7,
            "",
        )

        amount_cell = _v93_merge(
            ws,
            current_row,
            8,
            current_row,
            9,
            amount,
        )

        row_fill = (
            total_fill
            if is_final_total
            else white_fill
        )

        for column in range(1, 10):
            cell = ws.cell(
                row=current_row,
                column=column,
            )

            cell.fill = row_fill
            cell.font = (
                bold_font
                if is_total or is_final_total
                else normal_font
            )

        description_cell.alignment = left
        rate_cell.alignment = left
        amount_cell.alignment = right

        _v93_apply_border(
            ws,
            current_row,
            1,
            current_row,
            9,
            medium_border,
        )

        ws.row_dimensions[
            current_row
        ].height = 27

        current_row += 1

    # ------------------------------------------------------------
    # 관련 근거 및 기준
    # ------------------------------------------------------------
    current_row += 2

    if not note_rows:
        note_rows = [
            "관련 근거 및 기준",
            "• 관련근거 : 전력기술관리법 제12조 제1항",
            "• 노임단가기준 : 한국엔지니어링협회 적용 엔지니어링 실적공사 노임단가",
            "구분",
            "• 감리원수 산출기준 : 사업 공사비·규모·난이도·공사기간에 따른 필요 감리원 투입기준 적용",
        ]

    heading_written = False

    for note in note_rows:
        normalized = _v93_normalized_text(
            note
        )

        if not normalized:
            continue

        is_main_heading = (
            "관련 근거" in normalized
            or "관련근거" in normalized
        ) and not normalized.startswith(
            ("•", "·", "-")
        )

        is_sub_heading = (
            normalized == "구분"
        )

        if is_main_heading:
            if heading_written:
                continue

            heading_written = True

            cell = _v93_merge(
                ws,
                current_row,
                1,
                current_row,
                9,
                "관련 근거 및 기준",
            )

            cell.font = bold_font
            cell.fill = light_gray_fill
            cell.alignment = left

            ws.row_dimensions[
                current_row
            ].height = 23

            current_row += 1
            continue

        if is_sub_heading:
            cell = _v93_merge(
                ws,
                current_row,
                1,
                current_row,
                9,
                "구분",
            )

            cell.font = bold_font
            cell.fill = light_gray_fill
            cell.alignment = left

            ws.row_dimensions[
                current_row
            ].height = 23

            current_row += 1
            continue

        cell = _v93_merge(
            ws,
            current_row,
            1,
            current_row,
            9,
            normalized,
        )

        cell.font = normal_font
        cell.fill = white_fill
        cell.alignment = left

        _v93_apply_border(
            ws,
            current_row,
            1,
            current_row,
            9,
            thin_border,
        )

        line_count = max(
            1,
            len(normalized) // 90 + 1,
        )

        ws.row_dimensions[
            current_row
        ].height = max(
            23,
            18 * line_count,
        )

        current_row += 1

    # 제목이 없었던 경우라도 관련 근거 제목 추가
    if not heading_written:
        insert_row = current_row

        cell = _v93_merge(
            ws,
            insert_row,
            1,
            insert_row,
            9,
            "관련 근거 및 기준",
        )

        cell.font = bold_font
        cell.fill = light_gray_fill
        cell.alignment = left

    # ------------------------------------------------------------
    # 전체 서식
    # ------------------------------------------------------------
    for row in ws.iter_rows(
        min_row=1,
        max_row=ws.max_row,
        min_col=1,
        max_col=9,
    ):
        for cell in row:
            if cell.__class__.__name__ == "MergedCell":
                continue

            if cell.font is None:
                cell.font = normal_font

            if cell.alignment is None:
                cell.alignment = center

    ws.sheet_view.showGridLines = False
    ws.freeze_panes = None

    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0

    ws.sheet_properties.pageSetUpPr.fitToPage = True

    ws.page_margins = PageMargins(
        left=0.2,
        right=0.2,
        top=0.3,
        bottom=0.3,
        header=0.1,
        footer=0.1,
    )

    ws.print_area = (
        f"A1:I{ws.max_row}"
    )

    ws.sheet_view.zoomScale = 85
    ws.sheet_view.zoomScaleNormal = 85

    return ws


def _v93_is_calculation_sheet(sheet_name):
    normalized = str(
        sheet_name or ""
    ).replace(" ", "")

    if "기본입력" in normalized:
        return False

    if "산출조서" in normalized:
        return True

    return normalized in (
        "개별(정상요율)",
        "통합(정상요율)",
        "통합(조정요율)",
    )


def _v93_install_clean_excel_export():
    if globals().get(
        "_v93_clean_excel_installed"
    ):
        return

    original = globals().get(
        "_v71_write_widget_sheet"
    )

    if not callable(original):
        return

    if getattr(
        original,
        "_v93_clean_excel_wrapper",
        False,
    ):
        globals()[
            "_v93_clean_excel_installed"
        ] = True
        return

    globals()[
        "_v93_previous_write_widget_sheet"
    ] = original

    def wrapper(
        workbook,
        sheet_name,
        root_widget,
        excluded_roots=None,
    ):
        ws = original(
            workbook,
            sheet_name,
            root_widget,
            excluded_roots=excluded_roots,
        )

        if _v93_is_calculation_sheet(
            sheet_name
        ):
            try:
                _v93_rebuild_calculation_sheet(
                    ws,
                    sheet_name,
                )
            except Exception:
                # 산출조서 재작성 실패 시 기존 시트를 그대로 유지한다.
                pass

        return ws

    wrapper._v93_clean_excel_wrapper = True
    wrapper.__name__ = "_v71_write_widget_sheet"

    globals()[
        "_v71_write_widget_sheet"
    ] = wrapper

    globals()[
        "_v93_clean_excel_installed"
    ] = True


def _v94_previous_v93_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    _v93_install_clean_excel_export()

    namespace[
        "_v93_runtime_patch_installed"
    ] = True

# ================================================================
# 최종본107
#
# 1. Excel 내려받기 진행률 창
# 2. 규모 = 사업명[연면적]+사업명[연면적]=[총 연면적]
# 3. 감리원수 산출기준 중복 제거
# ================================================================

import re as _v94_re
import time as _v94_time


# ----------------------------------------------------------------
# 공통 함수
# ----------------------------------------------------------------

def _v94_widget_value(widget):
    if widget is None:
        return ""

    try:
        return str(widget.get()).strip()
    except Exception:
        return ""


def _v94_number(value):
    text = str(value or "").strip()

    text = (
        text.replace(",", "")
        .replace("㎡", "")
        .replace("m²", "")
        .replace("m2", "")
        .replace("M²", "")
        .replace("M2", "")
        .strip()
    )

    if not text:
        return 0

    try:
        return int(float(text))
    except Exception:
        return 0


def _v94_format_area(value):
    number = _v94_number(value)

    if not number:
        return "0㎡"

    return f"{number:,}㎡"


# ================================================================
# 규모 문구 생성
# ================================================================

def _v94_build_scale_text(namespace):
    """
    예:
        인문대[2,331㎡]+자연대[10,000㎡]=[12,331㎡]
    """
    name_entries = namespace.get(
        "entry_names",
        [],
    )

    area_entries = namespace.get(
        "entry_area",
        [],
    )

    parts = []
    total_area = 0

    for index in range(3):
        try:
            project_name = _v94_widget_value(
                name_entries[index]
            )
        except Exception:
            project_name = ""

        try:
            area_text = _v94_widget_value(
                area_entries[index]
            )
        except Exception:
            area_text = ""

        area = _v94_number(area_text)

        # 사업명이 없는 행은 규모에 포함하지 않는다.
        if not project_name:
            continue

        parts.append(
            f"{project_name}[{area:,}㎡]"
        )

        total_area += area

    if not parts:
        return ""

    return (
        "+".join(parts)
        + f"=[{total_area:,}㎡]"
    )


# ================================================================
# 산출조서 시트 규모 및 중복 문구 보정
# ================================================================

def _v94_is_calculation_sheet(sheet_name):
    normalized = str(
        sheet_name or ""
    ).replace(" ", "")

    if "기본입력" in normalized:
        return False

    if "산출조서" in normalized:
        return True

    return normalized in (
        "개별(정상요율)",
        "통합(정상요율)",
        "통합(조정요율)",
    )


def _v94_find_row_by_label(
    ws,
    label_text,
):
    normalized_label = str(
        label_text
    ).replace(" ", "")

    for row in range(
        1,
        ws.max_row + 1,
    ):
        for column in range(
            1,
            min(ws.max_column, 9) + 1,
        ):
            cell = ws.cell(
                row=row,
                column=column,
            )

            if (
                cell.__class__.__name__
                == "MergedCell"
            ):
                continue

            text = str(
                cell.value or ""
            ).replace(" ", "").strip()

            if text == normalized_label:
                return row

    return None


def _v94_unmerge_intersecting(
    ws,
    target_row,
    start_column,
    end_column,
):
    for merged_range in list(
        ws.merged_cells.ranges
    ):
        intersects = not (
            merged_range.max_row < target_row
            or merged_range.min_row > target_row
            or merged_range.max_col < start_column
            or merged_range.min_col > end_column
        )

        if not intersects:
            continue

        try:
            ws.unmerge_cells(
                str(merged_range)
            )
        except Exception:
            pass


def _v94_write_scale_row(
    ws,
    namespace,
):
    from copy import copy
    from openpyxl.styles import Alignment

    scale_row = _v94_find_row_by_label(
        ws,
        "규모",
    )

    if scale_row is None:
        return False

    scale_text = _v94_build_scale_text(
        namespace
    )

    if not scale_text:
        return False

    source_cell = ws.cell(
        row=scale_row,
        column=2,
    )

    try:
        source_font = copy(source_cell.font)
        source_fill = copy(source_cell.fill)
        source_border = copy(source_cell.border)
        source_protection = copy(
            source_cell.protection
        )
        source_format = source_cell.number_format
    except Exception:
        source_font = None
        source_fill = None
        source_border = None
        source_protection = None
        source_format = None

    _v94_unmerge_intersecting(
        ws,
        scale_row,
        2,
        9,
    )

    for column in range(2, 10):
        cell = ws.cell(
            row=scale_row,
            column=column,
        )

        try:
            cell.value = None
        except Exception:
            pass

    ws.merge_cells(
        start_row=scale_row,
        start_column=2,
        end_row=scale_row,
        end_column=9,
    )

    target_cell = ws.cell(
        row=scale_row,
        column=2,
    )

    target_cell.value = scale_text

    if source_font is not None:
        target_cell.font = source_font

    if source_fill is not None:
        target_cell.fill = source_fill

    if source_border is not None:
        target_cell.border = source_border

    if source_protection is not None:
        target_cell.protection = (
            source_protection
        )

    if source_format is not None:
        target_cell.number_format = (
            source_format
        )

    target_cell.alignment = Alignment(
        horizontal="left",
        vertical="center",
        wrap_text=True,
        shrink_to_fit=True,
    )

    try:
        ws.row_dimensions[
            scale_row
        ].height = max(
            ws.row_dimensions[
                scale_row
            ].height or 20,
            23,
        )
    except Exception:
        pass

    return True


def _v94_find_criteria_cells(ws):
    result = []

    for row in range(
        1,
        ws.max_row + 1,
    ):
        for column in range(
            1,
            ws.max_column + 1,
        ):
            cell = ws.cell(
                row=row,
                column=column,
            )

            if (
                cell.__class__.__name__
                == "MergedCell"
            ):
                continue

            text = str(
                cell.value or ""
            ).replace("\n", " ").strip()

            normalized = (
                text.replace(" ", "")
                .replace("·", "")
                .replace("•", "")
            )

            if "감리원수산출기준" in normalized:
                result.append(
                    (
                        row,
                        column,
                        cell,
                    )
                )

    return result


def _v94_remove_duplicate_criteria(ws):
    """
    감리원수 산출기준은 가장 아래쪽 문구 하나만 남긴다.
    """
    matches = _v94_find_criteria_cells(
        ws
    )

    if len(matches) <= 1:
        return 0

    # 가장 아래에 있는 문구를 유지한다.
    keep_row, keep_column, keep_cell = max(
        matches,
        key=lambda item: (
            item[0],
            item[1],
        ),
    )

    removed = 0

    for row, column, cell in matches:
        if (
            row == keep_row
            and column == keep_column
        ):
            continue

        try:
            cell.value = None
            removed += 1
        except Exception:
            pass

    return removed


def _v94_fix_calculation_sheet(
    ws,
    sheet_name,
    namespace,
):
    if not _v94_is_calculation_sheet(
        sheet_name
    ):
        return ws

    _v94_write_scale_row(
        ws,
        namespace,
    )

    _v94_remove_duplicate_criteria(
        ws
    )

    try:
        ws.sheet_view.showGridLines = False
    except Exception:
        pass

    return ws


# ================================================================
# Excel 진행률 창
# ================================================================

def _v94_center_window(
    window,
    parent,
    width=430,
    height=165,
):
    try:
        parent.update_idletasks()

        parent_x = parent.winfo_rootx()
        parent_y = parent.winfo_rooty()
        parent_width = parent.winfo_width()
        parent_height = parent.winfo_height()

        x = parent_x + max(
            0,
            (parent_width - width) // 2,
        )

        y = parent_y + max(
            0,
            (parent_height - height) // 2,
        )

        window.geometry(
            f"{width}x{height}+{x}+{y}"
        )

    except Exception:
        window.geometry(
            f"{width}x{height}"
        )


def _v94_create_progress_dialog(
    namespace,
):
    import tkinter as tk
    from tkinter import ttk

    root = namespace.get("root")

    if root is None:
        return None

    dialog = tk.Toplevel(root)

    dialog.title(
        "Excel 산출조서 생성 중"
    )

    dialog.resizable(
        False,
        False,
    )

    dialog.transient(root)

    dialog.protocol(
        "WM_DELETE_WINDOW",
        lambda: None,
    )

    dialog.configure(
        bg="#f3f5f8",
    )

    _v94_center_window(
        dialog,
        root,
    )

    container = tk.Frame(
        dialog,
        bg="#f3f5f8",
        padx=24,
        pady=20,
    )

    container.pack(
        fill="both",
        expand=True,
    )

    title_label = tk.Label(
        container,
        text="Excel 산출조서를 생성하고 있습니다.",
        font=(
            "맑은 고딕",
            11,
            "bold",
        ),
        bg="#f3f5f8",
        fg="#202020",
        anchor="w",
    )

    title_label.pack(
        fill="x",
        pady=(0, 8),
    )

    status_variable = tk.StringVar(
        value="산출 데이터를 준비하고 있습니다."
    )

    status_label = tk.Label(
        container,
        textvariable=status_variable,
        font=(
            "맑은 고딕",
            9,
        ),
        bg="#f3f5f8",
        fg="#555555",
        anchor="w",
    )

    status_label.pack(
        fill="x",
        pady=(0, 10),
    )

    style_name = (
        "V94.Horizontal.TProgressbar"
    )

    try:
        style = ttk.Style(dialog)

        style.configure(
            style_name,
            thickness=20,
            background="#4a78c2",
            troughcolor="#d9dfe8",
        )
    except Exception:
        pass

    progress_variable = tk.DoubleVar(
        value=0
    )

    progress_bar = ttk.Progressbar(
        container,
        orient="horizontal",
        mode="determinate",
        maximum=100,
        variable=progress_variable,
        style=style_name,
    )

    progress_bar.pack(
        fill="x",
    )

    percent_variable = tk.StringVar(
        value="0%"
    )

    percent_label = tk.Label(
        container,
        textvariable=percent_variable,
        font=(
            "맑은 고딕",
            10,
            "bold",
        ),
        bg="#f3f5f8",
        fg="#2455a4",
        anchor="e",
    )

    percent_label.pack(
        fill="x",
        pady=(5, 0),
    )

    state = {
        "dialog": dialog,
        "progress": progress_variable,
        "percent": percent_variable,
        "status": status_variable,
        "value": 0,
        "namespace": namespace,
    }

    globals()[
        "_v94_progress_state"
    ] = state

    try:
        dialog.grab_set()
    except Exception:
        pass

    try:
        dialog.lift()
        dialog.focus_force()
        dialog.update_idletasks()
        dialog.update()
    except Exception:
        pass

    return state


def _v94_progress_update(
    value,
    status=None,
):
    state = globals().get(
        "_v94_progress_state"
    )

    if not isinstance(state, dict):
        return

    dialog = state.get("dialog")

    if dialog is None:
        return

    try:
        if not dialog.winfo_exists():
            return
    except Exception:
        return

    value = max(
        0,
        min(100, int(value)),
    )

    state["value"] = value

    try:
        state["progress"].set(value)
        state["percent"].set(
            f"{value}%"
        )

        if status:
            state["status"].set(status)

        dialog.update_idletasks()
        dialog.update()
    except Exception:
        pass


def _v94_progress_step(
    status=None,
):
    state = globals().get(
        "_v94_progress_state"
    )

    if not isinstance(state, dict):
        return

    total = max(
        1,
        int(state.get("total", 1)),
    )

    completed = (
        int(state.get("completed", 0))
        + 1
    )

    state["completed"] = completed

    # 시트 출력 단계는 15~88% 사용
    value = 15 + int(
        73 * min(completed, total) / total
    )

    _v94_progress_update(
        value,
        status,
    )


def _v94_destroy_progress():
    state = globals().pop(
        "_v94_progress_state",
        None,
    )

    if not isinstance(state, dict):
        return

    dialog = state.get("dialog")

    if dialog is None:
        return

    try:
        dialog.grab_release()
    except Exception:
        pass

    try:
        dialog.destroy()
    except Exception:
        pass


# ================================================================
# Excel 저장 함수 연결
# ================================================================

def _v94_install_excel_enhancements(
    namespace,
):
    globals()[
        "_v94_current_export_namespace"
    ] = namespace

    # ------------------------------------------------------------
    # 시트 출력 함수
    # ------------------------------------------------------------
    write_original = globals().get(
        "_v71_write_widget_sheet"
    )

    if (
        callable(write_original)
        and not getattr(
            write_original,
            "_v94_write_wrapper",
            False,
        )
    ):
        globals()[
            "_v94_previous_write_widget_sheet"
        ] = write_original

        def write_wrapper(
            workbook,
            sheet_name,
            root_widget,
            excluded_roots=None,
        ):
            current_namespace = globals().get(
                "_v94_current_export_namespace",
                namespace,
            )

            state = globals().get(
                "_v94_progress_state"
            )

            if isinstance(state, dict):
                next_number = (
                    int(
                        state.get(
                            "completed",
                            0,
                        )
                    )
                    + 1
                )

                total = max(
                    1,
                    int(
                        state.get(
                            "total",
                            1,
                        )
                    ),
                )

                _v94_progress_update(
                    15
                    + int(
                        73
                        * min(
                            next_number - 1,
                            total,
                        )
                        / total
                    ),
                    f"{sheet_name} 시트를 작성하고 있습니다.",
                )

            ws = (
                _v94_previous_write_widget_sheet(
                    workbook,
                    sheet_name,
                    root_widget,
                    excluded_roots=excluded_roots,
                )
            )

            _v94_fix_calculation_sheet(
                ws,
                sheet_name,
                current_namespace,
            )

            _v94_progress_step(
                f"{sheet_name} 시트 작성 완료"
            )

            return ws

        write_wrapper._v94_write_wrapper = True
        write_wrapper.__name__ = (
            "_v71_write_widget_sheet"
        )

        globals()[
            "_v71_write_widget_sheet"
        ] = write_wrapper

    # ------------------------------------------------------------
    # 전체 Excel 내보내기 함수
    # ------------------------------------------------------------
    export_original = globals().get(
        "_v71_export_screen_excel"
    )

    if (
        callable(export_original)
        and not getattr(
            export_original,
            "_v94_export_wrapper",
            False,
        )
    ):
        globals()[
            "_v94_previous_export_screen_excel"
        ] = export_original

        def export_wrapper(
            export_namespace,
            trade_name,
        ):
            import tkinter.filedialog as _v94_filedialog
            import tkinter.messagebox as _v94_messagebox

            globals()[
                "_v94_current_export_namespace"
            ] = export_namespace

            original_save_dialog = (
                _v94_filedialog.asksaveasfilename
            )

            original_showinfo = (
                _v94_messagebox.showinfo
            )

            progress_created = {
                "value": False
            }

            def save_dialog_proxy(
                *args,
                **kwargs
            ):
                file_path = (
                    original_save_dialog(
                        *args,
                        **kwargs
                    )
                )

                if not file_path:
                    return file_path

                state = (
                    _v94_create_progress_dialog(
                        export_namespace
                    )
                )

                if isinstance(state, dict):
                    sheet_frames = (
                        export_namespace.get(
                            "sheet_frames",
                            {},
                        )
                    )

                    if isinstance(
                        sheet_frames,
                        dict,
                    ):
                        sheet_count = len(
                            sheet_frames
                        )
                    else:
                        sheet_count = 1

                    # 기본입력사항 및 추가 표를 고려한 여유 단계
                    state["total"] = max(
                        1,
                        sheet_count + 2,
                    )

                    state["completed"] = 0

                    progress_created[
                        "value"
                    ] = True

                    _v94_progress_update(
                        5,
                        "입력값과 계산 결과를 확인하고 있습니다.",
                    )

                return file_path

            def showinfo_proxy(
                title,
                message,
                *args,
                **kwargs
            ):
                title_text = str(title or "")

                if (
                    "엑셀" in title_text
                    or "Excel" in title_text
                ):
                    _v94_progress_update(
                        94,
                        "Excel 파일을 저장하고 있습니다.",
                    )

                    try:
                        dialog = globals().get(
                            "_v94_progress_state",
                            {},
                        ).get("dialog")

                        if dialog is not None:
                            dialog.after(80)
                            dialog.update()
                    except Exception:
                        pass

                    _v94_progress_update(
                        100,
                        "Excel 산출조서 생성이 완료되었습니다.",
                    )

                    try:
                        dialog = globals().get(
                            "_v94_progress_state",
                            {},
                        ).get("dialog")

                        if dialog is not None:
                            dialog.after(250)
                            dialog.update()
                    except Exception:
                        pass

                    _v94_destroy_progress()

                return original_showinfo(
                    title,
                    message,
                    *args,
                    **kwargs
                )

            _v94_filedialog.asksaveasfilename = (
                save_dialog_proxy
            )

            _v94_messagebox.showinfo = (
                showinfo_proxy
            )

            try:
                return (
                    _v94_previous_export_screen_excel(
                        export_namespace,
                        trade_name,
                    )
                )

            except Exception:
                _v94_destroy_progress()
                raise

            finally:
                _v94_filedialog.asksaveasfilename = (
                    original_save_dialog
                )

                _v94_messagebox.showinfo = (
                    original_showinfo
                )

                if progress_created["value"]:
                    _v94_destroy_progress()

        export_wrapper._v94_export_wrapper = True
        export_wrapper.__name__ = (
            "_v71_export_screen_excel"
        )

        globals()[
            "_v71_export_screen_excel"
        ] = export_wrapper


def _v95_previous_v94_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    globals()[
        "_v94_current_export_namespace"
    ] = namespace

    _v94_install_excel_enhancements(
        namespace
    )

    namespace[
        "_v94_runtime_patch_installed"
    ] = True

# ================================================================
# 최종본107
#
# 일반 사용자/관리자 로그인 모드 분리
#
# user:
#   개선사항 제출 버튼 표시
#
# admin:
#   코드 보기 버튼 표시
#   현재 실행 중인 전체 PY 코드 열람 및 복사
# ================================================================


def _v95_walk_widgets(widget):
    yield widget

    try:
        children = widget.winfo_children()
    except Exception:
        children = []

    for child in children:
        yield from _v95_walk_widgets(child)


def _v95_widget_text(widget):
    try:
        return str(widget.cget("text")).strip()
    except Exception:
        return ""


def _v95_entry_value(widget):
    if widget is None:
        return ""

    try:
        return str(widget.get()).strip()
    except Exception:
        return ""


def _v95_current_mode():
    mode = str(
        globals().get(
            "current_login_mode",
            "",
        )
    ).strip().lower()

    if mode in (
        "admin",
        "administrator",
        "관리자",
    ):
        return "admin"

    return "user"


def _v95_set_current_mode(mode):
    global current_login_mode

    normalized = str(
        mode or ""
    ).strip().lower()

    if normalized in (
        "admin",
        "administrator",
        "관리자",
    ):
        current_login_mode = "admin"
    else:
        current_login_mode = "user"

    for namespace in list(
        globals().get(
            "trade_instances",
            {},
        ).values()
    ):
        if not isinstance(namespace, dict):
            continue

        namespace[
            "current_login_mode"
        ] = current_login_mode

        namespace[
            "_v95_login_mode"
        ] = current_login_mode

        try:
            _v95_apply_mode_buttons(
                namespace
            )
        except Exception:
            pass


# ================================================================
# 현재 PY 전체 코드 읽기
# ================================================================

def _v95_source_path():
    candidates = []

    try:
        candidates.append(
            os.path.abspath(__file__)
        )
    except Exception:
        pass

    try:
        candidates.append(
            os.path.abspath(sys.argv[0])
        )
    except Exception:
        pass

    for path in candidates:
        if not path:
            continue

        try:
            if (
                os.path.isfile(path)
                and path.lower().endswith(".py")
            ):
                return path
        except Exception:
            pass

    return None


def _v95_read_current_source():
    source_path = _v95_source_path()

    if source_path is None:
        return (
            None,
            "현재 실행 중인 PY 파일의 경로를 "
            "확인하지 못했습니다.\n\n"
            "EXE로 패키징된 프로그램에서는 원본 PY 파일이 "
            "실행 파일과 같은 폴더에 있어야 전체 코드를 "
            "표시할 수 있습니다."
        )

    try:
        raw = open(
            source_path,
            "rb",
        ).read()
    except Exception as error:
        return (
            source_path,
            "소스 파일을 읽지 못했습니다.\n\n"
            f"{error}"
        )

    for encoding in (
        "utf-8-sig",
        "utf-8",
        "cp949",
    ):
        try:
            return (
                source_path,
                raw.decode(encoding),
            )
        except UnicodeDecodeError:
            pass

    return (
        source_path,
        raw.decode(
            "utf-8",
            errors="replace",
        ),
    )


# ================================================================
# 관리자 코드 보기 창
# ================================================================

def _v95_center_code_window(
    window,
    parent,
    width=1100,
    height=760,
):
    try:
        parent.update_idletasks()

        screen_width = (
            parent.winfo_screenwidth()
        )

        screen_height = (
            parent.winfo_screenheight()
        )

        x = max(
            0,
            (screen_width - width) // 2,
        )

        y = max(
            0,
            (screen_height - height) // 2,
        )

        window.geometry(
            f"{width}x{height}+{x}+{y}"
        )

    except Exception:
        window.geometry(
            f"{width}x{height}"
        )


def _v95_open_code_window(namespace):
    import tkinter as tk
    from tkinter import messagebox, ttk

    mode = str(
        namespace.get(
            "_v95_login_mode",
            namespace.get(
                "current_login_mode",
                _v95_current_mode(),
            ),
        )
    ).strip().lower()

    if mode != "admin":
        messagebox.showwarning(
            "권한 없음",
            "코드 보기는 관리자 모드에서만 사용할 수 있습니다.",
        )
        return

    root = namespace.get("root")

    if root is None:
        root = globals().get(
            "master_root"
        )

    if root is None:
        return

    existing_window = namespace.get(
        "_v95_code_window"
    )

    if existing_window is not None:
        try:
            if existing_window.winfo_exists():
                existing_window.deiconify()
                existing_window.lift()
                existing_window.focus_force()
                return
        except Exception:
            pass

    source_path, source_code = (
        _v95_read_current_source()
    )

    window = tk.Toplevel(root)

    namespace[
        "_v95_code_window"
    ] = window

    window.title(
        "관리자 모드 - 현재 PY 전체 코드"
    )

    window.configure(
        bg="#f3f5f8"
    )

    window.minsize(
        760,
        520,
    )

    _v95_center_code_window(
        window,
        root,
    )

    # ------------------------------------------------------------
    # 상단 정보
    # ------------------------------------------------------------
    top_frame = tk.Frame(
        window,
        bg="#d9e6f5",
        padx=15,
        pady=12,
    )

    top_frame.pack(
        fill="x",
    )

    tk.Label(
        top_frame,
        text="현재 실행 중인 PY 전체 코드",
        font=(
            "맑은 고딕",
            14,
            "bold",
        ),
        bg="#d9e6f5",
        fg="#17365d",
        anchor="w",
    ).pack(
        fill="x",
    )

    path_text = (
        source_path
        if source_path
        else "원본 PY 경로 확인 불가"
    )

    tk.Label(
        top_frame,
        text=path_text,
        font=(
            "맑은 고딕",
            9,
        ),
        bg="#d9e6f5",
        fg="#555555",
        anchor="w",
    ).pack(
        fill="x",
        pady=(4, 0),
    )

    # ------------------------------------------------------------
    # 코드 표시 영역
    # ------------------------------------------------------------
    code_frame = tk.Frame(
        window,
        bg="white",
    )

    code_frame.pack(
        fill="both",
        expand=True,
        padx=12,
        pady=(12, 5),
    )

    code_text = tk.Text(
        code_frame,
        wrap="none",
        undo=False,
        bg="#ffffff",
        fg="#111111",
        insertbackground="#111111",
        selectbackground="#b4c7e7",
        selectforeground="#000000",
        font=(
            "Consolas",
            10,
        ),
        relief="solid",
        bd=1,
        padx=8,
        pady=8,
    )

    vertical_scrollbar = ttk.Scrollbar(
        code_frame,
        orient="vertical",
        command=code_text.yview,
    )

    horizontal_scrollbar = ttk.Scrollbar(
        code_frame,
        orient="horizontal",
        command=code_text.xview,
    )

    code_text.configure(
        yscrollcommand=vertical_scrollbar.set,
        xscrollcommand=horizontal_scrollbar.set,
    )

    code_text.grid(
        row=0,
        column=0,
        sticky="nsew",
    )

    vertical_scrollbar.grid(
        row=0,
        column=1,
        sticky="ns",
    )

    horizontal_scrollbar.grid(
        row=1,
        column=0,
        sticky="ew",
    )

    code_frame.grid_rowconfigure(
        0,
        weight=1,
    )

    code_frame.grid_columnconfigure(
        0,
        weight=1,
    )

    code_text.insert(
        "1.0",
        source_code,
    )

    code_text.configure(
        state="disabled"
    )

    # ------------------------------------------------------------
    # 하단 버튼 및 검색
    # ------------------------------------------------------------
    bottom_frame = tk.Frame(
        window,
        bg="#f3f5f8",
        padx=12,
        pady=10,
    )

    bottom_frame.pack(
        fill="x",
    )

    search_frame = tk.Frame(
        bottom_frame,
        bg="#f3f5f8",
    )

    search_frame.pack(
        side="left",
        fill="x",
        expand=True,
    )

    tk.Label(
        search_frame,
        text="찾기:",
        font=(
            "맑은 고딕",
            9,
            "bold",
        ),
        bg="#f3f5f8",
    ).pack(
        side="left",
    )

    search_entry = tk.Entry(
        search_frame,
        width=30,
        font=(
            "맑은 고딕",
            10,
        ),
        relief="solid",
        bd=1,
    )

    search_entry.pack(
        side="left",
        padx=(5, 5),
        ipady=3,
    )

    status_variable = tk.StringVar(
        value=(
            f"총 {len(source_code):,}자"
        )
    )

    status_label = tk.Label(
        search_frame,
        textvariable=status_variable,
        font=(
            "맑은 고딕",
            9,
        ),
        bg="#f3f5f8",
        fg="#555555",
    )

    status_label.pack(
        side="left",
        padx=8,
    )

    def find_next(event=None):
        keyword = search_entry.get()

        code_text.tag_remove(
            "v95_search",
            "1.0",
            "end",
        )

        if not keyword:
            status_variable.set(
                f"총 {len(source_code):,}자"
            )
            return

        start_index = code_text.index(
            "insert"
        )

        position = code_text.search(
            keyword,
            start_index,
            stopindex="end",
            nocase=True,
        )

        if not position:
            position = code_text.search(
                keyword,
                "1.0",
                stopindex=start_index,
                nocase=True,
            )

        if not position:
            status_variable.set(
                "검색 결과 없음"
            )
            return

        end_index = (
            f"{position}+{len(keyword)}c"
        )

        code_text.configure(
            state="normal"
        )

        code_text.tag_add(
            "v95_search",
            position,
            end_index,
        )

        code_text.tag_config(
            "v95_search",
            background="#fff2cc",
            foreground="#000000",
        )

        code_text.mark_set(
            "insert",
            end_index,
        )

        code_text.see(position)

        code_text.configure(
            state="disabled"
        )

        status_variable.set(
            f"찾음: {keyword}"
        )

    def copy_all_code():
        try:
            window.clipboard_clear()
            window.clipboard_append(
                source_code
            )

            # 창이 닫힌 후에도 클립보드가 유지되도록 갱신
            window.update()

            status_variable.set(
                "전체 코드를 클립보드에 복사했습니다."
            )

        except Exception as error:
            messagebox.showerror(
                "복사 실패",
                "코드를 복사하지 못했습니다.\n\n"
                f"{error}",
                parent=window,
            )

    tk.Button(
        search_frame,
        text="다음 찾기",
        command=find_next,
        font=(
            "맑은 고딕",
            9,
            "bold",
        ),
        bg="#d9e1f2",
        relief="flat",
        cursor="hand2",
        padx=12,
        pady=5,
    ).pack(
        side="left",
        padx=3,
    )

    button_frame = tk.Frame(
        bottom_frame,
        bg="#f3f5f8",
    )

    button_frame.pack(
        side="right",
    )

    tk.Button(
        button_frame,
        text="전체 코드 복사하기",
        command=copy_all_code,
        font=(
            "맑은 고딕",
            10,
            "bold",
        ),
        bg="#00529b",
        fg="white",
        activebackground="#003f76",
        activeforeground="white",
        relief="flat",
        cursor="hand2",
        padx=15,
        pady=7,
    ).pack(
        side="left",
        padx=5,
    )

    tk.Button(
        button_frame,
        text="창 닫기",
        command=window.destroy,
        font=(
            "맑은 고딕",
            10,
            "bold",
        ),
        bg="#777777",
        fg="white",
        activebackground="#555555",
        activeforeground="white",
        relief="flat",
        cursor="hand2",
        padx=15,
        pady=7,
    ).pack(
        side="left",
        padx=5,
    )

    search_entry.bind(
        "<Return>",
        find_next,
    )

    window.bind(
        "<Control-f>",
        lambda event: (
            search_entry.focus_set(),
            search_entry.select_range(
                0,
                "end",
            ),
        ),
    )

    window.bind(
        "<Control-c>",
        lambda event: copy_all_code()
        if str(window.focus_get()) != str(code_text)
        else None,
    )

    window.protocol(
        "WM_DELETE_WINDOW",
        window.destroy,
    )

    search_entry.focus_set()


# ================================================================
# 일반 사용자/관리자 버튼 전환
# ================================================================

def _v95_find_action_buttons(namespace):
    root = namespace.get("root")

    if root is None:
        return None, None

    feedback_button = namespace.get(
        "btn_feedback"
    )

    code_button = namespace.get(
        "btn_view_code"
    )

    for widget in _v95_walk_widgets(root):
        try:
            widget_class = widget.winfo_class()

            if widget_class not in (
                "Button",
                "TButton",
            ):
                continue

            text = _v95_widget_text(widget)

            if "개선사항" in text:
                feedback_button = widget

            elif "코드 보기" in text:
                code_button = widget

        except Exception:
            pass

    return feedback_button, code_button


def _v95_forget_widget(widget):
    if widget is None:
        return

    try:
        widget.pack_forget()
    except Exception:
        pass

    try:
        widget.grid_remove()
    except Exception:
        pass

    try:
        widget.place_forget()
    except Exception:
        pass


def _v95_pack_action_button(widget):
    if widget is None:
        return

    try:
        widget.pack(
            side="left",
            padx=5,
        )
        return
    except Exception:
        pass

    try:
        widget.grid()
    except Exception:
        pass


def _v95_apply_mode_buttons(namespace):
    if not isinstance(namespace, dict):
        return

    mode = str(
        namespace.get(
            "_v95_login_mode",
            globals().get(
                "current_login_mode",
                "user",
            ),
        )
    ).strip().lower()

    if mode not in (
        "user",
        "admin",
    ):
        mode = "user"

    namespace[
        "current_login_mode"
    ] = mode

    namespace[
        "_v95_login_mode"
    ] = mode

    feedback_button, code_button = (
        _v95_find_action_buttons(
            namespace
        )
    )

    # 코드 보기 버튼이 원본에 없으면 하단 프레임에 새로 만든다.
    if code_button is None:
        bottom_frame = namespace.get(
            "bottom_frame"
        )

        if bottom_frame is not None:
            try:
                import tkinter as tk

                code_button = tk.Button(
                    bottom_frame,
                    text="코드 보기",
                    font=(
                        "Arial",
                        10,
                        "bold",
                    ),
                    bg="#5b9bd5",
                    fg="white",
                    activebackground="#4472c4",
                    activeforeground="white",
                    width=13,
                    relief="flat",
                    cursor="hand2",
                    command=lambda ns=namespace: (
                        _v95_open_code_window(ns)
                    ),
                )

                namespace[
                    "btn_view_code"
                ] = code_button

            except Exception:
                code_button = None

    if code_button is not None:
        try:
            code_button.configure(
                text="코드 보기",
                command=lambda ns=namespace: (
                    _v95_open_code_window(ns)
                ),
            )
        except Exception:
            pass

    if mode == "admin":
        _v95_forget_widget(
            feedback_button
        )

        _v95_pack_action_button(
            code_button
        )

    else:
        _v95_forget_widget(
            code_button
        )

        _v95_pack_action_button(
            feedback_button
        )


def _v95_wrap_trade_open_functions(
    namespace,
):
    for function_name in list(
        namespace.keys()
    ):
        if not str(function_name).endswith(
            "_open_selected_supervision"
        ):
            continue

        original = namespace.get(
            function_name
        )

        if not callable(original):
            continue

        if getattr(
            original,
            "_v95_open_wrapper",
            False,
        ):
            continue

        def wrapper(
            *args,
            __original=original,
            **kwargs
        ):
            namespace[
                "current_login_mode"
            ] = namespace.get(
                "_v95_login_mode",
                _v95_current_mode(),
            )

            result = __original(
                *args,
                **kwargs
            )

            root = namespace.get("root")

            def update_buttons():
                _v95_apply_mode_buttons(
                    namespace
                )

            if root is not None:
                try:
                    root.after_idle(
                        update_buttons
                    )

                    root.after(
                        100,
                        update_buttons,
                    )
                except Exception:
                    update_buttons()
            else:
                update_buttons()

            return result

        wrapper._v95_open_wrapper = True
        wrapper.__name__ = function_name

        namespace[
            function_name
        ] = wrapper


