def _v95_find_master_password_entries():
    root = globals().get(
        "master_root"
    )

    if root is None:
        return None, None

    user_entry = globals().get(
        "pwd_entry"
    )

    admin_entry = globals().get(
        "admin_pwd_entry"
    )

    # 전역 이름으로 못 찾으면 로그인 화면의 라벨과 인접 Entry 탐색
    if user_entry is not None and admin_entry is not None:
        return user_entry, admin_entry

    for widget in _v95_walk_widgets(root):
        text = _v95_widget_text(widget)

        if (
            "일반 사용자 암호" not in text
            and "관리자 암호" not in text
        ):
            continue

        try:
            parent = widget.master
            siblings = parent.winfo_children()
        except Exception:
            continue

        entry = None

        for sibling in siblings:
            try:
                if sibling.winfo_class() in (
                    "Entry",
                    "TEntry",
                ):
                    entry = sibling
                    break
            except Exception:
                pass

        if entry is None:
            continue

        if "일반 사용자 암호" in text:
            user_entry = entry

        elif "관리자 암호" in text:
            admin_entry = entry

    return user_entry, admin_entry


def _v95_login_succeeded():
    selection_frame = globals().get(
        "selection_frame"
    )

    login_frame = globals().get(
        "login_frame"
    )

    try:
        selection_visible = bool(
            selection_frame.winfo_ismapped()
        )
    except Exception:
        selection_visible = False

    try:
        login_visible = bool(
            login_frame.winfo_ismapped()
        )
    except Exception:
        login_visible = True

    return (
        selection_visible
        and not login_visible
    )


def _v95_apply_mode_to_existing_trades():
    mode = _v95_current_mode()

    for namespace in list(
        globals().get(
            "trade_instances",
            {},
        ).values()
    ):
        if not isinstance(namespace, dict):
            continue

        namespace[
            "current_login_mode"
        ] = mode

        namespace[
            "_v95_login_mode"
        ] = mode

        _v95_wrap_trade_open_functions(
            namespace
        )

        _v95_apply_mode_buttons(
            namespace
        )


def _v95_install_master_login():
    if globals().get(
        "_v95_master_login_installed"
    ):
        return

    root = globals().get(
        "master_root"
    )

    if root is None:
        return

    user_entry, admin_entry = (
        _v95_find_master_password_entries()
    )

    login_function_name = None
    login_function = None

    preferred_names = (
        "_attempt_login",
        "attempt_login",
        "main_attempt_login",
    )

    for name in preferred_names:
        candidate = globals().get(name)

        if callable(candidate):
            login_function_name = name
            login_function = candidate
            break

    if login_function is None:
        for name, candidate in list(
            globals().items()
        ):
            if (
                callable(candidate)
                and str(name).endswith(
                    "attempt_login"
                )
            ):
                login_function_name = name
                login_function = candidate
                break

    if not callable(login_function):
        return

    if getattr(
        login_function,
        "_v95_login_wrapper",
        False,
    ):
        globals()[
            "_v95_master_login_installed"
        ] = True
        return

    
def _v95_apply_runtime_patch(
    namespace,
    trade_name=None,
):
    if not isinstance(namespace, dict):
        return

    mode = _v95_current_mode()

    namespace[
        "current_login_mode"
    ] = mode

    namespace[
        "_v95_login_mode"
    ] = mode

    _v95_wrap_trade_open_functions(
        namespace
    )

    _v95_apply_mode_buttons(
        namespace
    )

    root = namespace.get("root")

    if root is not None:
        try:
            root.after_idle(
                lambda ns=namespace: (
                    _v95_apply_mode_buttons(ns)
                )
            )

            root.after(
                300,
                lambda ns=namespace: (
                    _v95_apply_mode_buttons(ns)
                ),
            )
        except Exception:
            pass

    namespace[
        "_v95_runtime_patch_installed"
    ] = True
