# ================================================================
# 최종본213 Excel 두 개 파일 완전 분리 저장
#
# 파일 1:
#   개요
#   기본입력사항
#   감리원 배치계획
#
# 파일 2:
#   개별(정상요율) 산출조서
#   통합(정상요율) 산출조서
#   통합(조정요율) 산출조서
#
# 파일 간 시트 복사·병합 없음
# 화면 캡처·이미지 삽입 없음
# ================================================================

def _v213_normalize_sheet_name(name):
    import re
    import unicodedata

    text = unicodedata.normalize(
        "NFKC",
        str(name or "")
    )

    return re.sub(
        r"[\s_\-]+",
        "",
        text
    ).lower()


def _v213_find_sheet(
    workbook,
    candidate_names
):
    normalized_candidates = {
        _v213_normalize_sheet_name(name)
        for name in candidate_names
    }

    for worksheet in workbook.worksheets:
        normalized_title = (
            _v213_normalize_sheet_name(
                worksheet.title
            )
        )

        if normalized_title in normalized_candidates:
            return worksheet

    # 정확히 일치하지 않아도 시트명 뒤에
    # "입력", "표", "화면" 등이 붙은 경우를 허용한다.
    allowed_suffixes = (
        "입력",
        "입력사항",
        "표",
        "화면",
        "시트",
    )

    for worksheet in workbook.worksheets:
        normalized_title = (
            _v213_normalize_sheet_name(
                worksheet.title
            )
        )

        for candidate_name in normalized_candidates:
            if not candidate_name:
                continue

            if normalized_title.startswith(
                candidate_name
            ):
                remaining_text = normalized_title[
                    len(candidate_name):
                ]

                if (
                    not remaining_text
                    or remaining_text in allowed_suffixes
                ):
                    return worksheet

    return None


def _v213_count_values(worksheet):
    value_count = 0

    for row in worksheet.iter_rows():
        for cell in row:
            if cell.value not in (None, ""):
                value_count += 1

    return value_count


def _v213_check_no_images(worksheets):
    for worksheet in worksheets:
        images = getattr(
            worksheet,
            "_images",
            []
        )

        if images:
            raise RuntimeError(
                f"'{worksheet.title}' 시트에서 "
                "이미지가 발견되었습니다.\n"
                "최종본213은 실제 셀 데이터만 허용합니다."
            )


def _v213_remove_unwanted_sheets(
    workbook,
    wanted_sheets
):
    wanted_sheets = list(wanted_sheets)

    for worksheet in list(workbook.worksheets):
        if worksheet not in wanted_sheets:
            workbook.remove(worksheet)

    workbook._sheets = wanted_sheets

    if workbook.worksheets:
        try:
            workbook.active = 0
        except Exception:
            pass


def _v213_prepare_first_file(file_path):
    import os
    import openpyxl

    if not os.path.isfile(file_path):
        raise RuntimeError(
            "첫 번째 Excel 임시 파일이 없습니다."
        )

    workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        overview_sheet = _v213_find_sheet(
            workbook,
            (
                "개요",
                "표지",
            )
        )

        basic_sheet = _v213_find_sheet(
            workbook,
            (
                "기본입력사항",
                "기본 입력사항",
                "기본입력",
                "사업정보",
            )
        )

        staffing_sheet = _v213_find_sheet(
            workbook,
            (
                "감리원 배치계획",
                "감리원배치계획",
                "감리 배치계획",
                "감리배치계획",
                "배치계획표",
                "투입계획표",
                "감리원 투입계획표",
                "감리원투입계획표",
                "감리원 배치계획 입력",
                "감리원배치계획입력",
                "감리 배치계획 입력",
                "감리배치계획입력",
                "배치계획 입력",
                "배치계획입력",
            )
        )

        missing_sheets = []

        if overview_sheet is None:
            missing_sheets.append("개요")

        if basic_sheet is None:
            missing_sheets.append("기본입력사항")

        if staffing_sheet is None:
            missing_sheets.append("감리원 배치계획")

        if missing_sheets:
            raise RuntimeError(
                "첫 번째 파일에서 다음 시트를 "
                "찾지 못했습니다.\n"
                + ", ".join(missing_sheets)
                + "\n\n현재 생성된 시트:\n"
                + ", ".join(workbook.sheetnames)
            )

        _v213_check_no_images(
            (
                overview_sheet,
                basic_sheet,
                staffing_sheet,
            )
        )

        if _v213_count_values(overview_sheet) < 1:
            raise RuntimeError(
                "'개요' 시트에 실제 셀 데이터가 없습니다."
            )

        if _v213_count_values(basic_sheet) < 10:
            raise RuntimeError(
                "'기본입력사항' 시트에 실제 셀 데이터가 "
                "충분히 입력되지 않았습니다."
            )

        if _v213_count_values(staffing_sheet) < 1:
            raise RuntimeError(
                "'감리원 배치계획' 시트에 실제 셀 데이터가 없습니다."
            )

        overview_sheet.title = "개요"
        basic_sheet.title = "기본입력사항"
        staffing_sheet.title = "감리원 배치계획"

        _v213_remove_unwanted_sheets(
            workbook,
            (
                overview_sheet,
                basic_sheet,
                staffing_sheet,
            )
        )

        for worksheet in workbook.worksheets:
            worksheet._images = []

        workbook.save(file_path)

    finally:
        try:
            workbook.close()
        except Exception:
            pass

    # 저장 후 재검증
    verification_workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        expected_names = [
            "개요",
            "기본입력사항",
            "감리원 배치계획",
        ]

        if verification_workbook.sheetnames != expected_names:
            raise RuntimeError(
                "첫 번째 파일의 시트 구성이 올바르지 않습니다.\n"
                f"예상: {expected_names}\n"
                f"실제: {verification_workbook.sheetnames}"
            )

        _v213_check_no_images(
            verification_workbook.worksheets
        )

    finally:
        verification_workbook.close()


def _v213_prepare_second_file(file_path):
    import os
    import openpyxl

    if not os.path.isfile(file_path):
        raise RuntimeError(
            "두 번째 Excel 임시 파일이 없습니다."
        )

    workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        calculation_specs = (
            (
                "개별(정상요율) 산출조서",
                (
                    "개별(정상요율) 산출조서",
                    "개별(정상요율)산출조서",
                ),
            ),
            (
                "통합(정상요율) 산출조서",
                (
                    "통합(정상요율) 산출조서",
                    "통합(정상요율)산출조서",
                ),
            ),
            (
                "통합(조정요율) 산출조서",
                (
                    "통합(조정요율) 산출조서",
                    "통합(조정요율)산출조서",
                ),
            ),
        )

        calculation_sheets = []
        missing_sheets = []

        for standard_name, candidates in calculation_specs:
            worksheet = _v213_find_sheet(
                workbook,
                candidates
            )

            if worksheet is None:
                missing_sheets.append(standard_name)
                continue

            calculation_sheets.append(
                (
                    standard_name,
                    worksheet,
                )
            )

        if missing_sheets:
            raise RuntimeError(
                "두 번째 파일에서 다음 산출조서를 "
                "찾지 못했습니다.\n"
                + ", ".join(missing_sheets)
                + "\n\n현재 생성된 시트:\n"
                + ", ".join(workbook.sheetnames)
            )

        for standard_name, worksheet in calculation_sheets:
            if _v213_count_values(worksheet) < 10:
                raise RuntimeError(
                    f"'{standard_name}' 시트에 실제 셀 데이터가 "
                    "충분히 입력되지 않았습니다."
                )

            worksheet.title = standard_name

        wanted_sheets = [
            worksheet
            for _, worksheet in calculation_sheets
        ]

        _v213_remove_unwanted_sheets(
            workbook,
            wanted_sheets
        )

        for worksheet in workbook.worksheets:
            worksheet._images = []

        try:
            workbook.calculation.fullCalcOnLoad = True
            workbook.calculation.forceFullCalc = True
            workbook.calculation.calcMode = "auto"
        except Exception:
            pass

        try:
            workbook.calculation_properties.fullCalcOnLoad = True
            workbook.calculation_properties.forceFullCalc = True
            workbook.calculation_properties.calcMode = "auto"
        except Exception:
            pass

        workbook.save(file_path)

    finally:
        try:
            workbook.close()
        except Exception:
            pass

    # 저장 후 재검증
    verification_workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        expected_names = [
            "개별(정상요율) 산출조서",
            "통합(정상요율) 산출조서",
            "통합(조정요율) 산출조서",
        ]

        if verification_workbook.sheetnames != expected_names:
            raise RuntimeError(
                "두 번째 파일의 시트 구성이 올바르지 않습니다.\n"
                f"예상: {expected_names}\n"
                f"실제: {verification_workbook.sheetnames}"
            )

        _v213_check_no_images(
            verification_workbook.worksheets
        )

    finally:
        verification_workbook.close()


def _v213_make_project_title(namespace):
    project_names = []
    entry_names = namespace.get(
        "entry_names",
        []
    )

    for index in range(
        min(3, len(entry_names))
    ):
        try:
            project_name = str(
                entry_names[index].get()
            ).strip()
        except Exception:
            project_name = ""

        if project_name:
            project_names.append(project_name)

    if project_names:
        return ", ".join(project_names)

    return "미지정사업"


def _v213_safe_filename_text(text):
    import re

    text = str(text or "").strip()

    text = re.sub(
        r'[\\/:*?"<>|]',
        "_",
        text
    )

    text = re.sub(
        r"\s+",
        " ",
        text
    ).strip()

    text = text.rstrip(". ")

    if not text:
        return "미지정사업"

    return text[:120]


def _v213_rebuild_staffing_sheet(
    file_path,
    namespace,
    trade_name
):
    """
    빈 외곽 프레임이 아닌 실제 감리원 배치계획 표 컨테이너를
    openpyxl 셀로 직접 변환하여 저장한다.

    화면 캡처, PNG, 이미지 삽입은 사용하지 않는다.
    """
    import openpyxl

    root_widget = namespace.get("root")

    trade_prefix = {
        "전기": "electric",
        "통신": "communication",
        "소방": "fire",
    }.get(
        trade_name,
        ""
    )

    # ------------------------------------------------------------
    # 1. 감리원 배치계획 화면의 실제 표를 최신 데이터로 갱신
    # ------------------------------------------------------------
    update_function_names = (
        trade_prefix + "_update_gantt_header",
        trade_prefix + "_update_gantt",
        trade_prefix + "_create_gantt",
        trade_prefix + "_create_gantt_chart",
        trade_prefix + "_generate_gantt",
        trade_prefix + "_generate_gantt_chart",
        "update_gantt_header",
        "update_gantt",
        "create_gantt",
        "create_gantt_chart",
        "generate_gantt",
        "generate_gantt_chart",
    )

    for function_name in update_function_names:
        if not function_name.strip("_"):
            continue

        update_function = namespace.get(
            function_name
        )

        if not callable(update_function):
            continue

        try:
            update_function()
        except TypeError:
            # 인수가 필요한 보조 함수는 호출하지 않는다.
            pass
        except Exception:
            pass

    if root_widget is not None:
        try:
            root_widget.update_idletasks()
        except Exception:
            pass

        try:
            root_widget.update()
        except Exception:
            pass

        try:
            root_widget.update_idletasks()
        except Exception:
            pass

    # ------------------------------------------------------------
    # 2. 실제 표가 들어 있는 위젯 후보 검색
    # ------------------------------------------------------------
    widget_candidates = []

    candidate_variable_names = (
        "gantt_container",
        "deployment_plan_frame",
        "gantt_frame",
        "gantt_table_frame",
        "gantt_content_frame",
        "deployment_container",
        "deployment_table_frame",
    )

    for variable_name in candidate_variable_names:
        widget = namespace.get(
            variable_name
        )

        if widget is None:
            continue

        if widget not in widget_candidates:
            widget_candidates.append(widget)

    # sheet_frames에 등록된 외곽 프레임의 내부에서도
    # 실제 데이터 위젯이 가장 많은 하위 프레임을 찾는다.
    sheet_frames = namespace.get(
        "sheet_frames",
        {}
    )

    if isinstance(sheet_frames, dict):
        for sheet_name, sheet_frame in sheet_frames.items():
            normalized_name = (
                _v213_normalize_sheet_name(
                    sheet_name
                )
            )

            if (
                "감리원배치계획" not in normalized_name
                and "배치계획" not in normalized_name
                and "투입계획" not in normalized_name
            ):
                continue

            if sheet_frame is not None:
                if sheet_frame not in widget_candidates:
                    widget_candidates.append(
                        sheet_frame
                    )

                # 외곽 프레임 아래에 Canvas/스크롤 프레임이 있으므로
                # 모든 하위 프레임을 후보로 추가한다.
                for child_widget in _v213_walk_widgets(
                    sheet_frame
                ):
                    try:
                        child_class = (
                            child_widget.winfo_class()
                        )
                    except Exception:
                        continue

                    if child_class not in (
                        "Frame",
                        "TFrame",
                        "Labelframe",
                        "TLabelframe",
                        "Canvas",
                    ):
                        continue

                    if child_widget not in widget_candidates:
                        widget_candidates.append(
                            child_widget
                        )

    # 자식 위젯이 많은 실제 표 컨테이너를 먼저 시도한다.
    def widget_score(widget):
        score = 0

        try:
            score += len(
                _v213_walk_widgets(widget)
            )
        except Exception:
            pass

        try:
            score += len(
                widget.winfo_children()
            ) * 5
        except Exception:
            pass

        try:
            variable_name = str(widget)
            if "gantt" in variable_name.lower():
                score += 100
        except Exception:
            pass

        return score

    widget_candidates.sort(
        key=widget_score,
        reverse=True
    )

    if not widget_candidates:
        raise RuntimeError(
            "감리원 배치계획의 실제 표 컨테이너를 "
            "찾지 못했습니다."
        )

    # ------------------------------------------------------------
    # 3. 기존 빈 시트를 삭제하고 실제 위젯을 셀로 변환
    # ------------------------------------------------------------
    workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        old_staffing_sheets = []

        for worksheet in workbook.worksheets:
            normalized_title = (
                _v213_normalize_sheet_name(
                    worksheet.title
                )
            )

            if (
                "감리원배치계획" in normalized_title
                or "감리배치계획" in normalized_title
                or "배치계획표" in normalized_title
                or "투입계획표" in normalized_title
            ):
                old_staffing_sheets.append(
                    worksheet
                )

        for worksheet in old_staffing_sheets:
            workbook.remove(
                worksheet
            )

        created_sheet = None
        best_value_count = 0
        best_sheet = None

        for candidate_index, widget in enumerate(
            widget_candidates,
            start=1
        ):
            try:
                if not widget.winfo_exists():
                    continue
            except Exception:
                continue

            try:
                widget.update_idletasks()
            except Exception:
                pass

            temporary_sheet_name = (
                f"_배치계획후보{candidate_index}"
            )

            try:
                worksheet = _v71_write_widget_sheet(
                    workbook,
                    temporary_sheet_name,
                    widget
                )
            except Exception:
                continue

            if worksheet is None:
                try:
                    worksheet = workbook[
                        temporary_sheet_name
                    ]
                except Exception:
                    continue

            value_count = _v213_count_values(
                worksheet
            )

            if value_count > best_value_count:
                if (
                    best_sheet is not None
                    and best_sheet in workbook.worksheets
                ):
                    workbook.remove(
                        best_sheet
                    )

                best_sheet = worksheet
                best_value_count = value_count
                created_sheet = worksheet
            else:
                if worksheet in workbook.worksheets:
                    workbook.remove(
                        worksheet
                    )

            # 제목과 표 데이터가 충분하면 추가 후보 탐색 불필요
            if best_value_count >= 10:
                break

        if created_sheet is None or best_value_count < 1:
            raise RuntimeError(
                "감리원 배치계획 표에서 실제 셀 데이터를 "
                "수집하지 못했습니다.\n\n"
                "프로그램에서 감리원 정보를 입력한 후 "
                "'감리원 배치계획표 생성하기'를 먼저 누르고 "
                "다시 Excel 내려받기를 실행하십시오."
            )

        created_sheet.title = (
            "감리원 배치계획"
        )

        # 시트에 이미지가 포함되지 않았는지 확인
        _v213_check_no_images(
            (
                created_sheet,
            )
        )

        workbook.save(
            file_path
        )

    finally:
        try:
            workbook.close()
        except Exception:
            pass

    # ------------------------------------------------------------
    # 4. 저장 후 실제 셀 데이터 재검증
    # ------------------------------------------------------------
    verification_workbook = openpyxl.load_workbook(
        file_path,
        data_only=False
    )

    try:
        staffing_sheet = _v213_find_sheet(
            verification_workbook,
            (
                "감리원 배치계획",
            )
        )

        if staffing_sheet is None:
            raise RuntimeError(
                "감리원 배치계획 시트 저장에 실패했습니다."
            )

        value_count = _v213_count_values(
            staffing_sheet
        )

        if value_count < 1:
            raise RuntimeError(
                "'감리원 배치계획' 시트에 실제 셀 데이터가 없습니다."
            )

        _v213_check_no_images(
            (
                staffing_sheet,
            )
        )

    finally:
        verification_workbook.close()


def _v213_run_first_file_export(
    namespace,
    trade_name,
    output_path
):
    import os
    from tkinter import filedialog
    from tkinter import messagebox

    if os.path.exists(output_path):
        os.remove(output_path)

    original_save_dialog = (
        filedialog.asksaveasfilename
    )
    original_showinfo = messagebox.showinfo

    def fixed_save_dialog(*args, **kwargs):
        return output_path

    def suppressed_showinfo(*args, **kwargs):
        return None

    try:
        filedialog.asksaveasfilename = (
            fixed_save_dialog
        )
        messagebox.showinfo = (
            suppressed_showinfo
        )

        # V71은 Tkinter 위젯 좌표와 실제 값을
        # openpyxl 셀로 직접 변환한다.
        # 화면 캡처나 이미지 삽입을 사용하지 않는다.
        _v71_export_screen_excel(
            namespace,
            trade_name
        )

    finally:
        filedialog.asksaveasfilename = (
            original_save_dialog
        )
        messagebox.showinfo = (
            original_showinfo
        )

    if not os.path.isfile(output_path):
        raise RuntimeError(
            "첫 번째 Excel 파일 생성에 실패했습니다.\n"
            "V71 셀 변환 함수가 파일을 저장하지 못했습니다."
        )

    if os.path.getsize(output_path) <= 0:
        raise RuntimeError(
            "첫 번째 Excel 파일이 비어 있습니다."
        )

    # V71이 만든 빈 외곽 시트를 사용하지 않고
    # 실제 gantt_container를 Excel 셀로 다시 생성한다.
    _v213_rebuild_staffing_sheet(
        output_path,
        namespace,
        trade_name
    )

    _v213_prepare_first_file(
        output_path
    )


def _v213_run_second_file_export(
    output_path,
    report_export_function,
    run_export_function
):
    import os

    if not callable(report_export_function):
        raise RuntimeError(
            "v199 산출조서 생성 함수를 찾지 못했습니다."
        )

    if not callable(run_export_function):
        raise RuntimeError(
            "v199 산출조서 저장 함수를 찾지 못했습니다."
        )

    if os.path.exists(output_path):
        os.remove(output_path)

    export_error = None

    try:
        created = run_export_function(
            report_export_function,
            output_path
        )
    except Exception as error:
        created = False
        export_error = error

    file_created = os.path.isfile(
        output_path
    )

    # 일부 기존 함수는 파일을 정상 생성하고도
    # None을 반환할 수 있으므로 실제 파일 존재 여부를 우선한다.
    if not file_created:
        function_name = getattr(
            report_export_function,
            "__name__",
            str(report_export_function)
        )

        error_message = (
            "두 번째 Excel 파일을 생성하지 못했습니다.\n"
            f"사용 함수: {function_name}"
        )

        if export_error is not None:
            error_message += (
                "\n내부 오류: "
                + str(export_error)
            )

        raise RuntimeError(
            error_message
        )

    if os.path.getsize(output_path) <= 0:
        raise RuntimeError(
            "두 번째 Excel 파일이 비어 있습니다."
        )

    _v213_prepare_second_file(
        output_path
    )


def _v213_copy_worksheet_between_workbooks(
    source_worksheet,
    target_workbook,
    target_title
):
    """
    다른 통합문서의 시트를 실제 Excel 셀 방식으로 복사한다.

    복사 대상:
    - 셀 값
    - Excel 수식
    - 글꼴·채우기·테두리·정렬
    - 숫자 표시 형식
    - 행 높이·열 너비
    - 병합 셀
    - 틀 고정
    - 인쇄 설정
    - 하이퍼링크·메모
    - 데이터 유효성 검사
    - 조건부 서식

    이미지 객체는 복사하지 않는다.
    """
    from copy import copy
    from openpyxl.cell.cell import MergedCell

    if getattr(
        source_worksheet,
        "_images",
        []
    ):
        raise RuntimeError(
            f"'{source_worksheet.title}' 시트에 이미지가 있습니다.\n"
            "최종본213는 실제 셀 데이터만 허용합니다."
        )

    target_worksheet = (
        target_workbook.create_sheet(
            title=target_title
        )
    )

    # ------------------------------------------------------------
    # 셀 값·수식·서식 복사
    # ------------------------------------------------------------
    for source_row in source_worksheet.iter_rows():
        for source_cell in source_row:
            if isinstance(source_cell, MergedCell):
                continue

            target_cell = target_worksheet.cell(
                row=source_cell.row,
                column=source_cell.column
            )

            target_cell.value = source_cell.value

            if source_cell.has_style:
                try:
                    target_cell.font = copy(
                        source_cell.font
                    )
                except Exception:
                    pass

                try:
                    target_cell.fill = copy(
                        source_cell.fill
                    )
                except Exception:
                    pass

                try:
                    target_cell.border = copy(
                        source_cell.border
                    )
                except Exception:
                    pass

                try:
                    target_cell.alignment = copy(
                        source_cell.alignment
                    )
                except Exception:
                    pass

                try:
                    target_cell.protection = copy(
                        source_cell.protection
                    )
                except Exception:
                    pass

                try:
                    target_cell.number_format = (
                        source_cell.number_format
                    )
                except Exception:
                    pass

            if source_cell.hyperlink:
                try:
                    target_cell._hyperlink = copy(
                        source_cell.hyperlink
                    )
                except Exception:
                    pass

            if source_cell.comment:
                try:
                    target_cell.comment = copy(
                        source_cell.comment
                    )
                except Exception:
                    pass

    # ------------------------------------------------------------
    # 병합 셀 복사
    # ------------------------------------------------------------
    for merged_range in (
        source_worksheet.merged_cells.ranges
    ):
        try:
            target_worksheet.merge_cells(
                str(merged_range)
            )
        except Exception:
            pass

    # ------------------------------------------------------------
    # 열 너비와 열 속성 복사
    # ------------------------------------------------------------
    for column_letter, source_dimension in (
        source_worksheet.column_dimensions.items()
    ):
        target_dimension = (
            target_worksheet.column_dimensions[
                column_letter
            ]
        )

        try:
            target_dimension.width = (
                source_dimension.width
            )
        except Exception:
            pass

        try:
            target_dimension.hidden = (
                source_dimension.hidden
            )
        except Exception:
            pass

        try:
            target_dimension.bestFit = (
                source_dimension.bestFit
            )
        except Exception:
            pass

        try:
            target_dimension.outlineLevel = (
                source_dimension.outlineLevel
            )
        except Exception:
            pass

        try:
            target_dimension.collapsed = (
                source_dimension.collapsed
            )
        except Exception:
            pass

        try:
            target_dimension.min = (
                source_dimension.min
            )
            target_dimension.max = (
                source_dimension.max
            )
        except Exception:
            pass

    # ------------------------------------------------------------
    # 행 높이와 행 속성 복사
    # ------------------------------------------------------------
    for row_number, source_dimension in (
        source_worksheet.row_dimensions.items()
    ):
        target_dimension = (
            target_worksheet.row_dimensions[
                row_number
            ]
        )

        try:
            target_dimension.height = (
                source_dimension.height
            )
        except Exception:
            pass

        try:
            target_dimension.hidden = (
                source_dimension.hidden
            )
        except Exception:
            pass

        try:
            target_dimension.outlineLevel = (
                source_dimension.outlineLevel
            )
        except Exception:
            pass

        try:
            target_dimension.collapsed = (
                source_dimension.collapsed
            )
        except Exception:
            pass

    # ------------------------------------------------------------
    # 시트 화면 설정 복사
    # ------------------------------------------------------------
    try:
        target_worksheet.freeze_panes = (
            source_worksheet.freeze_panes
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_view.showGridLines = (
            source_worksheet.sheet_view.showGridLines
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_view.zoomScale = (
            source_worksheet.sheet_view.zoomScale
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_view.zoomScaleNormal = (
            source_worksheet.sheet_view.zoomScaleNormal
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_format = copy(
            source_worksheet.sheet_format
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_properties = copy(
            source_worksheet.sheet_properties
        )
    except Exception:
        pass

    # ------------------------------------------------------------
    # 인쇄 설정 복사
    # ------------------------------------------------------------
    try:
        target_worksheet.page_margins = copy(
            source_worksheet.page_margins
        )
    except Exception:
        pass

    try:
        target_worksheet.page_setup = copy(
            source_worksheet.page_setup
        )
    except Exception:
        pass

    try:
        target_worksheet.print_options = copy(
            source_worksheet.print_options
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_properties.pageSetUpPr = copy(
            source_worksheet.sheet_properties.pageSetUpPr
        )
    except Exception:
        pass

    try:
        target_worksheet.print_title_rows = (
            source_worksheet.print_title_rows
        )
    except Exception:
        pass

    try:
        target_worksheet.print_title_cols = (
            source_worksheet.print_title_cols
        )
    except Exception:
        pass

    try:
        target_worksheet.print_area = (
            source_worksheet.print_area
        )
    except Exception:
        pass

    try:
        target_worksheet.auto_filter.ref = (
            source_worksheet.auto_filter.ref
        )
    except Exception:
        pass

    # ------------------------------------------------------------
    # 데이터 유효성 검사 복사
    # ------------------------------------------------------------
    try:
        for validation in (
            source_worksheet.data_validations.dataValidation
        ):
            target_worksheet.add_data_validation(
                copy(validation)
            )
    except Exception:
        pass

    # ------------------------------------------------------------
    # 조건부 서식 복사
    # ------------------------------------------------------------
    try:
        for conditional_range in (
            source_worksheet.conditional_formatting
        ):
            rules = (
                source_worksheet.conditional_formatting[
                    conditional_range
                ]
            )

            for rule in rules:
                target_worksheet.conditional_formatting.add(
                    str(conditional_range),
                    copy(rule)
                )
    except Exception:
        pass

    # ------------------------------------------------------------
    # 시트 보호 및 선택 상태 복사
    # ------------------------------------------------------------
    try:
        target_worksheet.protection = copy(
            source_worksheet.protection
        )
    except Exception:
        pass

    try:
        target_worksheet.sheet_state = (
            source_worksheet.sheet_state
        )
    except Exception:
        pass

    return target_worksheet


def _v213_merge_generated_excel_files(
    first_file_path,
    second_file_path,
    merged_file_path
):
    """
    먼저 정상 생성된 파일 1과 파일 2를 읽어서
    새로운 통합 Excel 파일을 만든다.

    원본 두 임시 파일에는 어떠한 수정도 하지 않는다.
    """
    import os
    import openpyxl

    if not os.path.isfile(first_file_path):
        raise RuntimeError(
            "통합할 첫 번째 Excel 파일이 없습니다."
        )

    if not os.path.isfile(second_file_path):
        raise RuntimeError(
            "통합할 두 번째 Excel 파일이 없습니다."
        )

    first_workbook = openpyxl.load_workbook(
        first_file_path,
        data_only=False
    )

    second_workbook = openpyxl.load_workbook(
        second_file_path,
        data_only=False
    )

    merged_workbook = openpyxl.Workbook()

    try:
        default_sheet = merged_workbook.active
        merged_workbook.remove(
            default_sheet
        )

        first_sheet_specs = (
            (
                "개요",
                (
                    "개요",
                ),
            ),
            (
                "기본입력사항",
                (
                    "기본입력사항",
                    "기본 입력사항",
                ),
            ),
            (
                "감리원 배치계획",
                (
                    "감리원 배치계획",
                    "감리원배치계획",
                ),
            ),
        )

        second_sheet_specs = (
            (
                "개별(정상요율) 산출조서",
                (
                    "개별(정상요율) 산출조서",
                    "개별(정상요율)산출조서",
                ),
            ),
            (
                "통합(정상요율) 산출조서",
                (
                    "통합(정상요율) 산출조서",
                    "통합(정상요율)산출조서",
                ),
            ),
            (
                "통합(조정요율) 산출조서",
                (
                    "통합(조정요율) 산출조서",
                    "통합(조정요율)산출조서",
                ),
            ),
        )

        # --------------------------------------------------------
        # 파일 1의 시트 3개 복사
        # --------------------------------------------------------
        for target_title, candidates in first_sheet_specs:
            source_worksheet = _v213_find_sheet(
                first_workbook,
                candidates
            )

            if source_worksheet is None:
                raise RuntimeError(
                    "첫 번째 파일에서 통합 대상 시트를 "
                    f"찾지 못했습니다: {target_title}"
                )

            _v213_copy_worksheet_between_workbooks(
                source_worksheet,
                merged_workbook,
                target_title
            )

        # --------------------------------------------------------
        # 파일 2의 산출조서 3개 복사
        # --------------------------------------------------------
        for target_title, candidates in second_sheet_specs:
            source_worksheet = _v213_find_sheet(
                second_workbook,
                candidates
            )

            if source_worksheet is None:
                raise RuntimeError(
                    "두 번째 파일에서 통합 대상 시트를 "
                    f"찾지 못했습니다: {target_title}"
                )

            _v213_copy_worksheet_between_workbooks(
                source_worksheet,
                merged_workbook,
                target_title
            )

        expected_sheet_names = [
            "개요",
            "기본입력사항",
            "감리원 배치계획",
            "개별(정상요율) 산출조서",
            "통합(정상요율) 산출조서",
            "통합(조정요율) 산출조서",
        ]

        if (
            merged_workbook.sheetnames
            != expected_sheet_names
        ):
            raise RuntimeError(
                "통합 파일의 시트 순서가 올바르지 않습니다.\n"
                f"예상: {expected_sheet_names}\n"
                f"실제: {merged_workbook.sheetnames}"
            )

        _v213_check_no_images(
            merged_workbook.worksheets
        )

        try:
            merged_workbook.calculation.fullCalcOnLoad = True
            merged_workbook.calculation.forceFullCalc = True
            merged_workbook.calculation.calcMode = "auto"
        except Exception:
            pass

        try:
            merged_workbook.calculation_properties.fullCalcOnLoad = True
            merged_workbook.calculation_properties.forceFullCalc = True
            merged_workbook.calculation_properties.calcMode = "auto"
        except Exception:
            pass

        if os.path.exists(merged_file_path):
            os.remove(
                merged_file_path
            )

        merged_workbook.save(
            merged_file_path
        )

    finally:
        try:
            first_workbook.close()
        except Exception:
            pass

        try:
            second_workbook.close()
        except Exception:
            pass

        try:
            merged_workbook.close()
        except Exception:
            pass

    if not os.path.isfile(merged_file_path):
        raise RuntimeError(
            "통합 Excel 파일이 생성되지 않았습니다."
        )

    # ------------------------------------------------------------
    # 최종 통합 파일 검증
    # ------------------------------------------------------------
    verification_workbook = openpyxl.load_workbook(
        merged_file_path,
        data_only=False
    )

    try:
        expected_sheet_names = [
            "개요",
            "기본입력사항",
            "감리원 배치계획",
            "개별(정상요율) 산출조서",
            "통합(정상요율) 산출조서",
            "통합(조정요율) 산출조서",
        ]

        if (
            verification_workbook.sheetnames
            != expected_sheet_names
        ):
            raise RuntimeError(
                "저장된 통합 파일의 시트 구성이 "
                "올바르지 않습니다.\n"
                f"실제: {verification_workbook.sheetnames}"
            )

        _v213_check_no_images(
            verification_workbook.worksheets
        )

        for worksheet in (
            verification_workbook.worksheets
        ):
            if _v213_count_values(worksheet) < 1:
                raise RuntimeError(
                    f"통합 파일의 '{worksheet.title}' 시트에 "
                    "실제 셀 데이터가 없습니다."
                )

    finally:
        verification_workbook.close()


def _v213_export_two_separate_files(
    namespace,
    trade_name,
    report_export_function,
    run_export_function
):
    import os
    import shutil
    import tempfile
    import traceback
    from datetime import datetime
    from tkinter import filedialog
    from tkinter import messagebox

    if namespace.get(
        "_v213_excel_export_busy",
        False
    ):
        return

    namespace["_v213_excel_export_busy"] = True

    temporary_directory = None

    try:
        output_directory = filedialog.askdirectory(
            title="Excel 파일 2개를 저장할 폴더 선택"
        )

        if not output_directory:
            return

        output_directory = os.path.abspath(
            output_directory
        )

        if not os.path.isdir(output_directory):
            raise RuntimeError(
                "선택한 저장 폴더가 존재하지 않습니다."
            )

        project_title = _v213_safe_filename_text(
            _v213_make_project_title(namespace)
        )

        trade_text = _v213_safe_filename_text(
            trade_name
        )

        date_text = datetime.now().strftime(
            "%y%m%d"
        )

        first_filename = (
            f"서울대학교 {project_title} "
            f"{trade_text}공사 감리용역_"
            f"1_개요_기본입력사항_감리원배치계획_"
            f"{date_text}.xlsx"
        )

        second_filename = (
            f"서울대학교 {project_title} "
            f"{trade_text}공사 감리용역_"
            f"2_개별_통합_산출조서_"
            f"{date_text}.xlsx"
        )

        first_output_path = os.path.join(
            output_directory,
            first_filename
        )

        second_output_path = os.path.join(
            output_directory,
            second_filename
        )

        if os.path.normcase(first_output_path) == os.path.normcase(
            second_output_path
        ):
            raise RuntimeError(
                "두 출력 파일의 경로가 동일합니다."
            )

        temporary_directory = tempfile.mkdtemp(
            prefix="final207_excel_"
        )

        temporary_first_path = os.path.join(
            temporary_directory,
            "file_1.xlsx"
        )

        temporary_second_path = os.path.join(
            temporary_directory,
            "file_2.xlsx"
        )

        root_widget = namespace.get("root")

        if root_widget is not None:
            try:
                root_widget.update_idletasks()
            except Exception:
                pass

            try:
                root_widget.update()
            except Exception:
                pass

        # 파일 1과 파일 2를 각각 독립적으로 생성한다.
        # 한 통합문서를 만든 뒤 시트를 복사하는 방식이 아니다.
        _v213_run_first_file_export(
            namespace,
            trade_name,
            temporary_first_path
        )

        _v213_run_second_file_export(
            temporary_second_path,
            report_export_function,
            run_export_function
        )

        # ------------------------------------------------
        # 정상 생성된 두 임시 파일을 수정하지 않고
        # 새로운 통합 Excel 파일 1개로 합친다.
        # ------------------------------------------------
        merged_filename = (
            f"서울대학교 {project_title} "
            f"{trade_text}공사 감리용역_"
            f"통합본_{date_text}.xlsx"
        )

        merged_output_path = os.path.join(
            output_directory,
            merged_filename
        )

        _v213_merge_generated_excel_files(
            temporary_first_path,
            temporary_second_path,
            merged_output_path
        )

        messagebox.showinfo(
            "통합 Excel 파일 저장 완료",
            "정상 생성된 두 Excel 파일을 실제 셀 방식으로 "
            "하나의 통합 파일에 합쳤습니다.\n\n"
            "[시트 구성]\n"
            "1. 개요\n"
            "2. 기본입력사항\n"
            "3. 감리원 배치계획\n"
            "4. 개별(정상요율) 산출조서\n"
            "5. 통합(정상요율) 산출조서\n"
            "6. 통합(조정요율) 산출조서\n\n"
            f"저장 위치:\n{merged_output_path}"
        )

    except PermissionError:
        messagebox.showerror(
            "Excel 저장 오류",
            "저장 대상 Excel 파일이 열려 있거나 "
            "파일을 쓸 권한이 없습니다.\n\n"
            "Excel 파일을 닫은 후 다시 실행하십시오."
        )

    except Exception as error:
        log_path = os.path.join(
            os.path.dirname(
                os.path.abspath(__file__)
            ),
            "최종본213_엑셀오류.log"
        )

        try:
            with open(
                log_path,
                "a",
                encoding="utf-8"
            ) as log_file:
                log_file.write(
                    "=" * 70
                    + "\n"
                )
                log_file.write(
                    datetime.now().strftime(
                        "%Y-%m-%d %H:%M:%S"
                    )
                    + "\n"
                )
                log_file.write(
                    traceback.format_exc()
                )
                log_file.write("\n")
        except Exception:
            pass

        messagebox.showerror(
            "Excel 저장 오류",
            str(error)
            + "\n\n오류 기록:\n"
            + log_path
        )

    finally:
        namespace["_v213_excel_export_busy"] = False

        if temporary_directory:
            try:
                shutil.rmtree(
                    temporary_directory,
                    ignore_errors=True
                )
            except Exception:
                pass


def _v213_walk_widgets(parent):
    widgets = []

    if parent is None:
        return widgets

    try:
        children = parent.winfo_children()
    except Exception:
        children = []

    for child in children:
        widgets.append(child)

        try:
            widgets.extend(
                _v213_walk_widgets(child)
            )
        except Exception:
            pass

    return widgets


def _v213_is_excel_button(widget):
    try:
        widget_class = widget.winfo_class()
    except Exception:
        return False

    if widget_class not in (
        "Button",
        "TButton",
    ):
        return False

    try:
        widget_text = str(
            widget.cget("text")
        ).replace(" ", "")
    except Exception:
        return False

    if "엑셀" not in widget_text:
        return False

    return any(
        keyword in widget_text
        for keyword in (
            "내려받기",
            "다운로드",
            "저장",
            "내보내기",
            "출력",
        )
    )


def _v213_install_trade_patch(
    namespace,
    trade_name
):
    prefix = {
        "전기": "electric",
        "통신": "communication",
        "소방": "fire",
    }.get(trade_name)

    if not prefix:
        return

    # ------------------------------------------------------------
    # 산출조서 원본 생성 함수 선택
    #
    # v199_report_export는 대부분 v197_safe_excel_export를
    # 가리키고 있으며, v197 함수는 내부에서 다시 v193을 찾는다.
    # v193은 기본입력사항 이미지 생성 경로를 포함할 수 있으므로
    # 최종본213에서는 사용하지 않는다.
    #
    # v192 또는 v184의 실제 셀 기반 산출조서 생성 함수를
    # 직접 선택하여 개별·통합 산출조서 3개를 만든다.
    # ------------------------------------------------------------
    report_export_function = None
    selected_report_function_name = None

    report_function_candidates = (
        prefix + "_v192_export_to_excel",
        prefix + "_v190_export_to_ex",
        prefix + "_v184_export_to_excel",
    )

    for candidate_name in report_function_candidates:
        candidate_function = namespace.get(
            candidate_name
        )

        if callable(candidate_function):
            report_export_function = (
                candidate_function
            )
            selected_report_function_name = (
                candidate_name
            )
            break

    # 셀 기반 직접 생성 함수를 찾지 못한 경우에만
    # 기존 v199 원본 함수 객체를 최후 수단으로 사용한다.
    if not callable(report_export_function):
        candidate_function = namespace.get(
            prefix + "_v199_report_export"
        )

        if callable(candidate_function):
            report_export_function = (
                candidate_function
            )
            selected_report_function_name = (
                prefix + "_v199_report_export"
            )

    run_export_function = namespace.get(
        prefix + "_v199_run_export"
    )

    if not callable(report_export_function):
        raise RuntimeError(
            f"{trade_name}공종의 셀 기반 산출조서 "
            "생성 함수를 찾지 못했습니다."
        )

    if not callable(run_export_function):
        raise RuntimeError(
            f"{trade_name}공종의 "
            f"{prefix}_v199_run_export 함수를 "
            "찾지 못했습니다."
        )

    namespace[
        "_v213_selected_report_function"
    ] = selected_report_function_name

    def two_file_export_command():
        return _v213_export_two_separate_files(
            namespace,
            trade_name,
            report_export_function,
            run_export_function
        )

    namespace[
        "_v213_two_file_export_command"
    ] = two_file_export_command

    def disabled_old_excel_patch(*args, **kwargs):
        # 이전 버전의 Excel 버튼 재연결 기능을 중지한다.
        return None

    # ------------------------------------------------------------
    # 기존 버전의 반복 버튼 감시 함수를 중지한다.
    #
    # 최종본207 오류 원인:
    #   v208 버튼을 연결한 뒤에도 v189/v190 감시 타이머가
    #   500ms마다 이전 electric_v197_safe_excel_export 등을
    #   다시 연결하고 있었다.
    #
    # 이미 예약된 이전 watcher가 한 번 실행되더라도,
    # 내부 전역 함수 조회 결과가 이 no-op 함수로 변경되므로
    # 다음 반복부터 기존 연결이 중지된다.
    # ------------------------------------------------------------
    old_patch_function_names = (
        "_v171_install_excel_buttons",
        "_v171_export_excel",

        prefix + "_v185_install",
        prefix + "_v189_bind_excel_button",
        prefix + "_v189_excel_button_watch",
        prefix + "_v190_install_excel_button",
        prefix + "_v190_button_watch",
        prefix + "_v197_connect_excel_buttons",
        prefix + "_v199_bind_excel_button",
        prefix + "_v199_bind_excel_buttons",
    )

    for function_name in old_patch_function_names:
        if function_name in namespace:
            namespace[
                function_name
            ] = disabled_old_excel_patch

    # ------------------------------------------------------------
    # 원본 산출조서 생성 함수는 절대 덮어쓰지 않는다.
    #
    # 최종본210 실패 원인:
    #   electric_v197_safe_excel_export 등이 두 파일 저장 함수로
    #   덮어써진 뒤, v199_run_export가 같은 함수를 호출하면서
    #   실제 산출조서 파일을 만들지 못했다.
    #
    # 최종본213에서는 사용자 버튼의 최종 진입점만 교체하고
    # v184/v190/v192/v193/v197 원본 함수는 그대로 보존한다.
    # ------------------------------------------------------------
    export_function_names = (
        prefix + "_export_to_excel",
        prefix + "_v199_export_to_excel",
    )

    root_widget = namespace.get("root")

    def install_excel_button():
        # 모든 기존 Excel 내보내기 진입점을 두 파일 저장 함수로 교체
        for function_name in export_function_names:
            namespace[
                function_name
            ] = two_file_export_command

        # 이름으로 등록된 Excel 버튼 처리
        for button_name in (
            "btn_excel",
            "excel_button",
            "btn_export_excel",
            "button_export_excel",
            "btn_excel_export",
            "export_excel_button",
        ):
            button = namespace.get(button_name)

            if button is None:
                continue

            try:
                button.config(
                    command=two_file_export_command
                )
            except Exception:
                pass

        # 실제 화면에 배치된 모든 Excel 버튼 처리
        for widget in _v213_walk_widgets(
            root_widget
        ):
            try:
                widget_class = widget.winfo_class()
            except Exception:
                continue

            if widget_class not in (
                "Button",
                "TButton",
            ):
                continue

            try:
                widget_text = str(
                    widget.cget("text")
                ).replace(" ", "")
            except Exception:
                continue

            if "엑셀" not in widget_text:
                continue

            if not any(
                keyword in widget_text
                for keyword in (
                    "내려받기",
                    "다운로드",
                    "저장",
                    "내보내기",
                    "출력",
                )
            ):
                continue

            try:
                widget.config(
                    command=two_file_export_command
                )
            except Exception:
                pass

    def permanent_excel_button_watch():
        try:
            install_excel_button()
        except Exception:
            pass

        try:
            if (
                root_widget is not None
                and root_widget.winfo_exists()
            ):
                namespace[
                    "_v213_excel_watch_after_id"
                ] = root_widget.after(
                    250,
                    permanent_excel_button_watch
                )
        except Exception:
            pass

    # 같은 공종에 감시 루프가 중복 설치되는 것을 방지
    if namespace.get(
        "_v213_excel_watch_installed",
        False
    ):
        install_excel_button()
        return

    namespace[
        "_v213_excel_watch_installed"
    ] = True

    # 즉시 버튼 연결
    install_excel_button()

    if root_widget is not None:
        # 기존 watcher가 초기화 과정에서 한 번 더 실행할 수 있으므로
        # 짧은 지연 재설치를 함께 수행한다.
        for delay in (
            1,
            10,
            50,
            100,
            200,
            350,
            500,
            700,
            1000,
            1500,
            2000,
            3000,
            5000,
            8000,
            12000,
            15000,
        ):
            try:
                root_widget.after(
                    delay,
                    install_excel_button
                )
            except Exception:
                pass

        # 이전 버전의 무한 감시보다 나중에 실행되도록
        # v208 감시 루프를 지속적으로 유지한다.
        try:
            root_widget.after(
                125,
                permanent_excel_button_watch
            )
        except Exception:
            pass


# ================================================================
# 최종본213 Excel 두 개 파일 완전 분리 저장 패치 끝
# ================================================================


def _create_trade_instance(trade_name):
    """원본 프로그램 전체를 별도 globals dictionary에서 실행."""
    if trade_name in trade_instances:
        return trade_instances[trade_name]

    source = _extract_trade_source(trade_name)
    namespace = {
        "__name__": f"__trade_instance_{trade_name}__",
        "__file__": os.path.abspath(__file__),
        "master_root": master_root,
        # 공종의 open_selected_supervision() 실행 시 참조하는 전역 상태를
        # 함수 호출 전에 각 공종 namespace 안에 먼저 생성합니다.
        "current_login_mode": current_login_mode,
        "current_supervision_type": None,
        "FORCED_SUPERVISION_TYPE": trade_name,
        # 원본 소스가 root를 만들기 전 참조하더라도 KeyError가 나지 않도록
        # 안전한 Toplevel을 미리 넣습니다. 원본 코드의 root 대입이 이를 정상 교체합니다.
        "root": tk.Toplevel(master_root),
        # 각 공종 원본 내부에서 사용하는 공통 선택변수를 실행 전에 미리 생성
        # (공종 간 공유가 아니라 해당 namespace 안에서만 존재)
        "electric_var": tk.BooleanVar(master=master_root, value=False),
        "communication_var": tk.BooleanVar(master=master_root, value=False),
        "fire_var": tk.BooleanVar(master=master_root, value=False),
    }
    namespace["root"].withdraw()

    # 원본 파일을 별도 namespace에서 실행한다.
    exec(compile(source, f"<{trade_name} 독립 인스턴스>", "exec"), namespace, namespace)
    namespace["__original_source_for_view"] = source
    trade_root = namespace["root"]
    trade_root.title(f"서울대 {trade_name}공사 감리 산출 프로그램_최종본107")
    trade_root.protocol("WM_DELETE_WINDOW", _return_to_selection)
    # 최종본71: 공종별 UI 및 화면동일형 Excel 내보내기 적용
    _v71_apply_runtime_patch(namespace, trade_name)


    # 원본 내부 로그인/공종선택 화면은 사용하지 않고 숨긴다.
    try:
        namespace["login_frame"].pack_forget()
        namespace["selection_frame"].pack_forget()
    except Exception:
        pass

    # 외부 로그인 정보와 연결
    namespace["current_login_mode"] = current_login_mode
    namespace["current_supervision_type"] = trade_name

    # 내부 공종 선택 변수도 해당 공종 하나만 선택
    namespace["electric_var"].set(trade_name == "전기")
    namespace["communication_var"].set(trade_name == "통신")
    namespace["fire_var"].set(trade_name == "소방")

    # 기존 실행 함수로 해당 공종의 전체 화면을 한 번만 초기화
    # 공종별로 분리된 open_selected_supervision을 정확히 호출
    _open_func_name = {
        "전기": "electric_open_selected_supervision",
        "통신": "communication_open_selected_supervision",
        "소방": "fire_open_selected_supervision",
    }[trade_name]
    namespace[_open_func_name]()

    # 최종본213: 화면 초기화 완료 후 Excel 두 파일 분리 저장 설치
    try:
        _v213_install_trade_patch(
            namespace,
            trade_name
        )
    except Exception:
        try:
            import traceback as _v206_traceback
            _v206_error_path = os.path.join(
                os.path.dirname(
                    os.path.abspath(__file__)
                ),
                "최종본213_오류.log"
            )
            with open(
                _v206_error_path,
                "a",
                encoding="utf-8"
            ) as _v206_error_file:
                _v206_error_file.write(
                    _v206_traceback.format_exc()
                    + "\n"
                )
        except Exception:
            pass

    # =====================================================================
    if trade_name == "소방":
        try:
            import re
            
            # 동적으로 추가되는 UI를 지속적으로 추적하여 제거하는 패치 함수
            def remove_unwanted_ui():
                # 1. 화면 내의 모든 위젯을 재귀적으로 스캔하여 대상 표만 정확히 파괴
                def hide_target_frames(widget):
                    try:
                        # 라벨 프레임의 텍스트가 정확히 일치하는 경우만 도려냄 (위에 있는 사업 1 표는 유지됨)
                        if widget.winfo_class() in ('Labelframe', 'LabelFrame', 'TLabelframe'):
                            if widget.cget("text").strip() == "실비정액가산방식 대가 산출":
                                widget.pack_forget()
                                widget.grid_forget()
                    except Exception:
                        pass
                    
                    # 자식 위젯들에 대해 끝까지 파고들며 탐색
                    for child in widget.winfo_children():
                        hide_target_frames(child)

                # 메인 창부터 스캔 시작
                hide_target_frames(trade_root)
                    
                # 2. '감리사항' 중박스 내 문구 제거
                if "label_required_supervisor_display" in namespace:
                    for lbl in namespace["label_required_supervisor_display"]:
                        if lbl is not None:
                            try:
                                current_text = lbl.cget("text")
                                new_text = current_text.replace("필요 감리원", "").replace("비상주 배치비율[%]", "")
                                new_text = re.sub(r'초급 이상\([^\)]+\)', '', new_text)
                                new_text = re.sub(r'\(전력기술관리법[^\)]*\)', '', new_text)
                                new_text = re.sub(r'\(소방시설공사업법[^\)]*\)', '', new_text)
                                new_text = re.sub(r'\(정보통신공사업법[^\)]*\)', '', new_text)
                                new_text = new_text.replace("  ", " ").strip()
                                lbl.config(text=new_text)
                            except:
                                pass

            # 사업 탭이 추가될 때마다 즉시 잉여 표를 날려버리도록 기존 함수 후킹
            original_add_project = namespace.get("add_project")
            if original_add_project:
                def patched_add_project(*args, **kwargs):
                    result = original_add_project(*args, **kwargs)
                    trade_root.after(50, remove_unwanted_ui) 
                    return result
                namespace["add_project"] = patched_add_project
                
            # 계산 업데이트 시 표가 다시 나타나지 않도록 후킹
            original_check = namespace.get("check_required_supervisor")
            if original_check:
                def patched_check(idx):
                    original_check(idx) 
                    trade_root.after(10, remove_unwanted_ui) 
                namespace["check_required_supervisor"] = patched_check
                
            # 창이 최초로 열릴 때 1회 즉시 실행
            trade_root.after(100, remove_unwanted_ui)

        except Exception as e:
            pass

    # 원본 공종선택 버튼은 외부 런처의 공종선택으로 연결
    try:
        namespace["btn_back"].config(command=_return_to_selection)
    except Exception:
        pass

    # 창을 완전히 숨긴 상태로 캐시
    try:
        trade_root.withdraw()
    except Exception:
        pass

    trade_instances[trade_name] = namespace
    return namespace

def _open_selected_trade():
    global active_trade
    
    if not electric_var.get() and not communication_var.get() and not fire_var.get():
        messagebox.showwarning("공종 선택", "실행할 공종을 선택하세요.")
        return
        
    if electric_var.get():
        selected = "전기"
    elif communication_var.get():
        selected = "통신"
    else:
        selected = "소방"
        
    try:
        ns = _create_trade_instance(selected)
    except Exception as exc:
        messagebox.showerror(
            "공종 실행 오류",
            f"{selected} 공종 프로그램을 초기화하는 중 오류가 발생했습니다.\n\n{exc}"
        )
        return
        
    active_trade = selected
    
    try:
        ns["current_login_mode"] = current_login_mode
        ns["current_supervision_type"] = selected
        ns["btn_back"].config(command=_return_to_selection)
    except Exception:
        pass
        
    selection_frame.pack_forget()
    master_root.withdraw()
    
    trade_root = ns["root"]
    trade_root.title(f"서울대 {selected}공사 감리 자동산출 프로그램_최종본107")
    trade_root.deiconify()
    trade_root.lift()
    trade_root.focus_force()
    _center_window(trade_root)

def _attempt_login(event=None):
    global current_login_mode
    user_pw = ""
    admin_pw = ""
    
    input_user = pwd_entry.get()
    input_admin = admin_pwd_entry.get()
    
    if input_admin == admin_pw:
        current_login_mode = "admin"
    elif input_user == user_pw:
        current_login_mode = "user"
    else:
        messagebox.showerror("오류", "비밀번호가 일치하지 않습니다.")
        return
        
    pwd_entry.delete(0, tk.END)
    admin_pwd_entry.delete(0, tk.END)
    _show_selection()

def _toggle_password(entry, button):
    if entry.cget("show") == "*":
        entry.config(show="")
        button.config(text="가림 설정")
    else:
        entry.config(show="*")
        button.config(text="가림 해제")

