# =====================================================================
# [최종본110] 라디오버튼 사용자 선택 보호 및 암호 자동입력
# =====================================================================

_v110_radio_values = {}
_v110_radio_variables = {}
_v110_radio_traces = {}
_v110_radio_busy = set()
_v110_radio_pending = set()

_V110_RADIO_BINDTAG = "_V110_RADIO_FIRST"
_V110_LOGIN_BINDTAG = "_V110_LOGIN_FIRST"


def _v110_walk_widgets(parent):
    """부모 아래의 모든 위젯을 재귀적으로 순회한다."""
    try:
        children = parent.winfo_children()
    except Exception:
        children = []

    for child in children:
        yield child
        yield from _v110_walk_widgets(child)


def _v110_is_radiobutton(widget):
    try:
        return str(widget.winfo_class()) in (
            "Radiobutton",
            "TRadiobutton",
        )
    except Exception:
        return False


def _v110_is_button(widget):
    try:
        return str(widget.winfo_class()) in (
            "Button",
            "TButton",
        )
    except Exception:
        return False


def _v110_radio_variable_name(widget):
    try:
        return str(widget.cget("variable")).strip()
    except Exception:
        return ""


def _v110_radio_value(widget):
    try:
        return str(widget.cget("value"))
    except Exception:
        return ""


def _v110_radio_enabled(widget):
    try:
        state = str(widget.cget("state")).lower()
        return state not in ("disabled",)
    except Exception:
        return True


def _v110_restore_radio(variable_name):
    """
    자동 계산이나 trace 함수가 라디오 값을 기본값으로 바꾸면
    사용자가 마지막으로 직접 클릭한 값으로 복원한다.
    """
    _v110_radio_pending.discard(variable_name)

    if variable_name in _v110_radio_busy:
        return

    if variable_name not in _v110_radio_values:
        return

    variable = _v110_radio_variables.get(variable_name)

    if variable is None:
        return

    expected = str(
        _v110_radio_values[variable_name]
    )

    try:
        current = str(variable.get())
    except Exception:
        return

    if current == expected:
        return

    try:
        _v110_radio_busy.add(variable_name)
        variable.set(expected)
    except Exception:
        pass
    finally:
        _v110_radio_busy.discard(variable_name)


def _v110_schedule_radio_restore(variable_name):
    """중복 예약을 막으면서 사용자 선택값 복원을 예약한다."""
    if variable_name in _v110_radio_busy:
        return

    if variable_name not in _v110_radio_values:
        return

    if variable_name in _v110_radio_pending:
        return

    _v110_radio_pending.add(variable_name)

    try:
        root.after_idle(
            lambda name=variable_name:
                _v110_restore_radio(name)
        )
    except Exception:
        _v110_radio_pending.discard(variable_name)


def _v110_install_variable_trace(widget, variable_name):
    """클릭한 라디오버튼의 Tcl 변수에 변경 감시를 설치한다."""
    if not variable_name:
        return

    if variable_name in _v110_radio_variables:
        return

    try:
        variable = tk.StringVar(
            master=widget,
            name=variable_name
        )

        _v110_radio_variables[variable_name] = variable

        trace_id = variable.trace_add(
            "write",
            lambda *args, name=variable_name:
                _v110_schedule_radio_restore(name)
        )

        _v110_radio_traces[variable_name] = trace_id

    except Exception:
        pass


def _v110_radio_button_press(event):
    """
    기존 프로그램의 Button-1 이벤트보다 먼저 실행된다.

    따라서 기존 이벤트가 var.set()을 실행하기 전에
    사용자가 누른 값을 기억할 수 있다.
    """
    widget = getattr(event, "widget", None)

    if widget is None:
        return

    if not _v110_is_radiobutton(widget):
        return

    if not _v110_radio_enabled(widget):
        return

    variable_name = _v110_radio_variable_name(widget)
    clicked_value = _v110_radio_value(widget)

    if not variable_name:
        return

    # 가장 중요한 부분:
    # 기존 라디오 이벤트가 실행되기 전에 사용자 선택값을 기록한다.
    _v110_radio_values[variable_name] = clicked_value

    _v110_install_variable_trace(
        widget,
        variable_name
    )

    # 기존 클릭 이벤트와 각종 계산 콜백이 끝나는 시점마다 재확인
    delays = (
        0,
        1,
        10,
        30,
        50,
        100,
        200,
        500,
        1000,
        2000,
    )

    for delay in delays:
        try:
            root.after(
                delay,
                lambda name=variable_name:
                    _v110_restore_radio(name)
            )
        except Exception:
            pass

    # 여기서는 "break"를 반환하지 않는다.
    # 기존 프로그램의 라디오버튼 계산 이벤트도 계속 실행되어야 한다.
    return None


def _v110_force_clicked_radio(event):
    """
    ButtonRelease 이후 사용자가 실제 누른 버튼값을 최종 확정한다.
    """
    widget = getattr(event, "widget", None)

    if widget is None:
        return

    if not _v110_is_radiobutton(widget):
        return

    if not _v110_radio_enabled(widget):
        return

    variable_name = _v110_radio_variable_name(widget)
    clicked_value = _v110_radio_value(widget)

    if not variable_name:
        return

    _v110_radio_values[variable_name] = clicked_value
    _v110_install_variable_trace(widget, variable_name)

    variable = _v110_radio_variables.get(variable_name)

    if variable is not None:
        try:
            _v110_radio_busy.add(variable_name)
            variable.set(clicked_value)
        except Exception:
            pass
        finally:
            _v110_radio_busy.discard(variable_name)

    for delay in (0, 10, 50, 100, 300, 1000):
        try:
            root.after(
                delay,
                lambda name=variable_name:
                    _v110_restore_radio(name)
            )
        except Exception:
            pass

    return None


def _v110_add_radio_bindtag(widget):
    """
    사용자 선택 기록 이벤트가 기존 widget 바인딩보다 먼저 실행되도록
    전용 bindtag를 맨 앞에 추가한다.
    """
    if not _v110_is_radiobutton(widget):
        return

    try:
        current_tags = tuple(widget.bindtags())

        if _V110_RADIO_BINDTAG in current_tags:
            return

        new_tags = (
            _V110_RADIO_BINDTAG,
        ) + current_tags

        widget.bindtags(new_tags)

    except Exception:
        pass


def _v110_fill_password_entries():
    """
    로그인 화면의 암호 입력칸에 123을 자동 입력한다.

    사용자는 암호를 입력하지 않고 로그인 버튼만 누르면 된다.
    """
    changed = 0

    for widget in _v110_walk_widgets(root):
        try:
            widget_class = str(widget.winfo_class())

            if widget_class not in (
                "Entry",
                "TEntry",
            ):
                continue

            show_value = str(
                widget.cget("show")
            )

            # 암호 입력칸은 일반적으로 show="*" 등으로 설정되어 있다.
            if not show_value:
                continue

            try:
                widget.config(state="normal")
            except Exception:
                pass

            widget.delete(0, tk.END)
            widget.insert(0, "123")
            changed += 1

        except Exception:
            pass

    return changed


def _v110_login_button_press(event):
    """
    로그인 버튼의 기존 command가 실행되기 전에 암호 123을 자동 입력한다.
    """
    widget = getattr(event, "widget", None)

    if widget is None:
        return

    if not _v110_is_button(widget):
        return

    try:
        button_text = str(
            widget.cget("text")
        ).strip()
    except Exception:
        return

    normalized_text = button_text.replace(
        " ",
        ""
    )

    if "로그인" not in normalized_text:
        return

    _v110_fill_password_entries()

    # 프로그램이 StringVar를 늦게 읽는 경우를 위해 한 번 더 입력
    try:
        root.after_idle(
            _v110_fill_password_entries
        )
    except Exception:
        pass

    return None


def _v110_add_login_bindtag(widget):
    """로그인 버튼에 기존 command보다 먼저 실행되는 bindtag를 추가한다."""
    if not _v110_is_button(widget):
        return

    try:
        button_text = str(
            widget.cget("text")
        ).replace(" ", "")

        if "로그인" not in button_text:
            return

        current_tags = tuple(
            widget.bindtags()
        )

        if _V110_LOGIN_BINDTAG in current_tags:
            return

        widget.bindtags(
            (_V110_LOGIN_BINDTAG,) + current_tags
        )

    except Exception:
        pass


def _v110_scan_widgets():
    """
    현재 존재하는 모든 위젯에 보호 기능을 적용한다.

    화면 전환 후 새로 생성되는 위젯을 위해 주기적으로 다시 검사한다.
    """
    try:
        for widget in _v110_walk_widgets(root):
            if _v110_is_radiobutton(widget):
                _v110_add_radio_bindtag(widget)

            elif _v110_is_button(widget):
                _v110_add_login_bindtag(widget)

    except Exception:
        pass

    try:
        root.after(
            500,
            _v110_scan_widgets
        )
    except Exception:
        pass


def _v110_install_runtime_patch():
    """최종본110 런타임 보호 기능 설치."""
    try:
        # 라디오버튼 기존 이벤트보다 먼저 실행
        root.bind_class(
            _V110_RADIO_BINDTAG,
            "<ButtonPress-1>",
            _v110_radio_button_press,
            add="+"
        )

        root.bind_class(
            _V110_RADIO_BINDTAG,
            "<ButtonRelease-1>",
            _v110_force_clicked_radio,
            add="+"
        )

        # 로그인 버튼 기존 command보다 먼저 실행
        root.bind_class(
            _V110_LOGIN_BINDTAG,
            "<ButtonPress-1>",
            _v110_login_button_press,
            add="+"
        )

        _v110_scan_widgets()

        print(
            "[최종본110] 라디오버튼 선택값 보호 기능 적용 완료"
        )

        print(
            "[최종본110] 로그인 암호 자동입력 기능 적용 완료"
        )

    except Exception as error:
        print(
            "[최종본110] 보호 기능 설치 오류:",
            error
        )


_v110_install_runtime_patch()

